/// Apply CREATE_NO_WINDOW flag on Windows to prevent console popups.
#[cfg(target_os = "windows")]
fn hide_window(cmd: &mut Command) -> &mut Command {
    use std::os::windows::process::CommandExt;
    cmd.creation_flags(0x08000000)
}

#[cfg(not(target_os = "windows"))]
fn hide_window(cmd: &mut Command) -> &mut Command {
    cmd
}

/// Same helper for std::process::Command (sync).
#[cfg(target_os = "windows")]
fn hide_window_sync(cmd: &mut std::process::Command) -> &mut std::process::Command {
    use std::os::windows::process::CommandExt;
    cmd.creation_flags(0x08000000)
}

#[cfg(not(target_os = "windows"))]
fn hide_window_sync(cmd: &mut std::process::Command) -> &mut std::process::Command {
    cmd
}

pub const BUILD_CANCELED_MARKER: &str = "CK_BUILD_CANCELED";

/// Returned build/upload logs are evidence and user-facing diagnostics, but
/// they must not retain an unbounded copy of output that has already been
/// streamed to the frontend. Keep the stable identity at the start and the
/// final error/success/artifact details at the end.
pub const BOUNDED_LOG_TRUNCATION_MARKER: &str =
    "\n[CK LOG TRUNCATED: middle output omitted; live stream was not affected]\n";
pub const COMPILE_FULL_LOG_MAX_BYTES: usize = 2 * 1024 * 1024;
pub const UPLOAD_FULL_LOG_MAX_BYTES: usize = 1024 * 1024;
/// Stable, machine-readable prefixes for cold-build timing evidence.  Keep the
/// numeric payload as an integer millisecond count followed by `ms`; Desktop
/// diagnostics parse these exact prefixes and reject lookalike compiler text.
pub const TIMING_RUNTIME_TOOL_PREFLIGHT_PREFIX: &str = "[Timing DIAG] Runtime tool preflight: ";
pub const TIMING_ARDUINO_CLI_CHILD_WALL_PREFIX: &str = "[Timing DIAG] Arduino CLI child wall: ";
pub const TIMING_DEPENDENCY_ARTIFACT_SEAL_PREFIX: &str = "[Timing DIAG] Dependency/artifact seal: ";
pub const TIMING_NATIVE_BASELINE_CAPTURE_COMMIT_PREFIX: &str =
    "[Timing DIAG] NativeRelink baseline capture+commit: ";
pub const TIMING_BUILD_META_SNAPSHOT_PREFIX: &str = "[Timing DIAG] BuildMeta/core snapshot: ";
pub const ESP32_LIBRARY_RELINK_EVIDENCE_PREFIX: &str =
    "[DIAG] ESP32 library NativeRelink evidence: ";
pub const TIMING_POST_BUILD_SNAPSHOT_PREFIX: &str = "[Timing DIAG] Post-build cache snapshot: ";
const COMPILE_FULL_LOG_HEAD_BYTES: usize = 256 * 1024;
const UPLOAD_FULL_LOG_HEAD_BYTES: usize = 128 * 1024;

/// UTF-8 safe, byte-bounded head+tail text retention.
///
/// `push_str` never lets the retained head/tail lengths exceed their fixed
/// budgets, even for one enormous line. `rendered` inserts exactly one marker
/// when middle bytes were discarded and is always at most `max_bytes` long.
#[derive(Clone, Debug)]
pub struct BoundedLog {
    head: String,
    tail: String,
    max_bytes: usize,
    head_limit: usize,
    tail_limit: usize,
    total_bytes_seen: u64,
    forced_truncated: bool,
}

impl BoundedLog {
    pub fn new(max_bytes: usize, requested_head_bytes: usize) -> Self {
        assert!(
            max_bytes >= BOUNDED_LOG_TRUNCATION_MARKER.len(),
            "bounded log limit must fit its truncation marker"
        );
        let payload_budget = max_bytes.saturating_sub(BOUNDED_LOG_TRUNCATION_MARKER.len());
        let head_limit = requested_head_bytes.min(payload_budget);
        let tail_limit = payload_budget.saturating_sub(head_limit);
        Self {
            // Grow lazily. Preallocating the maximum would turn a safety ceiling
            // into a permanent multi-megabyte cost for ordinary short builds.
            head: String::new(),
            tail: String::new(),
            max_bytes,
            head_limit,
            tail_limit,
            total_bytes_seen: 0,
            forced_truncated: false,
        }
    }

    pub fn push_str(&mut self, mut text: &str) {
        self.total_bytes_seen = self
            .total_bytes_seen
            .saturating_add(u64::try_from(text.len()).unwrap_or(u64::MAX));

        if !self.forced_truncated && self.head.len() < self.head_limit {
            let take = utf8_prefix_len(text, self.head_limit - self.head.len());
            self.head.push_str(&text[..take]);
            text = &text[take..];
        }
        if text.is_empty() || self.tail_limit == 0 {
            return;
        }

        if text.len() >= self.tail_limit {
            let start = utf8_suffix_start(text, self.tail_limit);
            self.tail.clear();
            self.tail.push_str(&text[start..]);
            return;
        }

        let existing_budget = self.tail_limit - text.len();
        if self.tail.len() > existing_budget {
            let minimum_drop = self.tail.len() - existing_budget;
            let drop = utf8_boundary_at_or_after(&self.tail, minimum_drop);
            self.tail.drain(..drop);
        }
        self.tail.push_str(text);
    }

    pub fn push_line(&mut self, line: &str) {
        self.push_str(line);
        self.push_str("\n");
    }

    pub fn is_truncated(&self) -> bool {
        self.forced_truncated
            || self.total_bytes_seen
                > u64::try_from(self.head.len().saturating_add(self.tail.len())).unwrap_or(u64::MAX)
    }

    pub fn mark_truncated(&mut self) {
        self.forced_truncated = true;
    }

    pub fn retained_bytes(&self) -> usize {
        self.head.len().saturating_add(self.tail.len())
    }

    pub fn rendered(&self) -> String {
        let truncated = self.is_truncated();
        let marker = if truncated {
            BOUNDED_LOG_TRUNCATION_MARKER
        } else {
            ""
        };
        let mut out = String::with_capacity(
            self.head
                .len()
                .saturating_add(marker.len())
                .saturating_add(self.tail.len())
                .min(self.max_bytes),
        );
        out.push_str(&self.head);
        out.push_str(marker);
        out.push_str(&self.tail);
        debug_assert!(out.len() <= self.max_bytes);
        out
    }

    pub fn into_string(self) -> String {
        self.rendered()
    }
}

fn utf8_prefix_len(text: &str, max_bytes: usize) -> usize {
    let mut end = text.len().min(max_bytes);
    while end > 0 && !text.is_char_boundary(end) {
        end -= 1;
    }
    end
}

fn utf8_boundary_at_or_after(text: &str, minimum: usize) -> usize {
    let mut index = minimum.min(text.len());
    while index < text.len() && !text.is_char_boundary(index) {
        index += 1;
    }
    index
}

fn utf8_suffix_start(text: &str, max_bytes: usize) -> usize {
    utf8_boundary_at_or_after(text, text.len().saturating_sub(max_bytes))
}

fn contains_ascii_case_insensitive(text: &str, needle: &[u8]) -> bool {
    text.as_bytes()
        .windows(needle.len())
        .any(|window| window.eq_ignore_ascii_case(needle))
}

const MAX_COMPILE_SUMMARY_LINES: usize = 128;
const MAX_COMPILE_SUMMARY_LINE_BYTES: usize = 4096;
const PROCESS_STREAM_READ_CHUNK_BYTES: usize = 8 * 1024;
const PROCESS_STREAM_RECORD_MAX_BYTES: usize = 16 * 1024;
const PROCESS_STREAM_CHANNEL_RECORDS: usize = 256;
const MANAGED_COMMAND_STREAM_MAX_BYTES: usize = 2 * 1024 * 1024;
const MANAGED_COMMAND_STREAM_HEAD_BYTES: usize = 256 * 1024;
const MANAGED_CANCEL_PROCESS_WAIT_TIMEOUT: std::time::Duration = std::time::Duration::from_secs(5);
const MANAGED_CANCEL_PIPE_DRAIN_TIMEOUT: std::time::Duration = std::time::Duration::from_secs(3);

#[derive(Debug)]
struct ProcessOutputRecord {
    text: String,
    line_end: bool,
}

/// Converts arbitrary process bytes into UTF-8-safe records without ever
/// buffering an unbounded physical line. Newline-delimited output remains one
/// record per line; a malicious/noisy line is split into bounded continuation
/// records while preserving a small suffix until its next record.
#[derive(Debug, Default)]
struct BoundedProcessOutputFramer {
    pending: Vec<u8>,
}

impl BoundedProcessOutputFramer {
    fn push_chunk(&mut self, chunk: &[u8]) -> Vec<ProcessOutputRecord> {
        let mut records = Vec::new();
        for byte in chunk {
            if *byte == b'\n' {
                records.push(self.take_record(true, self.pending.len()));
                continue;
            }
            self.pending.push(*byte);
            if self.pending.len() >= PROCESS_STREAM_RECORD_MAX_BYTES {
                let split = continuation_split_index(&self.pending);
                if split > 0 {
                    records.push(self.take_record(false, split));
                }
            }
        }
        records
    }

    fn finish(&mut self) -> Option<ProcessOutputRecord> {
        (!self.pending.is_empty()).then(|| self.take_record(true, self.pending.len()))
    }

    fn take_record(&mut self, line_end: bool, split: usize) -> ProcessOutputRecord {
        let bytes = self.pending.drain(..split).collect::<Vec<_>>();
        let mut text = String::from_utf8_lossy(&bytes).into_owned();
        if text.len() > PROCESS_STREAM_RECORD_MAX_BYTES {
            let end = utf8_prefix_len(&text, PROCESS_STREAM_RECORD_MAX_BYTES);
            text.truncate(end);
        }
        if line_end && text.ends_with('\r') {
            text.pop();
        }
        ProcessOutputRecord { text, line_end }
    }

    #[cfg(test)]
    fn pending_bytes(&self) -> usize {
        self.pending.len()
    }
}

fn continuation_split_index(bytes: &[u8]) -> usize {
    debug_assert!(bytes.len() >= PROCESS_STREAM_RECORD_MAX_BYTES);
    match std::str::from_utf8(bytes) {
        Ok(text) => {
            let mut split = text.len().saturating_sub(1);
            while split > 0 && !text.is_char_boundary(split) {
                split -= 1;
            }
            split
        }
        Err(error) if error.error_len().is_none() && error.valid_up_to() > 0 => error.valid_up_to(),
        Err(_) => bytes.len().saturating_sub(1),
    }
}

async fn forward_bounded_process_output<R>(
    mut reader: R,
    tx: tokio::sync::mpsc::Sender<(ProcessOutputRecord, bool)>,
    is_stderr: bool,
) where
    R: AsyncRead + Unpin,
{
    let mut framer = BoundedProcessOutputFramer::default();
    let mut chunk = [0u8; PROCESS_STREAM_READ_CHUNK_BYTES];
    loop {
        match reader.read(&mut chunk).await {
            Ok(0) => break,
            Ok(read) => {
                for record in framer.push_chunk(&chunk[..read]) {
                    if tx.send((record, is_stderr)).await.is_err() {
                        return;
                    }
                }
            }
            Err(error) => {
                let record = ProcessOutputRecord {
                    text: format!("[CK] process output read failed: {error}"),
                    line_end: true,
                };
                let _ = tx.send((record, is_stderr)).await;
                return;
            }
        }
    }
    if let Some(record) = framer.finish() {
        let _ = tx.send((record, is_stderr)).await;
    }
}

#[derive(Debug)]
struct BoundedByteCapture {
    head: Vec<u8>,
    tail: Vec<u8>,
    head_limit: usize,
    tail_limit: usize,
    total_bytes_seen: u64,
}

impl BoundedByteCapture {
    fn new(max_bytes: usize, requested_head_bytes: usize) -> Self {
        let head_limit = requested_head_bytes.min(max_bytes);
        Self {
            head: Vec::new(),
            tail: Vec::new(),
            head_limit,
            tail_limit: max_bytes - head_limit,
            total_bytes_seen: 0,
        }
    }

    fn push(&mut self, mut bytes: &[u8]) {
        self.total_bytes_seen = self
            .total_bytes_seen
            .saturating_add(u64::try_from(bytes.len()).unwrap_or(u64::MAX));
        if self.head.len() < self.head_limit {
            let take = bytes.len().min(self.head_limit - self.head.len());
            self.head.extend_from_slice(&bytes[..take]);
            bytes = &bytes[take..];
        }
        if bytes.is_empty() || self.tail_limit == 0 {
            return;
        }
        if bytes.len() >= self.tail_limit {
            self.tail.clear();
            self.tail
                .extend_from_slice(&bytes[bytes.len() - self.tail_limit..]);
            return;
        }
        let existing_budget = self.tail_limit - bytes.len();
        if self.tail.len() > existing_budget {
            let drop = self.tail.len() - existing_budget;
            self.tail.drain(..drop);
        }
        self.tail.extend_from_slice(bytes);
    }

    fn retained_bytes(&self) -> usize {
        self.head.len().saturating_add(self.tail.len())
    }

    fn is_truncated(&self) -> bool {
        self.total_bytes_seen > u64::try_from(self.retained_bytes()).unwrap_or(u64::MAX)
    }

    fn total_bytes_seen(&self) -> u64 {
        self.total_bytes_seen
    }

    fn tail_excerpt(&self, max_bytes: usize) -> String {
        let start = self.tail.len().saturating_sub(max_bytes);
        String::from_utf8_lossy(&self.tail[start..]).into_owned()
    }

    fn into_bytes(mut self) -> Vec<u8> {
        debug_assert!(!self.is_truncated());
        self.head.append(&mut self.tail);
        self.head
    }
}

async fn read_bounded_command_stream<R>(mut reader: R) -> std::io::Result<BoundedByteCapture>
where
    R: AsyncRead + Unpin,
{
    let mut capture = BoundedByteCapture::new(
        MANAGED_COMMAND_STREAM_MAX_BYTES,
        MANAGED_COMMAND_STREAM_HEAD_BYTES,
    );
    let mut chunk = [0u8; PROCESS_STREAM_READ_CHUNK_BYTES];
    loop {
        let read = reader.read(&mut chunk).await?;
        if read == 0 {
            break;
        }
        capture.push(&chunk[..read]);
    }
    Ok(capture)
}

fn read_bounded_command_stream_sync<R>(mut reader: R) -> std::io::Result<BoundedByteCapture>
where
    R: std::io::Read,
{
    let mut capture = BoundedByteCapture::new(
        MANAGED_COMMAND_STREAM_MAX_BYTES,
        MANAGED_COMMAND_STREAM_HEAD_BYTES,
    );
    let mut chunk = [0u8; PROCESS_STREAM_READ_CHUNK_BYTES];
    loop {
        let read = reader.read(&mut chunk)?;
        if read == 0 {
            break;
        }
        capture.push(&chunk[..read]);
    }
    Ok(capture)
}

#[derive(Debug, Default)]
struct CompileLogEvidence {
    warning_count: u64,
    summary_lines: VecDeque<String>,
    invalid_character: bool,
    current_line_warning: bool,
    current_line_summary: bool,
    current_line_prefix: String,
    scan_overlap: String,
}

impl CompileLogEvidence {
    fn observe_line(&mut self, line: &str) {
        self.observe_record(line, true);
    }

    fn observe_record(&mut self, text: &str, line_end: bool) {
        self.current_line_warning |= contains_ascii_case_insensitive(text, b"warning:")
            || split_pattern_matches(&self.scan_overlap, text, b"warning:");
        if contains_ascii_case_insensitive(text, b"invalid character")
            || split_pattern_matches(&self.scan_overlap, text, b"invalid character")
        {
            self.invalid_character = true;
        }
        self.current_line_summary |=
            is_size_or_summary_line(text) || split_summary_marker_matches(&self.scan_overlap, text);

        if self.current_line_prefix.len() < MAX_COMPILE_SUMMARY_LINE_BYTES {
            let take = utf8_prefix_len(
                text,
                MAX_COMPILE_SUMMARY_LINE_BYTES - self.current_line_prefix.len(),
            );
            self.current_line_prefix.push_str(&text[..take]);
        }
        self.scan_overlap = utf8_suffix(text, 128).to_string();

        if !line_end {
            return;
        }
        if self.current_line_warning {
            self.warning_count = self.warning_count.saturating_add(1);
        }
        if self.current_line_summary {
            if self.summary_lines.len() == MAX_COMPILE_SUMMARY_LINES {
                self.summary_lines.pop_front();
            }
            self.summary_lines
                .push_back(std::mem::take(&mut self.current_line_prefix));
        } else {
            self.current_line_prefix.clear();
        }
        self.current_line_warning = false;
        self.current_line_summary = false;
        self.scan_overlap.clear();
    }

    fn observe_text(&mut self, text: &str) {
        for line in text.lines() {
            self.observe_line(line);
        }
    }

    fn summary_lines(&self) -> Vec<String> {
        self.summary_lines.iter().cloned().collect()
    }
}

fn utf8_suffix(text: &str, max_bytes: usize) -> &str {
    let start = utf8_suffix_start(text, max_bytes);
    &text[start..]
}

fn split_pattern_matches(previous: &str, current: &str, pattern: &[u8]) -> bool {
    if previous.is_empty() || current.is_empty() {
        return false;
    }
    let current_end = utf8_prefix_len(current, 128);
    let mut bridge = String::with_capacity(previous.len() + current_end);
    bridge.push_str(previous);
    bridge.push_str(&current[..current_end]);
    contains_ascii_case_insensitive(&bridge, pattern)
}

fn split_summary_marker_matches(previous: &str, current: &str) -> bool {
    if previous.is_empty() || current.is_empty() {
        return false;
    }
    let current_end = utf8_prefix_len(current, 128);
    let mut bridge = String::with_capacity(previous.len() + current_end);
    bridge.push_str(previous);
    bridge.push_str(&current[..current_end]);
    is_size_or_summary_line(&bridge)
}

#[derive(Clone, Debug)]
pub struct BuildCancellation {
    inner: std::sync::Arc<BuildCancellationInner>,
}

#[derive(Debug)]
struct BuildCancellationInner {
    cancel_tx: watch::Sender<bool>,
    next_process_generation: std::sync::atomic::AtomicU64,
    active_processes: std::sync::Mutex<HashMap<u64, ActiveBuildProcessEntry>>,
}

#[derive(Debug)]
struct ActiveBuildProcessEntry {
    process_id: u32,
    #[cfg(target_os = "windows")]
    process_keepalive: Option<std::sync::Arc<std::os::windows::io::OwnedHandle>>,
}

#[derive(Clone)]
struct ActiveBuildProcessTarget {
    process_id: u32,
    #[cfg(target_os = "windows")]
    _process_keepalive: Option<std::sync::Arc<std::os::windows::io::OwnedHandle>>,
}

#[derive(Clone, Debug)]
struct ProcessTreeTerminationResult {
    process_id: u32,
    success: bool,
    status_code: Option<i32>,
    detail: String,
}

impl ProcessTreeTerminationResult {
    fn diagnostic(&self) -> String {
        format!(
            "pid={} success={} status={} detail={}",
            self.process_id,
            self.success,
            self.status_code
                .map(|code| code.to_string())
                .unwrap_or_else(|| "unavailable".to_string()),
            if self.detail.is_empty() {
                "(none)"
            } else {
                &self.detail
            }
        )
    }
}

impl Default for BuildCancellation {
    fn default() -> Self {
        Self::new()
    }
}

impl BuildCancellation {
    pub fn new() -> Self {
        let (cancel_tx, _cancel_rx) = watch::channel(false);
        Self {
            inner: std::sync::Arc::new(BuildCancellationInner {
                cancel_tx,
                next_process_generation: std::sync::atomic::AtomicU64::new(1),
                active_processes: std::sync::Mutex::new(HashMap::new()),
            }),
        }
    }

    pub fn is_cancelled(&self) -> bool {
        *self.inner.cancel_tx.borrow()
    }

    pub fn subscribe(&self) -> watch::Receiver<bool> {
        self.inner.cancel_tx.subscribe()
    }

    /// Mark only this build run as cancelled and terminate every process tree
    /// that the run currently owns. The compiling task still owns each Child
    /// handle and must wait/reap it before its compile lock can be released.
    pub fn cancel(&self) -> usize {
        // A second cancellation must not send taskkill to a PID that has
        // already exited and could, in principle, have been reused by Windows.
        // A process registered after the first request is still terminated by
        // register_process(), which closes the spawn/registration race.
        if self.inner.cancel_tx.send_replace(true) {
            return 0;
        }
        let processes = self
            .inner
            .active_processes
            .lock()
            .map(|active| {
                active
                    .values()
                    .map(|process| ActiveBuildProcessTarget {
                        process_id: process.process_id,
                        #[cfg(target_os = "windows")]
                        _process_keepalive: process.process_keepalive.clone(),
                    })
                    .collect::<Vec<_>>()
            })
            .unwrap_or_default();
        for process in &processes {
            let termination = terminate_process_tree_sync(process.process_id);
            if !termination.success {
                log::warn!(
                    "build cancellation could not confirm process-tree termination: {}",
                    termination.diagnostic()
                );
            }
        }
        processes.len()
    }

    fn checkpoint(&self) -> Result<()> {
        if self.is_cancelled() {
            Err(anyhow::anyhow!(
                "{}: build cancelled by user",
                BUILD_CANCELED_MARKER
            ))
        } else {
            Ok(())
        }
    }

    fn register_process(
        &self,
        child: &tokio::process::Child,
        process_id: u32,
    ) -> std::io::Result<ActiveBuildProcessGuard> {
        #[cfg(target_os = "windows")]
        let process_keepalive = {
            use std::os::windows::io::BorrowedHandle;
            let raw_handle = child.raw_handle().ok_or_else(|| {
                std::io::Error::new(
                    std::io::ErrorKind::NotFound,
                    "build child exited before its process identity was registered",
                )
            })?;
            let borrowed = unsafe { BorrowedHandle::borrow_raw(raw_handle) };
            Some(std::sync::Arc::new(borrowed.try_clone_to_owned()?))
        };
        let generation = self
            .inner
            .next_process_generation
            .fetch_add(1, std::sync::atomic::Ordering::Relaxed);
        if let Ok(mut active) = self.inner.active_processes.lock() {
            active.insert(
                generation,
                ActiveBuildProcessEntry {
                    process_id,
                    #[cfg(target_os = "windows")]
                    process_keepalive: process_keepalive.clone(),
                },
            );
        }

        // Close the race where cancellation happened after spawn but before
        // the PID became visible to cancel().
        if self.is_cancelled() {
            let termination = terminate_process_tree_sync(process_id);
            if !termination.success {
                log::warn!(
                    "late build-process registration could not confirm process-tree termination: {}",
                    termination.diagnostic()
                );
            }
        }

        Ok(ActiveBuildProcessGuard {
            cancellation: self.clone(),
            generation,
        })
    }

    #[cfg(test)]
    fn active_process_count(&self) -> usize {
        self.inner
            .active_processes
            .lock()
            .map(|active| active.len())
            .unwrap_or_default()
    }

    #[cfg(test)]
    fn active_process_ids(&self) -> Vec<u32> {
        self.inner
            .active_processes
            .lock()
            .map(|active| active.values().map(|process| process.process_id).collect())
            .unwrap_or_default()
    }
}

struct ActiveBuildProcessGuard {
    cancellation: BuildCancellation,
    generation: u64,
}

impl Drop for ActiveBuildProcessGuard {
    fn drop(&mut self) {
        if let Ok(mut active) = self.cancellation.inner.active_processes.lock() {
            active.remove(&self.generation);
        }
    }
}

#[cfg(target_os = "windows")]
fn terminate_process_tree_sync(process_id: u32) -> ProcessTreeTerminationResult {
    let mut taskkill = std::process::Command::new("taskkill");
    taskkill.args(["/PID", &process_id.to_string(), "/T", "/F"]);
    taskkill.stdout(Stdio::null()).stderr(Stdio::null());
    hide_window_sync(&mut taskkill);
    process_tree_termination_result(process_id, taskkill.status())
}

#[cfg(not(target_os = "windows"))]
fn terminate_process_tree_sync(process_id: u32) -> ProcessTreeTerminationResult {
    process_tree_termination_result(
        process_id,
        std::process::Command::new("kill")
            .args(["-TERM", &process_id.to_string()])
            .stdout(Stdio::null())
            .stderr(Stdio::null())
            .status(),
    )
}

fn process_tree_termination_result(
    process_id: u32,
    result: std::io::Result<std::process::ExitStatus>,
) -> ProcessTreeTerminationResult {
    const MAX_DIAGNOSTIC_CHARS: usize = 1024;
    match result {
        Ok(status) => ProcessTreeTerminationResult {
            process_id,
            success: status.success(),
            status_code: status.code(),
            detail: String::new(),
        },
        Err(error) => ProcessTreeTerminationResult {
            process_id,
            success: false,
            status_code: None,
            detail: error
                .to_string()
                .chars()
                .take(MAX_DIAGNOSTIC_CHARS)
                .collect(),
        },
    }
}

tokio::task_local! {
    static ACTIVE_BUILD_CANCELLATION: BuildCancellation;
}

fn current_build_cancellation() -> Option<BuildCancellation> {
    ACTIVE_BUILD_CANCELLATION.try_with(Clone::clone).ok()
}

fn current_build_cancellation_checkpoint() -> Result<()> {
    if let Some(cancellation) = current_build_cancellation() {
        cancellation.checkpoint()?;
    }
    Ok(())
}

async fn with_build_cancellation<T>(
    cancellation: BuildCancellation,
    future: impl std::future::Future<Output = T>,
) -> T {
    ACTIVE_BUILD_CANCELLATION.scope(cancellation, future).await
}

async fn terminate_managed_child_after_cancellation(
    child: &mut tokio::process::Child,
) -> std::io::Result<std::process::ExitStatus> {
    if let Some(status) = child.try_wait()? {
        return Ok(status);
    }

    if let Some(process_id) = child.id() {
        let termination =
            tokio::task::spawn_blocking(move || terminate_process_tree_sync(process_id))
                .await
                .map_err(|error| {
                    std::io::Error::other(format!(
                        "{}: process-tree termination task failed for pid {}: {}",
                        BUILD_CANCELED_MARKER, process_id, error
                    ))
                })?;
        if !termination.success {
            // Another cancellation caller may have terminated the process
            // between the initial try_wait and this second, owner-side attempt.
            // Reap that exit before reporting taskkill's "not found" as a real
            // termination failure.
            if let Some(status) = child.try_wait()? {
                return Ok(status);
            }
            log::warn!(
                "managed child could not confirm process-tree termination: {}",
                termination.diagnostic()
            );
        }
    } else {
        log::warn!(
            "{}: managed child was still pending but no process id was available for tree termination",
            BUILD_CANCELED_MARKER
        );
    }

    // taskkill/kill is responsible for descendants. start_kill is the
    // owner-held fallback for the direct child and child.wait below is the
    // authoritative reap before the build guard can be released.
    if let Err(error) = child.start_kill() {
        if let Some(status) = child.try_wait()? {
            return Ok(status);
        }
        log::warn!(
            "{}: direct managed-child kill request failed: {}",
            BUILD_CANCELED_MARKER,
            error
        );
    }

    match tokio::time::timeout(MANAGED_CANCEL_PROCESS_WAIT_TIMEOUT, child.wait()).await {
        Ok(status) => status,
        Err(_) => Err(std::io::Error::new(
            std::io::ErrorKind::TimedOut,
            format!(
                "{}: cancelled managed child did not exit and reap within {:?}",
                BUILD_CANCELED_MARKER, MANAGED_CANCEL_PROCESS_WAIT_TIMEOUT
            ),
        )),
    }
}

async fn join_managed_stream_task(
    mut task: tokio::task::JoinHandle<std::io::Result<BoundedByteCapture>>,
    stream_name: &'static str,
    cancellation_observed: bool,
) -> std::io::Result<BoundedByteCapture> {
    let joined = if cancellation_observed {
        match tokio::time::timeout(MANAGED_CANCEL_PIPE_DRAIN_TIMEOUT, &mut task).await {
            Ok(joined) => joined,
            Err(_) => {
                task.abort();
                let _ = task.await;
                let error = std::io::Error::new(
                    std::io::ErrorKind::TimedOut,
                    format!(
                        "{}: cancelled managed {} pipe stayed open for {:?}; a descendant process may still own it",
                        BUILD_CANCELED_MARKER, stream_name, MANAGED_CANCEL_PIPE_DRAIN_TIMEOUT
                    ),
                );
                log::warn!("{}", error);
                return Err(error);
            }
        }
    } else {
        task.await
    };
    joined.map_err(|error| {
        std::io::Error::other(format!(
            "managed {} reader task failed: {}",
            stream_name, error
        ))
    })?
}

/// Qualification-only subprocess timing sink.  The normal product path does
/// not touch the filesystem here.  Forge sets both the qualification token
/// and an owned JSONL path so we can distinguish process wait time from pipe
/// draining without changing the fail-closed build route.
fn append_managed_command_telemetry(
    program: &str,
    process_id: Option<u32>,
    spawn_ms: u128,
    wait_ms: u128,
    pipe_drain_ms: u128,
    total_ms: u128,
    status: Option<&std::process::ExitStatus>,
    stdout_bytes: u64,
    stderr_bytes: u64,
    stdout_truncated: bool,
    stderr_truncated: bool,
) {
    let Some(enabled) = std::env::var_os("CK_FLFE_MANAGED_COMMAND_TELEMETRY_ENABLED") else {
        return;
    };
    if enabled != "1" {
        return;
    }
    let Some(path_raw) = std::env::var_os("CK_FLFE_MANAGED_COMMAND_TELEMETRY_PATH") else {
        return;
    };
    if path_raw.is_empty() {
        return;
    }
    let path = PathBuf::from(path_raw);
    let record = serde_json::json!({
        "schemaVersion": 1,
        "program": program,
        "pid": process_id,
        "spawnMs": spawn_ms,
        "waitMs": wait_ms,
        "pipeDrainMs": pipe_drain_ms,
        "totalMs": total_ms,
        "statusCode": status.and_then(std::process::ExitStatus::code),
        "success": status.is_some_and(std::process::ExitStatus::success),
        "stdoutBytes": stdout_bytes,
        "stderrBytes": stderr_bytes,
        "stdoutTruncated": stdout_truncated,
        "stderrTruncated": stderr_truncated,
    });
    let line = match serde_json::to_string(&record) {
        Ok(mut line) => {
            line.push('\n');
            line
        }
        Err(_) => return,
    };
    // Qualification may launch several compile children concurrently.  Keep
    // records line-delimited and avoid interleaved writes; telemetry failure
    // is deliberately diagnostic-only and can never fail a build.
    static FILE_LOCK: std::sync::OnceLock<std::sync::Mutex<()>> = std::sync::OnceLock::new();
    let lock = FILE_LOCK.get_or_init(|| std::sync::Mutex::new(()));
    let _guard = lock.lock().ok();
    let Ok(mut file) = std::fs::OpenOptions::new()
        .create(true)
        .append(true)
        .open(path)
    else {
        return;
    };
    use std::io::Write as _;
    let _ = file.write_all(line.as_bytes());
}

async fn managed_command_output(cmd: &mut Command) -> std::io::Result<std::process::Output> {
    if let Err(error) = current_build_cancellation_checkpoint() {
        return Err(std::io::Error::new(
            std::io::ErrorKind::Interrupted,
            error.to_string(),
        ));
    }

    let command_started = std::time::Instant::now();
    let program = cmd.as_std().get_program().to_string_lossy().into_owned();
    cmd.kill_on_drop(true);
    cmd.stdout(Stdio::piped()).stderr(Stdio::piped());
    let spawn_started = std::time::Instant::now();
    let mut child = cmd.spawn()?;
    let spawn_ms = spawn_started.elapsed().as_millis();
    let process_id = child.id();
    let cancellation = current_build_cancellation();
    let process_guard = match (cancellation.as_ref(), child.id()) {
        (Some(token), Some(process_id)) => Some(token.register_process(&child, process_id)?),
        _ => None,
    };
    let stdout = child.stdout.take().ok_or_else(|| {
        std::io::Error::new(
            std::io::ErrorKind::BrokenPipe,
            "managed stdout pipe missing",
        )
    })?;
    let stderr = child.stderr.take().ok_or_else(|| {
        std::io::Error::new(
            std::io::ErrorKind::BrokenPipe,
            "managed stderr pipe missing",
        )
    })?;
    // Drain both pipes concurrently so a noisy hook cannot deadlock on a full
    // OS pipe. Each capture keeps at most 2 MiB while continuing to discard and
    // drain excess bytes until process exit.
    let stdout_task = tokio::spawn(read_bounded_command_stream(stdout));
    let stderr_task = tokio::spawn(read_bounded_command_stream(stderr));
    let mut cancel_rx = cancellation.as_ref().map(BuildCancellation::subscribe);
    let wait_started = std::time::Instant::now();
    let status = if cancel_rx
        .as_ref()
        .is_some_and(|receiver| *receiver.borrow())
    {
        terminate_managed_child_after_cancellation(&mut child).await
    } else if let Some(receiver) = cancel_rx.as_mut() {
        tokio::select! {
            status = child.wait() => status,
            changed = receiver.changed() => {
                if changed.is_ok() && *receiver.borrow() {
                    terminate_managed_child_after_cancellation(&mut child).await
                } else {
                    child.wait().await
                }
            }
        }
    } else {
        child.wait().await
    };
    let wait_ms = wait_started.elapsed().as_millis();
    let pipe_drain_started = std::time::Instant::now();
    let cancellation_observed = cancellation
        .as_ref()
        .is_some_and(BuildCancellation::is_cancelled);
    let (stdout_capture, stderr_capture) = tokio::join!(
        join_managed_stream_task(stdout_task, "stdout", cancellation_observed),
        join_managed_stream_task(stderr_task, "stderr", cancellation_observed),
    );
    let pipe_drain_ms = pipe_drain_started.elapsed().as_millis();
    let total_ms = command_started.elapsed().as_millis();
    let (stdout_bytes, stdout_truncated) = stdout_capture
        .as_ref()
        .map(|capture| (capture.total_bytes_seen(), capture.is_truncated()))
        .unwrap_or((0, false));
    let (stderr_bytes, stderr_truncated) = stderr_capture
        .as_ref()
        .map(|capture| (capture.total_bytes_seen(), capture.is_truncated()))
        .unwrap_or((0, false));
    append_managed_command_telemetry(
        &program,
        process_id,
        spawn_ms,
        wait_ms,
        pipe_drain_ms,
        total_ms,
        status.as_ref().ok(),
        stdout_bytes,
        stderr_bytes,
        stdout_truncated,
        stderr_truncated,
    );
    drop(process_guard);

    if cancellation_observed {
        // A pipe timeout is stronger evidence than the ordinary cancellation
        // result because it can indicate that a descendant survived. Preserve
        // that failure instead of translating it into a clean cancellation.
        let _stdout_capture = stdout_capture?;
        let _stderr_capture = stderr_capture?;
        let _status = status?;
        return Err(std::io::Error::new(
            std::io::ErrorKind::Interrupted,
            format!("{}: build cancelled by user", BUILD_CANCELED_MARKER),
        ));
    }
    let status = status?;
    let stdout_capture = stdout_capture?;
    let stderr_capture = stderr_capture?;
    if stdout_capture.is_truncated() || stderr_capture.is_truncated() {
        return Err(std::io::Error::new(
            std::io::ErrorKind::InvalidData,
            format!(
                "managed subprocess output exceeded the {} byte per-stream safety limit (stdout={} bytes, stderr={} bytes); refusing to parse truncated hook output; stdout_tail={:?}; stderr_tail={:?}",
                MANAGED_COMMAND_STREAM_MAX_BYTES,
                stdout_capture.total_bytes_seen(),
                stderr_capture.total_bytes_seen(),
                stdout_capture.tail_excerpt(4096),
                stderr_capture.tail_excerpt(4096),
            ),
        ));
    }
    Ok(std::process::Output {
        status,
        stdout: stdout_capture.into_bytes(),
        stderr: stderr_capture.into_bytes(),
    })
}

#[cfg(test)]
mod build_cancellation_tests {
    use super::{
        BUILD_CANCELED_MARKER, BuildCancellation, hide_window, managed_command_output,
        with_build_cancellation,
    };
    use tokio::process::Command;

    #[cfg(target_os = "windows")]
    fn running_windows_process_ids() -> std::io::Result<std::collections::HashSet<u32>> {
        let mut command = std::process::Command::new("tasklist");
        command.args(["/FO", "CSV", "/NH"]);
        super::hide_window_sync(&mut command);
        let output = command.output()?;
        if !output.status.success() {
            return Err(std::io::Error::other(format!(
                "tasklist failed with status {:?}: {}",
                output.status.code(),
                String::from_utf8_lossy(&output.stderr).trim()
            )));
        }
        Ok(String::from_utf8_lossy(&output.stdout)
            .lines()
            .filter_map(|line| {
                line.split(',')
                    .nth(1)
                    .map(|field| field.trim().trim_matches('"'))
                    .and_then(|field| field.parse::<u32>().ok())
            })
            .collect())
    }

    #[test]
    fn cancellation_tokens_are_run_scoped() {
        let first = BuildCancellation::new();
        let second = BuildCancellation::new();
        assert_eq!(first.cancel(), 0);
        assert_eq!(
            first.cancel(),
            0,
            "repeated cancellation must be idempotent"
        );
        assert!(first.is_cancelled());
        assert!(!second.is_cancelled());
    }

    #[tokio::test]
    async fn cancellation_terminates_and_reaps_the_owned_process_tree() {
        let cancellation = BuildCancellation::new();
        let task_cancellation = cancellation.clone();

        #[cfg(target_os = "windows")]
        let (mut command, descendant_pid_path, _temp) = {
            let temp = tempfile::tempdir().expect("cancellation test tempdir");
            let descendant_pid_path = temp.path().join("descendant.pid");
            let escaped_pid_path = descendant_pid_path.to_string_lossy().replace('\'', "''");
            let script = format!(
                "$child = Start-Process -FilePath \"$env:SystemRoot\\System32\\PING.EXE\" -ArgumentList @('-n','120','127.0.0.1') -PassThru -WindowStyle Hidden; [System.IO.File]::WriteAllText('{}', [string]$child.Id); $child.WaitForExit(); exit $child.ExitCode",
                escaped_pid_path
            );
            let mut command = Command::new("powershell.exe");
            command.args([
                "-NoLogo",
                "-NoProfile",
                "-NonInteractive",
                "-Command",
                &script,
            ]);
            (command, descendant_pid_path, temp)
        };

        #[cfg(not(target_os = "windows"))]
        let mut command = {
            let mut command = Command::new("sh");
            command.args(["-c", "sleep 120"]);
            command
        };

        let mut task = tokio::spawn(async move {
            with_build_cancellation(task_cancellation, async move {
                hide_window(&mut command);
                managed_command_output(&mut command).await
            })
            .await
        });

        let root_process_id = tokio::time::timeout(std::time::Duration::from_secs(5), async {
            loop {
                if let Some(process_id) = cancellation.active_process_ids().first().copied() {
                    return process_id;
                }
                tokio::time::sleep(std::time::Duration::from_millis(10)).await;
            }
        })
        .await
        .expect("managed command should publish its process id");

        #[cfg(target_os = "windows")]
        let descendant_process_id =
            tokio::time::timeout(std::time::Duration::from_secs(5), async {
                loop {
                    if let Ok(pid) = std::fs::read_to_string(&descendant_pid_path)
                        && let Ok(pid) = pid.trim().parse::<u32>()
                    {
                        return pid;
                    }
                    tokio::time::sleep(std::time::Duration::from_millis(10)).await;
                }
            })
            .await
            .expect("managed command should publish its descendant process id");

        assert_eq!(cancellation.cancel(), 1);
        let task_result = tokio::time::timeout(std::time::Duration::from_secs(10), &mut task).await;
        let command_result = match task_result {
            Ok(Ok(result)) => result,
            Ok(Err(error)) => {
                let _ = super::terminate_process_tree_sync(root_process_id);
                #[cfg(target_os = "windows")]
                let _ = super::terminate_process_tree_sync(descendant_process_id);
                panic!("managed command task failed: {error}");
            }
            Err(_) => {
                let root_cleanup = super::terminate_process_tree_sync(root_process_id);
                #[cfg(target_os = "windows")]
                let descendant_cleanup = super::terminate_process_tree_sync(descendant_process_id);
                task.abort();
                let _ = task.await;
                #[cfg(target_os = "windows")]
                panic!(
                    "cancelled process tree did not exit within 10s; root_cleanup={}; descendant_cleanup={}",
                    root_cleanup.diagnostic(),
                    descendant_cleanup.diagnostic()
                );
                #[cfg(not(target_os = "windows"))]
                panic!(
                    "cancelled process tree did not exit within 10s; cleanup={}",
                    root_cleanup.diagnostic()
                );
            }
        };

        #[cfg(target_os = "windows")]
        {
            let running = running_windows_process_ids().expect("read Windows process list");
            let root_survived = running.contains(&root_process_id);
            let descendant_survived = running.contains(&descendant_process_id);
            if root_survived {
                let _ = super::terminate_process_tree_sync(root_process_id);
            }
            if descendant_survived {
                let _ = super::terminate_process_tree_sync(descendant_process_id);
            }
            assert!(
                !root_survived,
                "managed root process {root_process_id} survived cancellation"
            );
            assert!(
                !descendant_survived,
                "managed descendant process {descendant_process_id} survived cancellation"
            );
        }

        let error = command_result.expect_err("cancelled command must not report success");
        assert_eq!(error.kind(), std::io::ErrorKind::Interrupted);
        assert!(error.to_string().contains(BUILD_CANCELED_MARKER));
        assert_eq!(cancellation.active_process_count(), 0);
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct CcacheStatsSnapshot {
    hits: u64,
    misses: u64,
}

fn parse_ccache_stats_snapshot(raw: &str) -> Option<CcacheStatsSnapshot> {
    let value: serde_json::Value = serde_json::from_str(raw).ok()?;
    let direct_hits = value.get("direct_cache_hit")?.as_u64()?;
    let preprocessed_hits = value.get("preprocessed_cache_hit")?.as_u64()?;
    let misses = value.get("cache_miss")?.as_u64()?;
    Some(CcacheStatsSnapshot {
        hits: direct_hits.checked_add(preprocessed_hits)?,
        misses,
    })
}

fn ccache_stats_delta(
    before: CcacheStatsSnapshot,
    after: CcacheStatsSnapshot,
) -> Option<CcacheStatsSnapshot> {
    Some(CcacheStatsSnapshot {
        hits: after.hits.checked_sub(before.hits)?,
        misses: after.misses.checked_sub(before.misses)?,
    })
}

async fn read_ccache_stats_snapshot(
    sysroot_root: &Path,
    ccache_env: &HashMap<String, String>,
) -> Option<CcacheStatsSnapshot> {
    if ccache_env.is_empty() {
        return None;
    }
    let binary = sysroot_root
        .join("bin")
        .join(if cfg!(target_os = "windows") {
            "ccache.exe"
        } else {
            "ccache"
        });
    if !binary.is_file() {
        return None;
    }
    let mut command = Command::new(binary);
    hide_window(&mut command);
    command.args(["--print-stats", "--format=json"]);
    for (key, value) in ccache_env {
        command.env(key, value);
    }
    let output = managed_command_output(&mut command).await.ok()?;
    if !output.status.success() {
        return None;
    }
    parse_ccache_stats_snapshot(&String::from_utf8_lossy(&output.stdout))
}

fn fast_profile_ccache_namespace_for_target(
    sysroot_root: &Path,
    fqbn: &str,
    profile: CompileProfile,
) -> String {
    let toolchain_key = toolchain_cache_key_from_root(sysroot_root, fqbn);
    fast_profile_ccache_namespace_for_toolchain_key(&toolchain_key, fqbn, profile)
}

/// Derive the ccache namespace from an already authenticated toolchain key.
///
/// A foreground compile owns a `ToolchainIdentityLease`, so resolving the same
/// identity again here only repeats its guarded filesystem walk.  Keeping this
/// helper separate preserves the conservative standalone path while letting a
/// request reuse the proof it has already paid for.
fn fast_profile_ccache_namespace_for_toolchain_key(
    toolchain_key: &str,
    fqbn: &str,
    profile: CompileProfile,
) -> String {
    fast_profile_ccache_namespace_for_toolchain_key_with_time_context(
        toolchain_key,
        fqbn,
        profile,
        &compiler_time_environment_cache_context(),
    )
}

/// Keep ccache object namespaces aligned with the Core archive identity.
///
/// ccache can safely avoid hits for source-level time macros once its
/// `time_macros` sloppiness is disabled, but it cannot know that a CK-owned
/// Core archive was made under a different compiler-time environment. Binding
/// both caches to the same context prevents a fixed-time qualification build
/// from consuming ordinary user-build objects (and vice versa).
fn fast_profile_ccache_namespace_for_toolchain_key_with_time_context(
    toolchain_key: &str,
    fqbn: &str,
    profile: CompileProfile,
    compiler_time_context: &str,
) -> String {
    crate::builder::portable_cache::fast_profile_ccache_namespace(
        toolchain_key,
        &canonical_fqbn_cache_identity(fqbn),
        build_mode_suffix(profile),
        &format!(
            "{}|compiler-time-environment:{}",
            FAST_BUILD_CONTRACT_SIGNATURE_MARKER, compiler_time_context
        ),
    )
}

/// Build ccache environment variables as a map for Arduino CLI, Fast Relink,
/// and dependency-only subprocess injection.
fn build_ccache_env_map(
    sysroot_root: &Path,
    fqbn: &str,
    profile: CompileProfile,
) -> HashMap<String, String> {
    build_ccache_env_map_with_toolchain_key(sysroot_root, fqbn, profile, None)
}

/// Build ccache environment variables while reusing a request's authenticated
/// toolchain identity when one is available.  `None` is reserved for isolated
/// helpers and warmup work that do not own a request lease.
fn build_ccache_env_map_with_toolchain_key(
    sysroot_root: &Path,
    fqbn: &str,
    profile: CompileProfile,
    toolchain_key: Option<&str>,
) -> HashMap<String, String> {
    if !profile_uses_ccache(profile) {
        return HashMap::new();
    }
    let Ok(shims) = ensure_ccache_shims(sysroot_root) else {
        return HashMap::new();
    };
    if !shims.enabled {
        return HashMap::new();
    }
    let cache_store = sysroot_root.join("cache").join("ccache");
    let _ = std::fs::create_dir_all(&cache_store);
    let namespace = toolchain_key
        .map(|key| fast_profile_ccache_namespace_for_toolchain_key(key, fqbn, profile))
        .unwrap_or_else(|| fast_profile_ccache_namespace_for_target(sysroot_root, fqbn, profile));
    let allow_hardlinks = profile != CompileProfile::PortableFast;
    let mut env: HashMap<String, String> = crate::builder::portable_cache::fast_profile_ccache_env(
        sysroot_root,
        &namespace,
        allow_hardlinks,
    )
    .into_iter()
    .collect();
    let packages_dir = sysroot_root.join("packages");
    let mut tool_paths = Vec::new();
    if let Ok(vendors) = std::fs::read_dir(&packages_dir) {
        for vendor in vendors.flatten() {
            let tools = vendor.path().join("tools");
            if !tools.is_dir() {
                continue;
            }
            if let Ok(tool_entries) = std::fs::read_dir(&tools) {
                for tool in tool_entries.flatten() {
                    if let Ok(versions) = std::fs::read_dir(tool.path()) {
                        for ver in versions.flatten() {
                            let bin = ver.path().join("bin");
                            if bin.is_dir() {
                                tool_paths.push(bin.to_string_lossy().to_string());
                            }
                        }
                    }
                }
            }
        }
    }
    let sep = if cfg!(target_os = "windows") {
        ";"
    } else {
        ":"
    };
    env.insert("CCACHE_PATH".into(), tool_paths.join(sep));
    env
}

/// Inject ccache environment variables into an arduino-cli Command.
/// Returns true if ccache acceleration was applied.
fn setup_ccache_env(
    cmd: &mut Command,
    sysroot_root: &Path,
    fqbn: &str,
    profile: CompileProfile,
) -> bool {
    setup_ccache_env_with_toolchain_key(cmd, sysroot_root, fqbn, profile, None)
}

/// Inject ccache settings without re-resolving an identity that the active
/// compile request already authenticated.
fn setup_ccache_env_with_toolchain_key(
    cmd: &mut Command,
    sysroot_root: &Path,
    fqbn: &str,
    profile: CompileProfile,
    toolchain_key: Option<&str>,
) -> bool {
    let env = build_ccache_env_map_with_toolchain_key(sysroot_root, fqbn, profile, toolchain_key);
    if env.is_empty() {
        return false;
    }
    // Do not inherit the opposite presence-style boolean from CK's own launch
    // environment. The profile-specific map below owns exactly one of them.
    cmd.env_remove("CCACHE_HARDLINK");
    cmd.env_remove("CCACHE_NOHARDLINK");
    // ccache rewrites source paths when this is inherited, which changes
    // `__FILE__` bytes in Core/library objects on some Arduino platforms.
    cmd.env_remove("CCACHE_BASEDIR");
    for (key, value) in env {
        cmd.env(key, value);
    }
    true
}

/// Build the old CK-owned `platform.local.txt` payload for one platform.
///
/// CK used to persist this payload inside every installed Core. That made a
/// supposedly platform-native Release build inherit CK compiler recipes and
/// could overwrite a third-party author's own `platform.local.txt`. New builds
/// pass the same values as command-scoped `--build-property` arguments instead.
/// Keeping this renderer allows a fail-closed migration: only a byte-for-byte
/// CK payload is removed; every unknown or user-authored file is preserved.
fn ccache_shims_enabled(sysroot_root: &Path) -> bool {
    ensure_ccache_shims(sysroot_root)
        .map(|shims| shims.enabled)
        .unwrap_or(false)
}

fn legacy_ck_platform_local_payload_with_verified_shims(
    sysroot_root: &Path,
    platform_txt: &Path,
    shims_enabled: bool,
) -> Option<String> {
    if !shims_enabled {
        return None;
    }
    let ccache_bin_dir = sysroot_root.join("bin").join("ccache");
    let ccache_path_value = ccache_bin_dir.to_string_lossy().replace('\\', "/");
    let platform_content = std::fs::read_to_string(platform_txt).ok()?;
    let nocache_path = platform_content
        .lines()
        .find_map(|line| line.trim().strip_prefix("compiler.path="))
        .unwrap_or("{tools.{build.tarch}-esp-elf-gcc.path}/bin/")
        .to_string();
    let mut content = format!(
        "compiler.path={ccache}/\n\
         compiler.path.nocache={nocache}\n\
         compiler.c.extra_flags=-pipe\n\
         compiler.cpp.extra_flags=-pipe\n\
         compiler.S.extra_flags=-pipe\n\
         compiler.ck.final_flags=\n",
        ccache = ccache_path_value,
        nocache = nocache_path,
    );
    if let Some(preproc_recipe) = derive_preproc_recipe_from_platform(&platform_content) {
        content.push_str(&format!("recipe.preproc.macros={}\n", preproc_recipe));
    }
    for (key, nocache) in derive_nocache_tool_recipe_overrides(&platform_content) {
        content.push_str(&format!("{}={}\n", key, nocache));
    }
    for (key, flags) in derive_final_compile_flag_overrides(&platform_content) {
        content.push_str(&format!("{}={}\n", key, flags));
    }
    Some(content)
}

fn legacy_ck_platform_local_payload(sysroot_root: &Path, platform_txt: &Path) -> Option<String> {
    legacy_ck_platform_local_payload_with_verified_shims(
        sysroot_root,
        platform_txt,
        ccache_shims_enabled(sysroot_root),
    )
}

fn platform_version_root_for_fqbn(sysroot_root: &Path, fqbn: &str) -> Option<PathBuf> {
    let mut parts = fqbn.split(':');
    let vendor = parts.next()?;
    let arch = parts.next()?;
    let board = parts.next()?;
    if !safe_fqbn_path_component(vendor)
        || !safe_fqbn_path_component(arch)
        || !safe_fqbn_path_component(board)
    {
        return None;
    }
    let base = sysroot_root
        .join("packages")
        .join(vendor)
        .join("hardware")
        .join(arch);
    let version = select_highest_installed_core_version(&base)?;
    let root = base.join(version);
    let canonical_sysroot = std::fs::canonicalize(sysroot_root).ok()?;
    let canonical_root = std::fs::canonicalize(&root).ok()?;
    (canonical_root.starts_with(canonical_sysroot) && canonical_root.is_dir()).then_some(root)
}

fn ccache_command_build_properties(
    sysroot_root: &Path,
    fqbn: &str,
    profile: CompileProfile,
    verified_shims_enabled: Option<bool>,
) -> Vec<(String, String)> {
    // Release alone is the intentionally unaccelerated lane. PortableFast
    // uses this content-derived, command-scoped adapter as its generic cache
    // mechanism; it never writes platform.local.txt.
    if profile == CompileProfile::Release {
        return Vec::new();
    }
    let Some(platform_root) = platform_version_root_for_fqbn(sysroot_root, fqbn) else {
        return Vec::new();
    };
    let platform_txt = platform_root.join("platform.txt");
    let shims_enabled =
        verified_shims_enabled.unwrap_or_else(|| ccache_shims_enabled(sysroot_root));
    legacy_ck_platform_local_payload_with_verified_shims(sysroot_root, &platform_txt, shims_enabled)
        .into_iter()
        .flat_map(|payload| {
            payload
                .lines()
                .filter_map(|line| line.split_once('='))
                .map(|(key, value)| (key.to_string(), value.to_string()))
                .collect::<Vec<_>>()
        })
        .collect()
}

/// Remove only legacy files that match CK's old generated payload exactly.
/// User-authored or publisher-authored `platform.local.txt` files are never
/// changed and remain part of the toolchain identity, forcing conservative
/// routing unless independently qualified.
pub fn remove_legacy_ck_platform_local_overrides(sysroot_root: &Path) -> usize {
    let mut removed = 0usize;
    let packages = sysroot_root.join("packages");
    let Ok(vendors) = std::fs::read_dir(packages) else {
        return 0;
    };
    for vendor in vendors.flatten() {
        let hardware = vendor.path().join("hardware");
        let Ok(architectures) = std::fs::read_dir(hardware) else {
            continue;
        };
        for architecture in architectures.flatten() {
            let Ok(versions) = std::fs::read_dir(architecture.path()) else {
                continue;
            };
            for version in versions.flatten() {
                let platform_txt = version.path().join("platform.txt");
                let local_txt = version.path().join("platform.local.txt");
                let Ok(metadata) = std::fs::symlink_metadata(&local_txt) else {
                    continue;
                };
                if metadata.file_type().is_symlink() || !metadata.is_file() {
                    continue;
                }
                let Some(expected) = legacy_ck_platform_local_payload(sysroot_root, &platform_txt)
                else {
                    continue;
                };
                if std::fs::read_to_string(&local_txt).ok().as_deref() == Some(expected.as_str())
                    && std::fs::remove_file(&local_txt).is_ok()
                {
                    removed += 1;
                }
            }
        }
    }
    removed
}

/// Append CK's optional final compiler flags after the Core's own C/C++ flag
/// property. ESP32 embeds SDK response files in `compiler.*.flags`, after
/// `compiler.*.extra_flags`; appending here lets Quick/Shared override DWARF
/// without rewriting source/output recipes. Release keeps the property empty.
fn derive_final_compile_flag_overrides(platform_txt: &str) -> Vec<(String, String)> {
    let mut overrides = Vec::new();
    for line in platform_txt.lines().map(str::trim) {
        let Some((key, flags)) = line.split_once('=') else {
            continue;
        };
        let is_c_or_cpp_flags = matches!(key, "compiler.c.flags" | "compiler.cpp.flags")
            || key.starts_with("compiler.c.flags.")
            || key.starts_with("compiler.cpp.flags.");
        if !is_c_or_cpp_flags || flags.contains("{compiler.ck.final_flags}") {
            continue;
        }
        overrides.push((
            key.to_string(),
            format!("{} {{compiler.ck.final_flags}}", flags.trim_end()),
        ));
    }
    overrides
}

/// Derive a `recipe.preproc.macros` recipe from the platform's `recipe.cpp.o.pattern`,
/// replacing `{compiler.path}` with `{compiler.path.nocache}` (real compiler) and
/// converting from compilation to preprocessing flags.
fn derive_preproc_recipe_from_platform(platform_txt: &str) -> Option<String> {
    for line in platform_txt.lines() {
        let line = line.trim();
        if let Some(recipe) = line.strip_prefix("recipe.cpp.o.pattern=") {
            // Replace {compiler.path} with {compiler.path.nocache}
            let mut preproc = recipe.replace("{compiler.path}", "{compiler.path.nocache}");
            // Replace the source/output part with preprocessing flags
            // Original: "{source_file}" -o "{object_file}"
            // Target:   -w -x c++ -E -CC "{source_file}" -o "{preprocessed_file_path}"
            preproc = preproc.replace(
                "\"{source_file}\" -o \"{object_file}\"",
                "-w -x c++ -E -CC \"{source_file}\" -o \"{preprocessed_file_path}\"",
            );
            return Some(preproc);
        }
    }
    None
}

/// Lookup a recipe line in platform.txt and replace `{compiler.path}` with
/// `{compiler.path.nocache}` so it bypasses the ccache shim.
/// Used for non-compiler tools (ar, linker, size) that ccache cannot cache —
/// going through the shim just wastes 10-50ms per invocation.
fn derive_nocache_recipe(platform_txt: &str, key: &str) -> Option<String> {
    let prefix = format!("{}=", key);
    for line in platform_txt.lines() {
        let line = line.trim();
        if let Some(recipe) = line.strip_prefix(&prefix) {
            if recipe.contains("{compiler.path}") {
                return Some(recipe.replace("{compiler.path}", "{compiler.path.nocache}"));
            }
        }
    }
    None
}

/// Find all non-compiler properties that must retain the Core-selected real
/// toolchain path. In addition to archive/link/size, this intentionally covers
/// arbitrary `recipe.objcopy.*.pattern` variants so imported and future Cores do
/// not need a hardcoded list of eep/hex/bin recipe names.
fn derive_nocache_tool_recipe_overrides(platform_txt: &str) -> Vec<(String, String)> {
    let mut keys = BTreeSet::new();
    for line in platform_txt.lines().map(str::trim) {
        let Some((key, recipe)) = line.split_once('=') else {
            continue;
        };
        let objcopy_recipe = key.starts_with("recipe.objcopy.")
            && (key.ends_with(".pattern") || key.ends_with(".pattern.windows"));
        let fixed_noncompiler = matches!(
            key,
            "recipe.ar.pattern"
                | "recipe.c.combine.pattern"
                | "recipe.size.pattern"
                | "debug.cortex-debug.custom.objdumpPath"
        );
        if (objcopy_recipe || fixed_noncompiler) && recipe.contains("{compiler.path}") {
            keys.insert(key.to_string());
        }
    }

    keys.into_iter()
        .filter_map(|key| derive_nocache_recipe(platform_txt, &key).map(|recipe| (key, recipe)))
        .collect()
}

fn normalize_code_for_cache(code: &str) -> String {
    // Keep cache matching stable across CRLF/LF differences from frontend/editor pipelines.
    code.replace("\r\n", "\n")
}

fn exact_cache_source_matches(previous: &str, current: &str) -> bool {
    // Exact-cache reuse must be based on lossless source identity.  A lexical
    // canonicalizer cannot safely decide C/C++ equivalence: for example,
    // `p + ++q` and `p++ + q` both collapse to `p+++q` if whitespace around
    // punctuators is discarded.  Normalizing line endings is safe, but no
    // comments, whitespace, or token boundaries may otherwise be ignored.
    normalize_code_for_cache(previous).as_bytes() == normalize_code_for_cache(current).as_bytes()
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum CompileProfile {
    QuickFast,
    SharedFast,
    /// Core-agnostic acceleration lane. This keeps Arduino CLI's native
    /// recipes/hooks and stable incremental build directory, while enabling
    /// command-scoped ccache. It deliberately never enters CK Fast Relink,
    /// direct-link, skipped-hook, or -O1 property contracts.
    PortableFast,
    Release,
}

/// Product-level purpose of one compile request. This is intentionally
/// independent of `CompileProfile`: a profile selects the existing compiler
/// behavior, while intent constrains whether a future NativeRelink engine may
/// ever be considered for the request.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum CompileIntent {
    /// Editor compile/check action. This is the only intent that may become a
    /// NativeRelink candidate after that engine has its own evidence gate.
    CompileOnly,
    /// Firmware artifacts are about to be uploaded; packaging/objcopy hooks
    /// and the full upload-ready contract remain authoritative.
    UploadReady,
    /// Opportunistic/silent warmup work must never exercise a future direct
    /// source-edit engine.
    Background,
    /// Rebuild of a content-locked historical project remains on its isolated,
    /// reproducible compiler route.
    LockedReplay,
}

impl CompileIntent {
    /// Safety gate reserved for future NativeRelink routing. No current engine
    /// consumes this decision yet.
    pub fn allows_future_native_relink_candidate(self) -> bool {
        matches!(self, Self::CompileOnly)
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum NativeRelinkAccessMode {
    Disabled,
    QualificationProbe,
    Certified,
}

/// Request-scoped authorization for the independent NativeRelink engine.
/// Existing compile APIs always use `disabled`; only an explicit qualification
/// probe or a matching Forge performance certificate may construct an enabled
/// value. The binding covers this host installation and the complete FQBN.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct NativeRelinkAccess {
    mode: NativeRelinkAccessMode,
    target_binding: String,
    authorization_key: String,
}

/// Engine-contract dispatch for the host/target authorization binding. Every
/// architecture family with its own NativeRelink engine MUST have a branch
/// here: falling through to the AVR default would silently hash the wrong
/// contract into that family's access keys and certificates.
fn native_relink_engine_contract_for_fqbn(fqbn: &str) -> &'static str {
    if fqbn.starts_with("arduino:samd:") {
        samd_native_relink::SAMD_NATIVE_RELINK_ENGINE_CONTRACT
    } else if fqbn.starts_with("esp32:esp32:") {
        esp32_native_relink::ESP32_NATIVE_RELINK_ENGINE_CONTRACT
    } else {
        native_relink::NATIVE_RELINK_ENGINE_CONTRACT
    }
}

fn native_relink_target_binding(
    sysroot_root: &Path,
    fqbn: &str,
    toolchain_key: &str,
) -> Result<String> {
    let canonical_sysroot = canonical_toolchain_lease_target(sysroot_root, fqbn)?;
    if toolchain_key.trim().is_empty() {
        anyhow::bail!("NativeRelink target binding requires a toolchain identity");
    }
    let mut hasher = Sha256::new();
    hasher.update(b"ck-native-relink-host-target-v1\0");
    let engine_contract = native_relink_engine_contract_for_fqbn(fqbn);
    hasher.update(engine_contract.as_bytes());
    hasher.update(b"\0");
    hasher.update(canonical_sysroot.to_string_lossy().as_bytes());
    hasher.update(b"\0");
    hasher.update(fqbn.as_bytes());
    hasher.update(b"\0");
    hasher.update(toolchain_key.as_bytes());
    for key in [
        "COMPUTERNAME",
        "PROCESSOR_IDENTIFIER",
        "PROCESSOR_ARCHITECTURE",
        "NUMBER_OF_PROCESSORS",
        "HOSTNAME",
    ] {
        hasher.update(b"\0");
        hasher.update(key.as_bytes());
        hasher.update(b"=");
        hasher.update(
            std::env::var(key)
                .unwrap_or_else(|_| "<unset>".into())
                .as_bytes(),
        );
    }
    Ok(hex::encode(hasher.finalize()))
}

fn valid_sha256_text(value: &str) -> bool {
    value.len() == 64
        && value
            .as_bytes()
            .iter()
            .all(|byte| byte.is_ascii_digit() || (b'a'..=b'f').contains(byte))
}

impl NativeRelinkAccess {
    pub fn disabled() -> Self {
        Self {
            mode: NativeRelinkAccessMode::Disabled,
            target_binding: String::new(),
            authorization_key: String::new(),
        }
    }

    pub fn qualification_probe(
        sysroot_root: &Path,
        fqbn: &str,
        identity_lease: &ToolchainIdentityLease,
    ) -> Result<Self> {
        identity_lease.validate_target(sysroot_root, fqbn)?;
        let target_binding =
            native_relink_target_binding(sysroot_root, fqbn, identity_lease.toolchain_key())?;
        let authorization_key = hex::encode(Sha256::digest(
            [
                b"ck-native-relink-qualification-probe-v1\0".as_slice(),
                target_binding.as_bytes(),
            ]
            .concat(),
        ));
        Ok(Self {
            mode: NativeRelinkAccessMode::QualificationProbe,
            target_binding,
            authorization_key,
        })
    }

    pub fn certified(
        sysroot_root: &Path,
        fqbn: &str,
        identity_lease: &ToolchainIdentityLease,
        evidence_sha256: &str,
    ) -> Result<Self> {
        let evidence_sha256 = evidence_sha256.trim();
        if !valid_sha256_text(evidence_sha256) {
            anyhow::bail!("NativeRelink certificate evidence hash is invalid");
        }
        identity_lease.validate_target(sysroot_root, fqbn)?;
        let target_binding =
            native_relink_target_binding(sysroot_root, fqbn, identity_lease.toolchain_key())?;
        let authorization_key = hex::encode(Sha256::digest(
            [
                b"ck-native-relink-certified-v1\0".as_slice(),
                target_binding.as_bytes(),
                b"\0".as_slice(),
                evidence_sha256.as_bytes(),
            ]
            .concat(),
        ));
        Ok(Self {
            mode: NativeRelinkAccessMode::Certified,
            target_binding,
            authorization_key,
        })
    }

    fn is_authorized_for(
        &self,
        sysroot_root: &Path,
        fqbn: &str,
        identity_lease: &ToolchainIdentityLease,
    ) -> bool {
        self.mode != NativeRelinkAccessMode::Disabled
            && !self.authorization_key.is_empty()
            && identity_lease.validate_target(sysroot_root, fqbn).is_ok()
            && native_relink_target_binding(sysroot_root, fqbn, identity_lease.toolchain_key())
                .is_ok_and(|binding| binding == self.target_binding)
    }

    fn mode_label(&self) -> &'static str {
        match self.mode {
            NativeRelinkAccessMode::Disabled => "disabled",
            NativeRelinkAccessMode::QualificationProbe => "qualification-probe",
            NativeRelinkAccessMode::Certified => "certified",
        }
    }

    fn authorization_key(&self) -> &str {
        &self.authorization_key
    }
}

/// Profiles that are allowed to consume CK's specialized compilation-database
/// and direct-link implementation. Every other profile must stay on the
/// platform's authoritative Arduino CLI path.
fn profile_supports_fast_relink(profile: CompileProfile) -> bool {
    matches!(
        profile,
        CompileProfile::QuickFast | CompileProfile::SharedFast
    )
}

/// The portable lane still gets the generic compiler cache, but no profile
/// specific compiler/property rewriting. Keeping this predicate centralized
/// prevents a new Core from accidentally inheriting ESP32-only relink logic.
fn profile_supports_portable_cache(profile: CompileProfile) -> bool {
    matches!(profile, CompileProfile::PortableFast)
}

fn profile_uses_ccache(profile: CompileProfile) -> bool {
    profile_supports_fast_relink(profile) || profile_supports_portable_cache(profile)
}

/// Whether CK may return a previously authenticated artefact without invoking
/// the platform compiler for this request. `Deny` still keeps the stable
/// Arduino build directory, so Arduino CLI may perform its own incremental
/// build; it only disables CK's zero-compile early return.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum CkExactReusePolicy {
    Allow,
    Deny,
}

fn ck_exact_reuse_allowed(
    policy: CkExactReusePolicy,
    exact_match: bool,
    libraries_stale: bool,
) -> bool {
    policy == CkExactReusePolicy::Allow && exact_match && !libraries_stale
}

fn ck_exact_reuse_allowed_with_managed_cli(
    policy: CkExactReusePolicy,
    exact_match: bool,
    libraries_stale: bool,
    managed_cli_identity_available: bool,
) -> bool {
    managed_cli_identity_available && ck_exact_reuse_allowed(policy, exact_match, libraries_stale)
}

/// Resolve runtime compiler/tool paths only for an invocation that has already
/// failed (or disabled) authenticated Exact reuse and will now launch either
/// Fast Relink or Arduino CLI.
///
/// Exact already authenticates the complete FQBN/build signature, Core cache
/// identity, dependency content and firmware artifact manifest. Resolving the
/// same Core recipes before that decision adds foreground latency but cannot
/// strengthen the committed Exact proof. Deterministic missing-tool evidence
/// remains fail-closed for every real compile; resolver errors for unfamiliar
/// third-party Cores preserve the existing conservative native-Core fallback.
async fn enforce_runtime_tools_preflight_for_compile<F, Fut>(
    compile_required: bool,
    fqbn: &str,
    preflight: F,
) -> Result<()>
where
    F: FnOnce() -> Fut,
    Fut: std::future::Future<
            Output = Result<crate::builder::direct_engine::RuntimeToolPreflightReport>,
        >,
{
    if !compile_required {
        return Ok(());
    }

    match preflight().await {
        Ok(report) if report.is_blocked() => anyhow::bail!(report.blocking_message(fqbn)),
        Ok(_) => Ok(()),
        Err(error) => {
            log::debug!(
                "Board runtime preflight unavailable for {}; continuing through native Core: {:#}",
                fqbn,
                error
            );
            Ok(())
        }
    }
}

#[cfg(test)]
#[derive(Clone)]
struct TestRuntimeToolsPreflightOverride {
    calls: std::sync::Arc<std::sync::atomic::AtomicUsize>,
    report: crate::builder::direct_engine::RuntimeToolPreflightReport,
}

#[cfg(test)]
tokio::task_local! {
    static TEST_RUNTIME_TOOLS_PREFLIGHT_OVERRIDE: TestRuntimeToolsPreflightOverride;
    static TEST_COMPILE_EXECUTION_BOUNDARY_COUNT: std::sync::Arc<std::sync::atomic::AtomicUsize>;
}

async fn resolve_runtime_tools_preflight_for_compile(
    sysroot_root: &Path,
    fqbn: &str,
    build_path: &Path,
    project_dir: &Path,
    sketch_name: &str,
    property_overrides: &[(String, String)],
    native_release_props_lease: Option<&ToolchainIdentityLease>,
) -> Result<crate::builder::direct_engine::RuntimeToolPreflightReport> {
    #[cfg(test)]
    if let Ok(test_override) = TEST_RUNTIME_TOOLS_PREFLIGHT_OVERRIDE.try_with(Clone::clone) {
        test_override
            .calls
            .fetch_add(1, std::sync::atomic::Ordering::SeqCst);
        return Ok(test_override.report);
    }

    if let Some(identity_lease) = native_release_props_lease {
        let (resolved, _) = resolve_native_release_properties_cached(
            sysroot_root,
            fqbn,
            build_path,
            project_dir,
            sketch_name,
            property_overrides,
            identity_lease,
        )
        .await?;
        return Ok(
            crate::builder::direct_engine::runtime_tool_preflight_from_resolved_props(&resolved),
        );
    }

    crate::builder::direct_engine::preflight_runtime_tools(
        sysroot_root,
        fqbn,
        build_path,
        project_dir,
        sketch_name,
        property_overrides,
    )
    .await
}

async fn enforce_runtime_tools_preflight_for_build_context(
    sysroot: &Sysroot,
    fqbn: &str,
    profile: CompileProfile,
    build_path: &Path,
    project_dir: &Path,
    artifact_project_name: &str,
    native_release_props_lease: Option<&ToolchainIdentityLease>,
) -> Result<()> {
    let property_overrides = command_scoped_build_properties(&sysroot.root_dir, fqbn, profile);
    let sketch_name = format!("{artifact_project_name}.ino");
    enforce_runtime_tools_preflight_for_compile(true, fqbn, || {
        resolve_runtime_tools_preflight_for_compile(
            &sysroot.root_dir,
            fqbn,
            build_path,
            project_dir,
            &sketch_name,
            &property_overrides,
            native_release_props_lease,
        )
    })
    .await
}

#[inline]
fn observe_compile_execution_boundary_for_test() {
    #[cfg(test)]
    {
        let _ = TEST_COMPILE_EXECUTION_BOUNDARY_COUNT.try_with(|count| {
            count.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
        });
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum DependencyResolutionPolicy {
    Managed,
    Locked,
}

fn conservative_default_compile_intent(
    dependency_policy: DependencyResolutionPolicy,
) -> CompileIntent {
    match dependency_policy {
        DependencyResolutionPolicy::Managed => CompileIntent::UploadReady,
        DependencyResolutionPolicy::Locked => CompileIntent::LockedReplay,
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum UntrackedLibraryResolutionPolicy {
    /// Preserve the existing hot-edit behavior: use trusted platform roots,
    /// Arduino build-options roots, and the user's managed sketchbook.
    Compatible,
    /// A project-empty ready-install seed has no library provenance beyond the
    /// exact installed platform. Never widen its search to project/user roots.
    StrictPlatformOnly,
}

/// Only a verified, project-empty QuickFast Core seed may reinterpret the
/// current sketch headers as an initial "added" set. This lets the existing
/// header resolver and strictly validated synthetic CCDB path run without
/// restoring project-specific metadata. Any selected external library, stale
/// project evidence, retry, locked build, or non-QuickFast profile stays on the
/// conservative Arduino CLI path.
fn verified_fresh_core_header_seed_allowed(
    dependency_policy: DependencyResolutionPolicy,
    profile: CompileProfile,
    attempt: usize,
    verified_prebuilt_core_injected: bool,
    project_meta_exists: bool,
    project_backup_exists: bool,
    ccdb_exists: bool,
    extra_library_count: usize,
) -> bool {
    dependency_policy == DependencyResolutionPolicy::Managed
        && profile == CompileProfile::QuickFast
        && attempt == 0
        && verified_prebuilt_core_injected
        && !project_meta_exists
        && !project_backup_exists
        && !ccdb_exists
        && extra_library_count == 0
}

fn locked_build_cache_key(identity: &str) -> Result<String> {
    let identity = identity.trim();
    if identity.is_empty() {
        return Err(anyhow::anyhow!(
            "Locked build identity is empty; an isolated cache cannot be trusted"
        ));
    }
    let digest = format!("{:x}", Sha256::digest(identity.as_bytes()));
    Ok(digest[..24].to_string())
}

fn should_include_global_library_root(
    profile: CompileProfile,
    explicit_compatibility_value: Option<&str>,
) -> bool {
    matches!(
        profile,
        CompileProfile::Release | CompileProfile::PortableFast
    ) || explicit_compatibility_value.is_some_and(|value| {
        matches!(
            value.trim().to_ascii_lowercase().as_str(),
            "1" | "true" | "yes" | "on"
        )
    })
}

const QUICK_FAST_MODE_SUFFIX: &str = "qfast2";
const SHARED_FAST_MODE_SUFFIX: &str = "sfast2";
// Bump whenever relink property resolution changes in a way that makes already-expanded
// cached values unsafe to reuse. This invalidates only the small property cache, not core/object
// build caches.
const FAST_RELINK_PROPS_CACHE_SCHEMA_VERSION: u32 = 5;
const BUILD_META_SCHEMA_VERSION: u32 = 3;
const BUILD_ARTIFACT_MANIFEST_SCHEMA_VERSION: u32 = 1;
// Core archives are only reusable when their compiler-time environment is
// identical. `__DATE__` / `__TIME__` can be affected by SOURCE_DATE_EPOCH and
// TZ, so an identity produced before this guard must not authenticate reuse.
const CORE_CACHE_IDENTITY_SCHEMA_VERSION: u32 = 7;
const CORE_CACHE_IDENTITY_FILE: &str = ".ck-core-cache.json";
const FORCE_REBUILD_MARKER_SUFFIX: &str = ".force-rebuild";
// Arduino requires the sketch directory and the .ino filename to share a
// basename. ESP32 then repeats that basename again in files such as
// `<project>.ino.bootloader.bin`. Keep the readable portion deliberately
// small because several bundled Windows tools still use the legacy MAX_PATH
// limit even when CK itself can address longer paths.
const FQBN_CACHE_READABLE_SLUG_MAX_LEN: usize = 24;
const FQBN_CACHE_HASH_BYTES: usize = 12;

#[derive(Debug, Clone, serde::Serialize)]
pub struct BoardCompileCacheClearReport {
    pub fqbn: String,
    pub removed_entries: usize,
    pub removed_bytes: u64,
    pub force_rebuild_pending: bool,
    /// Machine-readable benchmark scope. The complete canonical target,
    /// including every board menu option, is reset; other configurations are
    /// intentionally left untouched.
    pub reset_scope: String,
    /// Whether the shared ccache object store was deliberately retained.
    pub ccache_store_preserved: bool,
    /// Whether exact-target prebuilt core/full-build snapshots were retained.
    pub prebuilt_core_preserved: bool,
    /// Whether an exact-target, profile-specific v7 identity and `core/core.a`
    /// were verified for the retained prebuilt Core.
    pub prebuilt_core_validated: bool,
    /// Whether the next ccache-enabled compile is required to set
    /// `CCACHE_RECACHE=true` instead of accepting a global ccache hit.
    pub force_ccache_recache: bool,
}

fn build_mode_suffix(profile: CompileProfile) -> &'static str {
    match profile {
        CompileProfile::QuickFast => QUICK_FAST_MODE_SUFFIX,
        CompileProfile::SharedFast => SHARED_FAST_MODE_SUFFIX,
        CompileProfile::PortableFast => "pfast3",
        CompileProfile::Release => "rel",
    }
}

fn canonical_fqbn_cache_identity(fqbn: &str) -> String {
    let trimmed = fqbn.trim();
    let mut parts = trimmed.splitn(4, ':');
    let Some(package) = parts.next().filter(|part| !part.is_empty()) else {
        return trimmed.to_string();
    };
    let Some(architecture) = parts.next().filter(|part| !part.is_empty()) else {
        return trimmed.to_string();
    };
    let Some(board) = parts.next().filter(|part| !part.is_empty()) else {
        return trimmed.to_string();
    };
    let base = format!("{package}:{architecture}:{board}");
    let Some(raw_options) = parts.next() else {
        return base;
    };
    if raw_options.trim().is_empty() {
        return base;
    }

    let mut options = BTreeMap::new();
    for raw_option in raw_options.split(',') {
        let Some((key, value)) = raw_option.trim().split_once('=') else {
            // Invalid/unresolved input retains its exact spelling instead of
            // being silently normalized into another target identity.
            return trimmed.to_string();
        };
        let key = key.trim();
        let value = value.trim();
        if key.is_empty() || value.is_empty() {
            return trimmed.to_string();
        }
        // Last duplicate wins, matching the strict desktop resolver.
        options.insert(key, value);
    }
    let options = options
        .into_iter()
        .map(|(key, value)| format!("{key}={value}"))
        .collect::<Vec<_>>()
        .join(",");
    format!("{base}:{options}")
}

fn filesystem_slug(value: &str, max_len: usize) -> String {
    let mut out = String::with_capacity(value.len().min(max_len));
    let mut prev_is_us = false;
    for ch in value.chars() {
        let mapped = if ch.is_ascii_alphanumeric() { ch } else { '_' };
        let is_us = mapped == '_';
        if is_us && prev_is_us {
            continue;
        }
        out.push(mapped);
        prev_is_us = is_us;
        if out.len() >= max_len {
            break;
        }
    }
    let slug = out.trim_matches('_');
    if slug.is_empty() {
        "board".to_string()
    } else {
        slug.to_string()
    }
}

fn canonical_fqbn_base(identity: &str) -> &str {
    let Some(first) = identity.find(':') else {
        return identity;
    };
    let Some(second_offset) = identity[first + 1..].find(':') else {
        return identity;
    };
    let second = first + 1 + second_offset;
    let Some(third_offset) = identity[second + 1..].find(':') else {
        return identity;
    };
    &identity[..second + 1 + third_offset]
}

/// Previous hashed key format. It is intentionally retained only so an
/// explicit cache refresh can clean directories created by older releases.
/// Reusing those directories after renaming would be unsafe because expanded
/// Arduino recipes contain the old absolute project path and project name.
fn legacy_long_fqbn_cache_key(fqbn: &str) -> String {
    let canonical = canonical_fqbn_cache_identity(fqbn);
    let slug = filesystem_slug(&canonical, 64);
    let digest = Sha256::digest(canonical.as_bytes());
    let short_hash = hex::encode(&digest[..FQBN_CACHE_HASH_BYTES]);
    format!("{slug}_{short_hash}")
}

/// Collision-resistant, path-bounded filesystem identity for one complete
/// board target. Only the base FQBN is kept as a readable hint. Every menu
/// selection (FlashSize, PartitionScheme, PSRAM, USB, and third-party options)
/// remains part of the canonical 96-bit hash, so configurations never share a
/// build directory merely because their readable board names match.
pub fn fqbn_cache_key(fqbn: &str) -> String {
    let canonical = canonical_fqbn_cache_identity(fqbn);
    let readable_base = canonical_fqbn_base(&canonical);
    let slug = filesystem_slug(readable_base, FQBN_CACHE_READABLE_SLUG_MAX_LEN);
    let digest = Sha256::digest(canonical.as_bytes());
    let short_hash = hex::encode(&digest[..FQBN_CACHE_HASH_BYTES]);
    format!("{slug}_{short_hash}")
}

fn fqbn_cache_keys_for_cleanup(fqbn: &str) -> Vec<String> {
    let mut keys = vec![fqbn_cache_key(fqbn), legacy_long_fqbn_cache_key(fqbn)];
    keys.sort();
    keys.dedup();
    keys
}

fn sanitize_fqbn_for_path(fqbn: &str) -> String {
    fqbn_cache_key(fqbn)
}

/// Generated objects live outside the sketch directory.  Arduino CLI and
/// several Core hooks recursively inspect the sketch tree; nesting a large
/// `build/` subtree below the project therefore causes a substantial Windows
/// cold-build penalty.  Keep the readable sketch project (and its matching
/// `.ino` basename) separate from this short, stable object-cache path.
fn short_build_cache_path(cache_dir: &Path, fqbn: &str, profile: CompileProfile) -> PathBuf {
    let key = sanitize_fqbn_for_path(fqbn);
    let suffix = build_mode_suffix(profile);
    // Keep the same `sketch_<key>_<profile>` basename as the source project.
    // Arduino's recipes derive artifact names from this basename, so an
    // out-of-tree build directory without the prefix would make the generated
    // artifacts impossible to discover (and would break upload manifests).
    cache_dir
        .join("build")
        .join(format!("sketch_{key}_{suffix}"))
}

/// Monotonic generation for authorized external Forge qualification probes.
/// `clear_board_first_project_compile_cache` bumps it, so every qualification
/// trial materializes into a fresh, never-reused build directory while the
/// `sketch_<key>_<suffix>` basename (which Arduino recipes derive artifact
/// names from) stays identical to the production layout.
static QUALIFICATION_FRESH_BUILD_GENERATION: std::sync::atomic::AtomicU64 =
    std::sync::atomic::AtomicU64::new(0);

fn qualification_fresh_build_generation() -> u64 {
    QUALIFICATION_FRESH_BUILD_GENERATION.load(std::sync::atomic::Ordering::Acquire)
}

fn rotate_qualification_fresh_build_generation() -> u64 {
    QUALIFICATION_FRESH_BUILD_GENERATION.fetch_add(1, std::sync::atomic::Ordering::AcqRel) + 1
}

fn qualification_fresh_build_root(cache_dir: &Path, generation: u64) -> PathBuf {
    cache_dir.join("build").join(format!("q{generation}"))
}

fn qualification_fresh_build_cache_path(
    cache_dir: &Path,
    fqbn: &str,
    profile: CompileProfile,
    generation: u64,
) -> PathBuf {
    let key = sanitize_fqbn_for_path(fqbn);
    let suffix = build_mode_suffix(profile);
    qualification_fresh_build_root(cache_dir, generation).join(format!("sketch_{key}_{suffix}"))
}

/// Remove every per-generation qualification build root. They exist only
/// during an external A/B capture and must never leak state across trials.
fn clear_qualification_fresh_build_roots(cache_root: &Path) -> std::io::Result<(usize, u64)> {
    let build_root = cache_root.join("build");
    let mut removed_entries = 0usize;
    let mut removed_bytes = 0u64;
    let entries = match std::fs::read_dir(&build_root) {
        Ok(entries) => entries,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
            return Ok((0, 0));
        }
        Err(error) => return Err(error),
    };
    for entry in entries.flatten() {
        let name = entry.file_name();
        let Some(name) = name.to_str() else { continue };
        let Some(generation) = name.strip_prefix('q') else {
            continue;
        };
        if generation.is_empty() || !generation.bytes().all(|byte| byte.is_ascii_digit()) {
            continue;
        }
        let path = entry.path();
        let bytes = cache_path_size(&path);
        if remove_cache_path(&path)? {
            removed_entries += 1;
            removed_bytes = removed_bytes.saturating_add(bytes);
        }
    }
    Ok((removed_entries, removed_bytes))
}

fn has_core_archive(root: &Path) -> bool {
    root.join("core").join("core.a").is_file()
        || root.join("core.a").is_file()
        || root.join("build").join("core").join("core.a").is_file()
        || root.join("build").join("core.a").is_file()
}

fn is_regular_file_without_symlink(path: &Path) -> bool {
    std::fs::symlink_metadata(path)
        .map(|metadata| metadata.file_type().is_file() && !metadata.file_type().is_symlink())
        .unwrap_or(false)
}

/// The native Release config already exposes `<sysroot>/sketchbook/libraries`
/// through `directories.user`. Repeating one of its ordinary descendants as a
/// `--library` argument changes Arduino CLI's `otherLibrariesFolders` whenever
/// the include set changes, which makes Arduino wipe the complete build path.
/// Only an unambiguous, non-reparse descendant may omit the redundant flag;
/// CK/board-package roots outside this exact boundary remain explicit.
fn release_library_is_covered_by_configured_sketchbook(
    sysroot_root: &Path,
    candidate: &Path,
) -> bool {
    let lexical_root = sysroot_root.join("sketchbook").join("libraries");
    let Some(canonical_root) = canonical_directory_without_reparse(&lexical_root) else {
        return false;
    };
    let Ok(relative) = candidate.strip_prefix(&lexical_root) else {
        return false;
    };
    if relative.as_os_str().is_empty() {
        return false;
    }
    let mut lexical = lexical_root;
    for component in relative.components() {
        let std::path::Component::Normal(name) = component else {
            return false;
        };
        lexical.push(name);
        let Ok(metadata) = std::fs::symlink_metadata(&lexical) else {
            return false;
        };
        if metadata_is_link_or_reparse(&metadata) || (!metadata.is_dir() && lexical != candidate) {
            return false;
        }
    }
    let Some(canonical_candidate) = canonical_directory_without_reparse(candidate) else {
        return false;
    };
    canonical_candidate != canonical_root && canonical_candidate.starts_with(canonical_root)
}

/// Check if a fast build cache exists for the exact complete FQBN and profile.
/// A core archive without a matching identity is stale (for example after an
/// ESP32 FlashSize/PartitionScheme/PSRAM change) and must not select the fast
/// upload tier.
pub fn has_warm_build_cache(sysroot: &Sysroot, fqbn: &str, profile: CompileProfile) -> bool {
    let cache_dir = std::env::temp_dir().join("CK_Builds");
    let fqbn_safe = sanitize_fqbn_for_path(fqbn);
    let suffix = build_mode_suffix(profile);
    let expected = expected_core_cache_identity(sysroot, fqbn, profile);
    for candidate in seed_candidate_safes(fqbn, &fqbn_safe) {
        let build_root = cache_dir
            .join("build")
            .join(format!("sketch_{}_{}", candidate, suffix));

        // 1) Active temp build cache (fastest path).
        if has_core_archive(&build_root) && core_cache_identity_matches(&build_root, &expected) {
            return true;
        }

        // 2) Restorable snapshot cache. Metadata alone is not sufficient: it
        // cannot drive fast relink without the matching core archive.
        for snapshot_root in prebuilt_profile_read_roots(sysroot, &candidate, suffix) {
            if has_core_archive(&snapshot_root)
                && core_cache_identity_matches(&snapshot_root, &expected)
            {
                return true;
            }
        }
    }

    false
}

fn has_valid_prebuilt_core_snapshot(
    sysroot: &Sysroot,
    fqbn: &str,
    profile: CompileProfile,
) -> bool {
    let fqbn_safe = sanitize_fqbn_for_path(fqbn);
    let suffix = build_mode_suffix(profile);
    let expected = expected_core_cache_identity(sysroot, fqbn, profile);
    prebuilt_profile_read_roots(sysroot, &fqbn_safe, suffix)
        .into_iter()
        .any(|root| {
            std::fs::symlink_metadata(&root)
                .map(|metadata| metadata.is_dir() && !metadata.file_type().is_symlink())
                .unwrap_or(false)
                && is_regular_file_without_symlink(&root.join("core").join("core.a"))
                && core_cache_identity_matches(&root, &expected)
        })
}

fn force_rebuild_marker_path(fqbn: &str) -> PathBuf {
    std::env::temp_dir().join("CK_Builds").join(format!(
        "{}{}",
        sanitize_fqbn_for_path(fqbn),
        FORCE_REBUILD_MARKER_SUFFIX
    ))
}

fn force_rebuild_marker_paths(fqbn: &str) -> Vec<PathBuf> {
    fqbn_cache_keys_for_cleanup(fqbn)
        .into_iter()
        .map(|key| {
            std::env::temp_dir()
                .join("CK_Builds")
                .join(format!("{key}{FORCE_REBUILD_MARKER_SUFFIX}"))
        })
        .collect()
}

fn cache_path_size(path: &Path) -> u64 {
    let Ok(metadata) = std::fs::symlink_metadata(path) else {
        return 0;
    };
    if metadata.file_type().is_symlink() {
        return 0;
    }
    if metadata.is_file() {
        return metadata.len();
    }
    let mut total = 0u64;
    if let Ok(entries) = std::fs::read_dir(path) {
        for entry in entries.flatten() {
            total = total.saturating_add(cache_path_size(&entry.path()));
        }
    }
    total
}

fn remove_cache_path(path: &Path) -> std::io::Result<bool> {
    let Ok(metadata) = std::fs::symlink_metadata(path) else {
        return Ok(false);
    };
    if metadata.is_dir() && !metadata.file_type().is_symlink() {
        std::fs::remove_dir_all(path)?;
    } else {
        std::fs::remove_file(path)?;
    }
    Ok(true)
}

fn clear_board_compile_cache_paths(
    sysroot: &Sysroot,
    fqbn: &str,
    preserve_prebuilt_core: bool,
) -> std::io::Result<(usize, u64)> {
    let cache_root = std::env::temp_dir().join("CK_Builds");
    let metadata_root = cache_root.join("metadata");
    let prebuilt_roots = sysroot.prebuilt_cores_read_roots();
    let fqbn_safe = sanitize_fqbn_for_path(fqbn);
    let mut candidates = seed_candidate_safes(fqbn, &fqbn_safe);
    // Older hashed paths are safe to remove for this exact FQBN because their
    // digest covered the same canonical complete target. They are never used
    // as build seeds: old expanded recipes embed the longer absolute path.
    candidates.extend(fqbn_cache_keys_for_cleanup(fqbn));
    candidates.sort();
    candidates.dedup();

    let mut paths = Vec::new();
    for candidate in candidates {
        for suffix in [
            QUICK_FAST_MODE_SUFFIX,
            SHARED_FAST_MODE_SUFFIX,
            build_mode_suffix(CompileProfile::PortableFast),
            "rel",
            "qfast",
            "sfast",
            "pfast",
            "pfast2",
        ] {
            // New layout: generated objects are outside the sketch tree.
            paths.push(
                cache_root
                    .join("build")
                    .join(format!("sketch_{}_{}", candidate, suffix)),
            );
            // Remove the legacy nested layout too; it is never reused because
            // its recipes contain the old absolute project path.
            paths.push(cache_root.join(format!("sketch_{}_{}", candidate, suffix)));
            if !preserve_prebuilt_core {
                for root in &prebuilt_roots {
                    paths.push(root.join(format!("sketch_{}_{}", candidate, suffix)));
                }
            }
            paths.push(metadata_root.join(format!("meta_{}_{}.json", candidate, suffix)));
            paths.push(metadata_root.join(format!("backup_{}_{}.ino", candidate, suffix)));
            paths.push(metadata_root.join(format!("warmup_meta_{}_{}.json", candidate, suffix)));
            paths.push(metadata_root.join(format!("warmup_success_{}_{}", candidate, suffix)));
            paths.push(metadata_root.join(format!("relink_props_{}_{}.json", candidate, suffix)));
            paths.push(release_core_seed_certificate_path(
                &metadata_root,
                &candidate,
                suffix,
            ));
        }
        paths.push(cache_root.join("dep_obj_cache").join(candidate));
    }

    paths.sort();
    paths.dedup();
    let mut removed_entries = 0usize;
    let mut removed_bytes = 0u64;
    for path in paths {
        if !path.exists() {
            continue;
        }
        let bytes = cache_path_size(&path);
        if remove_cache_path(&path)? {
            removed_entries += 1;
            removed_bytes = removed_bytes.saturating_add(bytes);
        }
    }
    Ok((removed_entries, removed_bytes))
}

fn clear_prebuilt_project_snapshot_payloads(
    sysroot: &Sysroot,
    fqbn: &str,
) -> std::io::Result<(usize, u64)> {
    let fqbn_safe = sanitize_fqbn_for_path(fqbn);
    let mut candidates = seed_candidate_safes(fqbn, &fqbn_safe);
    candidates.extend(fqbn_cache_keys_for_cleanup(fqbn));
    candidates.sort();
    candidates.dedup();
    let mut paths = Vec::new();
    for candidate in candidates {
        for suffix in [
            QUICK_FAST_MODE_SUFFIX,
            SHARED_FAST_MODE_SUFFIX,
            build_mode_suffix(CompileProfile::PortableFast),
            "rel",
            "qfast",
            "sfast",
            "pfast",
            "pfast2",
        ] {
            for root in sysroot.prebuilt_cores_read_roots() {
                let profile = root.join(format!("sketch_{}_{}", candidate, suffix));
                paths.push(profile.join("build"));
                paths.push(profile.join("snapshot_meta.json"));
                paths.push(profile.join("snapshot_backup.ino"));
                paths.push(profile.join("libraries"));
            }
        }
    }
    paths.sort();
    paths.dedup();
    let mut removed_entries = 0usize;
    let mut removed_bytes = 0u64;
    for path in paths {
        if !path.exists() {
            continue;
        }
        let bytes = cache_path_size(&path);
        if remove_cache_path(&path)? {
            removed_entries += 1;
            removed_bytes = removed_bytes.saturating_add(bytes);
        }
    }
    Ok((removed_entries, removed_bytes))
}

pub fn request_board_compile_cache_rebuild(
    sysroot: &Sysroot,
    fqbn: &str,
) -> Result<BoardCompileCacheClearReport> {
    let (removed_entries, removed_bytes) = clear_board_compile_cache_paths(sysroot, fqbn, false)?;
    let marker = force_rebuild_marker_path(fqbn);
    for legacy_marker in force_rebuild_marker_paths(fqbn) {
        if legacy_marker != marker {
            let _ = std::fs::remove_file(legacy_marker);
        }
    }
    if let Some(parent) = marker.parent() {
        std::fs::create_dir_all(parent)?;
    }
    std::fs::write(&marker, b"force-rebuild-v1")?;
    Ok(BoardCompileCacheClearReport {
        fqbn: fqbn.to_string(),
        removed_entries,
        removed_bytes,
        force_rebuild_pending: true,
        reset_scope: "exact-full-fqbn".to_string(),
        ccache_store_preserved: true,
        prebuilt_core_preserved: false,
        prebuilt_core_validated: false,
        force_ccache_recache: true,
    })
}

/// Prepare a reliable "first project" cold-build benchmark for one exact,
/// complete FQBN.
///
/// Unlike the user-facing hard refresh above, this removes only CK-owned
/// per-target build, metadata, prebuilt and dependency-object caches. The
/// global ccache store remains available and no one-shot recache marker is
/// armed. This intentionally models a configuration without a prepared Core.
/// Any
/// stale marker left by an earlier interrupted hard refresh is removed so the
/// reported mode cannot silently become a hard-refresh measurement.
pub fn clear_board_compile_cache_for_first_project(
    sysroot: &Sysroot,
    fqbn: &str,
) -> Result<BoardCompileCacheClearReport> {
    let (mut removed_entries, mut removed_bytes) =
        clear_board_compile_cache_paths(sysroot, fqbn, false)?;
    // Qualification probe builds live in per-generation roots; remove them all
    // and rotate the generation so the next authorized probe compile starts in
    // a directory no earlier trial has ever touched.
    let (fresh_entries, fresh_bytes) =
        clear_qualification_fresh_build_roots(&std::env::temp_dir().join("CK_Builds"))?;
    removed_entries = removed_entries.saturating_add(fresh_entries);
    removed_bytes = removed_bytes.saturating_add(fresh_bytes);
    rotate_qualification_fresh_build_generation();
    for marker in force_rebuild_marker_paths(fqbn) {
        match std::fs::remove_file(marker) {
            Ok(()) => {}
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {}
            Err(error) => return Err(error.into()),
        }
    }
    Ok(BoardCompileCacheClearReport {
        fqbn: fqbn.to_string(),
        removed_entries,
        removed_bytes,
        force_rebuild_pending: false,
        reset_scope: "first-project-full-fqbn".to_string(),
        ccache_store_preserved: true,
        prebuilt_core_preserved: false,
        prebuilt_core_validated: false,
        force_ccache_recache: false,
    })
}

/// Model the first project on a ready installation. Project build products,
/// metadata, and dependency-object staging are removed, while an exact-target
/// prebuilt Core remains reusable only through its existing v7 identity gate.
/// This is distinct from both a never-seen configuration and user-requested
/// hard refresh.
pub fn clear_board_compile_cache_for_ready_install_project(
    sysroot: &Sysroot,
    fqbn: &str,
) -> Result<BoardCompileCacheClearReport> {
    if !has_valid_prebuilt_core_snapshot(sysroot, fqbn, CompileProfile::QuickFast) {
        anyhow::bail!(
            "ready-install cache reset requires an exact-target validated QuickFast Core"
        );
    }
    let (mut removed_entries, mut removed_bytes) =
        clear_board_compile_cache_paths(sysroot, fqbn, true)?;
    let (snapshot_entries, snapshot_bytes) =
        clear_prebuilt_project_snapshot_payloads(sysroot, fqbn)?;
    removed_entries = removed_entries.saturating_add(snapshot_entries);
    removed_bytes = removed_bytes.saturating_add(snapshot_bytes);
    if !has_valid_prebuilt_core_snapshot(sysroot, fqbn, CompileProfile::QuickFast) {
        anyhow::bail!("ready-install cache reset lost its validated exact-target Core");
    }
    for marker in force_rebuild_marker_paths(fqbn) {
        match std::fs::remove_file(marker) {
            Ok(()) => {}
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {}
            Err(error) => return Err(error.into()),
        }
    }
    Ok(BoardCompileCacheClearReport {
        fqbn: fqbn.to_string(),
        removed_entries,
        removed_bytes,
        force_rebuild_pending: false,
        reset_scope: "ready-install-project-full-fqbn".to_string(),
        ccache_store_preserved: true,
        prebuilt_core_preserved: true,
        prebuilt_core_validated: true,
        force_ccache_recache: false,
    })
}

