    fn standard_esp32_upload_props(
        build: &std::path::Path,
        project: &std::path::Path,
    ) -> HashMap<String, String> {
        let mut props = HashMap::new();
        props.insert(
            "build.project_name".to_string(),
            format!("{}.ino", project.file_name().unwrap().to_string_lossy()),
        );
        props.insert(
            "build.path".to_string(),
            build.to_string_lossy().to_string(),
        );
        props.insert(
            "build.source.path".to_string(),
            project.to_string_lossy().to_string(),
        );
        props.insert("upload.tool".to_string(), "esptool_py".to_string());
        props.insert("upload.extra_flags".to_string(), String::new());
        props.insert(
            "build.custom_bootloader".to_string(),
            "bootloader".to_string(),
        );
        props.insert(
            "build.custom_partitions".to_string(),
            "partitions".to_string(),
        );
        props.insert("build.partitions".to_string(), "default".to_string());
        for key in ESP32_FAST_RELINK_REQUIRED_RECIPES {
            props.insert(key.to_string(), "echo safe-recipe".to_string());
        }
        props
    }

