/// Foreground variant with run-scoped cancellation. Every compiler process
/// spawned on this task is registered with `cancellation`; canceling another
/// run cannot see or terminate these PIDs.
pub async fn compile_sketch_string_cancellable<F, L>(
    sysroot: &Sysroot,
    code: &str,
    fqbn: &str,
    extra_libs: &[PathBuf],
    max_jobs: u32,
    build_signature: &str,
    workspace_fingerprint: Option<&str>,
    profile: CompileProfile,
    exact_reuse_policy: CkExactReusePolicy,
    cancellation: BuildCancellation,
    progress: F,
    log_callback: L,
) -> Result<(PathBuf, String)>
where
    F: Fn(f32, String) + Send + Sync + 'static,
    L: Fn(String) + Send + Sync + 'static,
{
    cancellation.checkpoint()?;
    let cancellation_after = cancellation.clone();
    let result = with_build_cancellation(
        cancellation,
        compile_sketch_string_with_policy(
            sysroot,
            code,
            fqbn,
            extra_libs,
            max_jobs,
            build_signature,
            workspace_fingerprint,
            profile,
            exact_reuse_policy,
            DependencyResolutionPolicy::Managed,
            None,
            progress,
            log_callback,
        ),
    )
    .await;
    cancellation_after.checkpoint()?;
    result
}

