/// Compiles only against an already verified, content-locked dependency set.
///
/// The isolated cache identity must bind the lock file and every dependency
/// content hash. This path never searches the user's global sketchbook and it
/// deliberately avoids Fast Relink, whose historical compilation database can
/// contain providers that are outside the supplied lock.
pub async fn compile_sketch_string_locked<F, L>(
    sysroot: &Sysroot,
    code: &str,
    fqbn: &str,
    locked_libs: &[PathBuf],
    lock_identity: &str,
    max_jobs: u32,
    build_signature: &str,
    workspace_fingerprint: Option<&str>,
    profile: CompileProfile,
    exact_reuse_policy: CkExactReusePolicy,
    progress: F,
    log_callback: L,
) -> Result<(PathBuf, String)>
where
    F: Fn(f32, String) + Send + Sync + 'static,
    L: Fn(String) + Send + Sync + 'static,
{
    let cache_key = locked_build_cache_key(lock_identity)?;
    compile_sketch_string_with_policy(
        sysroot,
        code,
        fqbn,
        locked_libs,
        max_jobs,
        build_signature,
        workspace_fingerprint,
        profile,
        exact_reuse_policy,
        DependencyResolutionPolicy::Locked,
        Some(cache_key.as_str()),
        progress,
        log_callback,
    )
    .await
}

