    fn esp32_verbose_link_fixture() -> (tempfile::TempDir, PathBuf, PathBuf, PathBuf, String) {
        let temp = tempfile::tempdir().expect("ESP32 verbose link fixture");
        let build = temp.path().join("build");
        let sketch = build.join("sketch").join("probe.ino.cpp.o");
        let library = build.join("libraries").join("Foo").join("Foo.cpp.o");
        let core = build.join("core").join("core.a");
        for path in [&sketch, &library, &core] {
            std::fs::create_dir_all(path.parent().expect("fixture parent"))
                .expect("fixture directory");
            std::fs::write(path, b"evidence").expect("fixture evidence");
        }
        let line = format!(
            "g++ -Wl,--start-group \"{}\" \"{}\" \"{}\" -Wl,--end-group -o \"{}\"",
            sketch.display(),
            library.display(),
            core.display(),
            build.join("probe.ino.elf").display()
        );
        (temp, build, sketch, library, line)
    }

    #[test]
    fn native_relink_ccdb_working_directory_migration_is_systemic_and_fail_closed() {
        let temp = tempfile::tempdir().expect("working-directory migration fixture");
        let build = temp.path().join("build");
        let stable = temp.path().join("managed-cli-cwd");
        std::fs::create_dir_all(&build).expect("build fixture");
        std::fs::create_dir_all(&stable).expect("stable working directory fixture");
        let ccdb = build.join("compile_commands.json");
        let entry = |directory: String| CompileCommandEntry {
            directory,
            arguments: vec!["avr-g++".into(), "-c".into(), "sketch.cpp".into()],
            command: String::new(),
            file: "sketch.cpp".into(),
            output: Some("sketch.cpp.o".into()),
        };

        std::fs::write(
            &ccdb,
            serde_json::to_vec(&vec![entry(stable.to_string_lossy().into_owned())])
                .expect("stable CCDB"),
        )
        .expect("write stable CCDB");
        assert!(!native_relink_ccdb_requires_working_directory_migration(
            &build, &stable
        ));
        #[cfg(windows)]
        {
            let extended = format!("\\\\?\\{}", stable.display());
            std::fs::write(
                &ccdb,
                serde_json::to_vec(&vec![entry(extended)]).expect("extended stable CCDB"),
            )
            .expect("write extended stable CCDB");
            assert!(!native_relink_ccdb_requires_working_directory_migration(
                &build, &stable
            ));
        }

        let old_install = temp.path().join("old-install").join("CK");
        std::fs::write(
            &ccdb,
            serde_json::to_vec(&vec![entry(old_install.to_string_lossy().into_owned())])
                .expect("legacy CCDB"),
        )
        .expect("write legacy CCDB");
        assert!(native_relink_ccdb_requires_working_directory_migration(
            &build, &stable
        ));

        std::fs::write(
            &ccdb,
            serde_json::to_vec(&vec![
                entry(stable.to_string_lossy().into_owned()),
                entry("relative-install-directory".into()),
            ])
            .expect("mixed CCDB"),
        )
        .expect("write mixed CCDB");
        assert!(native_relink_ccdb_requires_working_directory_migration(
            &build, &stable
        ));

        std::fs::write(&ccdb, b"not-json").expect("write malformed CCDB");
        assert!(native_relink_ccdb_requires_working_directory_migration(
            &build, &stable
        ));
        std::fs::remove_file(&ccdb).expect("remove CCDB");
        assert!(!native_relink_ccdb_requires_working_directory_migration(
            &build, &stable
        ));
    }

    #[test]
    fn esp32_native_link_capture_reassembles_fragments_and_preserves_order() {
        let (_temp, build, sketch, library, line) = esp32_verbose_link_fixture();
        let core = build.join("core").join("core.a");
        let working_directory = _temp.path().join("cli-working-directory");
        std::fs::create_dir(&working_directory).expect("CLI working directory");
        let split = line.len() / 2;
        let mut capture = Esp32NativeLinkLineCapture::default();
        capture.observe(&line[..split], false, false);
        capture.observe(&line[split..], true, false);
        let captured = capture
            .finish(&build, &core, &working_directory)
            .expect("one fragmented native link command");
        assert_eq!(
            captured.working_directory,
            std::fs::canonicalize(&working_directory).expect("canonical CLI working directory")
        );
        assert_eq!(
            captured.ordered_link_inputs,
            vec![
                std::fs::canonicalize(sketch).expect("canonical sketch object"),
                std::fs::canonicalize(library).expect("canonical library object"),
            ]
        );
    }

    #[test]
    fn esp32_native_link_capture_resolves_relative_tokens_from_explicit_spawn_cwd() {
        let (temp, build, sketch, library, line) = esp32_verbose_link_fixture();
        let core = build.join("core").join("core.a");
        let prefix = format!("{}{}", temp.path().display(), std::path::MAIN_SEPARATOR);
        let relative_line = line.replace(&prefix, "");
        let mut capture = Esp32NativeLinkLineCapture::default();
        capture.observe(&relative_line, true, false);
        let captured = capture
            .finish(&build, &core, temp.path())
            .expect("relative link inputs resolve from the launch cwd");
        assert_eq!(
            captured.ordered_link_inputs,
            vec![
                std::fs::canonicalize(sketch).expect("canonical sketch object"),
                std::fs::canonicalize(library).expect("canonical library object"),
            ]
        );

        let wrong = temp.path().join("wrong-cwd");
        std::fs::create_dir(&wrong).expect("wrong cwd fixture");
        let mut wrong_capture = Esp32NativeLinkLineCapture::default();
        wrong_capture.observe(&relative_line, true, false);
        assert!(
            wrong_capture.finish(&build, &core, &wrong).is_err(),
            "the same relative argv must not resolve under a different cwd"
        );
    }

