    /// Keep NativeReleasePropsCache fixtures below the same managed root that
    /// production key construction accepts.  This prevents a unit test from
    /// accidentally weakening the path-boundary contract just to exercise the
    /// in-memory cache.
    fn native_release_props_cache_fixture(
        label: &str,
    ) -> (
        tempfile::TempDir,
        PathBuf,
        PathBuf,
        PathBuf,
        super::ToolchainIdentityLease,
        String,
    ) {
        let managed_root = std::env::temp_dir().join("CK_Builds");
        std::fs::create_dir_all(&managed_root).expect("managed cache root");
        let temp = tempfile::tempdir_in(&managed_root).expect("native props cache tempdir");
        let sysroot = temp.path().join("sysroot");
        let build = temp.path().join("build");
        let project = temp.path().join("project");
        for directory in [&sysroot, &build, &project] {
            std::fs::create_dir_all(directory).expect("native props fixture directory");
        }
        let fqbn = "arduino:avr:uno".to_string();
        let lease = super::ToolchainIdentityLease {
            canonical_sysroot: std::fs::canonicalize(&sysroot).expect("canonical fixture sysroot"),
            complete_fqbn: fqbn.clone(),
            toolchain_key: format!("native-props-cache-{label}"),
            resolution_source: super::ToolchainIdentityResolutionSource::StrongContent,
            managed_cli_identity_available: true,
            generation: super::toolchain_identity_cache_generation(),
        };
        (temp, sysroot, build, project, lease, fqbn)
    }

    #[test]
    fn native_release_props_cache_key_is_bound_to_all_avr_request_inputs() {
        let _identity_scope = process_identity_test_scope();
        super::invalidate_process_toolchain_identity_cache();
        let (_temp, sysroot, build, project, lease, fqbn) =
            native_release_props_cache_fixture("key-inputs");
        super::clear_native_release_resolved_props_cache();
        let overrides = vec![
            ("compiler.cpp.extra_flags".to_string(), "-DCK_A".to_string()),
            ("compiler.cpp.extra_flags".to_string(), "-DCK_B".to_string()),
        ];
        let key = super::native_release_props_cache_key(
            &sysroot,
            &fqbn,
            &build,
            &project,
            "sketch.ino",
            &overrides,
            &lease,
        )
        .expect("base NativeRelease key")
        .expect("AVR key must be eligible");
        let same_key = super::native_release_props_cache_key(
            &sysroot,
            &fqbn,
            &build,
            &project,
            "sketch.ino",
            &overrides,
            &lease,
        )
        .expect("repeat NativeRelease key")
        .expect("repeat AVR key must be eligible");
        assert_eq!(key, same_key, "identical requests must share one key");

        let resolved = std::sync::Arc::new(crate::builder::direct_engine::ResolvedProps {
            props: HashMap::from([(String::from("test.cache"), String::from("base"))]),
        });
        super::insert_native_release_properties(key.clone(), resolved);
        assert!(
            super::lookup_native_release_properties(&key).is_some(),
            "base key should be retrievable"
        );

        let assert_miss = |candidate: super::NativeReleasePropsCacheKey, reason: &str| {
            assert!(
                super::lookup_native_release_properties(&candidate).is_none(),
                "{reason} must not reuse the base resolved properties"
            );
        };

        let mut changed_fqbn_lease = lease.clone();
        changed_fqbn_lease.complete_fqbn = "arduino:avr:uno:Clock=16MHz".to_string();
        let changed_fqbn = super::native_release_props_cache_key(
            &sysroot,
            &changed_fqbn_lease.complete_fqbn,
            &build,
            &project,
            "sketch.ino",
            &overrides,
            &changed_fqbn_lease,
        )
        .expect("changed FQBN key")
        .expect("changed AVR FQBN remains eligible");
        assert_miss(changed_fqbn, "complete FQBN");

        let changed_build = build.join("other-build");
        std::fs::create_dir_all(&changed_build).expect("changed build directory");
        let changed_build_key = super::native_release_props_cache_key(
            &sysroot,
            &fqbn,
            &changed_build,
            &project,
            "sketch.ino",
            &overrides,
            &lease,
        )
        .expect("changed build key")
        .expect("changed build remains eligible");
        assert_miss(changed_build_key, "build path");

        let changed_project = project.join("other-project");
        std::fs::create_dir_all(&changed_project).expect("changed project directory");
        let changed_project_key = super::native_release_props_cache_key(
            &sysroot,
            &fqbn,
            &build,
            &changed_project,
            "sketch.ino",
            &overrides,
            &lease,
        )
        .expect("changed project key")
        .expect("changed project remains eligible");
        assert_miss(changed_project_key, "project path");

        let changed_sketch = super::native_release_props_cache_key(
            &sysroot,
            &fqbn,
            &build,
            &project,
            "other.ino",
            &overrides,
            &lease,
        )
        .expect("changed sketch key")
        .expect("changed sketch remains eligible");
        assert_miss(changed_sketch, "sketch filename");

        let reordered_overrides = vec![
            ("compiler.cpp.extra_flags".to_string(), "-DCK_B".to_string()),
            ("compiler.cpp.extra_flags".to_string(), "-DCK_A".to_string()),
        ];
        let reordered = super::native_release_props_cache_key(
            &sysroot,
            &fqbn,
            &build,
            &project,
            "sketch.ino",
            &reordered_overrides,
            &lease,
        )
        .expect("reordered override key")
        .expect("reordered overrides remain eligible");
        assert_miss(reordered, "ordered property overrides");

        let mut changed_toolchain_lease = lease.clone();
        changed_toolchain_lease.toolchain_key.push_str("-different");
        let changed_toolchain = super::native_release_props_cache_key(
            &sysroot,
            &fqbn,
            &build,
            &project,
            "sketch.ino",
            &overrides,
            &changed_toolchain_lease,
        )
        .expect("changed toolchain key")
        .expect("changed toolchain remains eligible");
        assert_miss(changed_toolchain, "toolchain identity");

        let mut changed_generation = key.clone();
        changed_generation.toolchain_generation =
            changed_generation.toolchain_generation.saturating_add(1);
        assert_miss(changed_generation, "lease generation");

        super::clear_native_release_resolved_props_cache();
    }

    #[test]
    fn native_release_props_cache_allows_only_authorized_samd_adapter_requests() {
        let _identity_scope = process_identity_test_scope();
        super::invalidate_process_toolchain_identity_cache();
        let (_temp, sysroot, build, project, lease, _fqbn) =
            native_release_props_cache_fixture("samd-scope");
        super::clear_native_release_resolved_props_cache();

        let samd_fqbn = "arduino:samd:mkrzero";
        let mut samd_lease = lease.clone();
        samd_lease.complete_fqbn = samd_fqbn.to_string();
        samd_lease.toolchain_key = "native-props-cache-samd".to_string();
        let authorized = super::authorized_native_release_props_lease(
            true,
            CompileProfile::Release,
            DependencyResolutionPolicy::Managed,
            samd_fqbn,
            &samd_lease,
        )
        .expect("authorized SAMD compile-only request should receive a cache lease");
        let samd_key = super::native_release_props_cache_key(
            &sysroot,
            samd_fqbn,
            &build,
            &project,
            "sketch.ino",
            &[],
            authorized,
        )
        .expect("authorized SAMD key decision")
        .expect("authorized SAMD adapter should be cache eligible");
        super::insert_native_release_properties(
            samd_key.clone(),
            std::sync::Arc::new(crate::builder::direct_engine::ResolvedProps {
                props: HashMap::from([(String::from("test.cache"), String::from("samd"))]),
            }),
        );
        assert!(super::lookup_native_release_properties(&samd_key).is_some());

        for (authorized, profile, policy, label) in [
            (
                false,
                CompileProfile::Release,
                DependencyResolutionPolicy::Managed,
                "ordinary unapproved SAMD request",
            ),
            (
                true,
                CompileProfile::QuickFast,
                DependencyResolutionPolicy::Managed,
                "non-Release SAMD request",
            ),
            (
                true,
                CompileProfile::Release,
                DependencyResolutionPolicy::Locked,
                "Locked SAMD request",
            ),
        ] {
            assert!(
                super::authorized_native_release_props_lease(
                    authorized,
                    profile,
                    policy,
                    samd_fqbn,
                    &samd_lease,
                )
                .is_none(),
                "{label} must not receive a NativeReleasePropsCache lease"
            );
        }

        let unknown_fqbn = "acme:samd:custom";
        let mut unknown_lease = samd_lease.clone();
        unknown_lease.complete_fqbn = unknown_fqbn.to_string();
        assert!(
            super::authorized_native_release_props_lease(
                true,
                CompileProfile::Release,
                DependencyResolutionPolicy::Managed,
                unknown_fqbn,
                &unknown_lease,
            )
            .is_none(),
            "an unknown SAMD-compatible Core must not inherit Arduino SAMD cache trust"
        );
        assert!(
            super::native_release_props_cache_key(
                &sysroot,
                unknown_fqbn,
                &build,
                &project,
                "sketch.ino",
                &[],
                &unknown_lease,
            )
            .expect("unknown Core key decision")
            .is_none(),
            "the key builder must also fail closed for unknown Cores"
        );
        super::clear_native_release_resolved_props_cache();
    }

    #[test]
    fn native_release_props_cache_rejects_unknown_core_and_invalidates_with_toolchain_generation() {
        let _identity_scope = process_identity_test_scope();
        super::invalidate_process_toolchain_identity_cache();
        let (_temp, sysroot, build, project, lease, fqbn) =
            native_release_props_cache_fixture("scope");
        // Generic ESP32 bases are all phase-1 adapter family members; a named
        // variant without a qualified adapter remains the unknown-Core exemplar.
        let non_adapter = super::native_release_props_cache_key(
            &sysroot,
            "esp32:esp32:esp32wrover",
            &build,
            &project,
            "sketch.ino",
            &[],
            &lease,
        )
        .expect("unknown Core cache key decision");
        assert!(
            non_adapter.is_none(),
            "unknown Cores must not use this cache"
        );

        let key = super::native_release_props_cache_key(
            &sysroot,
            &fqbn,
            &build,
            &project,
            "sketch.ino",
            &[],
            &lease,
        )
        .expect("AVR cache key")
        .expect("AVR key must be eligible");
        super::insert_native_release_properties(
            key.clone(),
            std::sync::Arc::new(crate::builder::direct_engine::ResolvedProps {
                props: HashMap::from([(String::from("test.cache"), String::from("scope"))]),
            }),
        );
        assert!(super::lookup_native_release_properties(&key).is_some());
        let generation_before = super::toolchain_identity_cache_generation();
        super::invalidate_process_toolchain_identity_cache();
        assert!(
            super::toolchain_identity_cache_generation() > generation_before,
            "identity invalidation must advance the generation"
        );
        assert!(
            super::lookup_native_release_properties(&key).is_none(),
            "entries from the old lease generation must not survive invalidation"
        );
        assert_eq!(
            super::native_release_props_cache()
                .lock()
                .expect("props cache lock")
                .len(),
            0,
            "identity invalidation should clear stale props eagerly"
        );
        super::clear_native_release_resolved_props_cache();
    }

    #[test]
    fn native_release_props_cache_enforces_capacity_and_expiry() {
        let _identity_scope = process_identity_test_scope();
        super::invalidate_process_toolchain_identity_cache();
        let (_temp, sysroot, build, project, lease, fqbn) =
            native_release_props_cache_fixture("capacity");
        super::clear_native_release_resolved_props_cache();
        let base = super::native_release_props_cache_key(
            &sysroot,
            &fqbn,
            &build,
            &project,
            "sketch.ino",
            &[],
            &lease,
        )
        .expect("capacity base key")
        .expect("capacity AVR key");
        let mut keys = Vec::new();
        for index in 0..(super::NATIVE_RELEASE_PROPS_CACHE_MAX_ENTRIES + 1) {
            let mut key = base.clone();
            key.sketch_name = format!("sketch-{index}.ino");
            super::insert_native_release_properties(
                key.clone(),
                std::sync::Arc::new(crate::builder::direct_engine::ResolvedProps {
                    props: HashMap::from([(String::from("test.index"), index.to_string())]),
                }),
            );
            // Make eviction deterministic even on a coarse-resolution host
            // clock: lower indexes are older, but all remain inside the TTL.
            if let Some(entry) = super::native_release_props_cache()
                .lock()
                .expect("props cache lock")
                .get_mut(&key)
            {
                entry.inserted_at = std::time::Instant::now()
                    - std::time::Duration::from_millis(
                        (super::NATIVE_RELEASE_PROPS_CACHE_MAX_ENTRIES + 1 - index) as u64,
                    );
            }
            keys.push(key);
        }
        let cache_len = super::native_release_props_cache()
            .lock()
            .expect("props cache lock")
            .len();
        assert_eq!(
            cache_len,
            super::NATIVE_RELEASE_PROPS_CACHE_MAX_ENTRIES,
            "cache must remain bounded"
        );
        assert!(
            super::lookup_native_release_properties(keys.last().expect("latest key")).is_some(),
            "newest entry must remain after capacity eviction"
        );
        assert!(
            super::lookup_native_release_properties(&keys[0]).is_none(),
            "oldest entry must be evicted when capacity is exceeded"
        );

        let latest = keys.last().expect("latest key").clone();
        if let Some(entry) = super::native_release_props_cache()
            .lock()
            .expect("props cache lock")
            .get_mut(&latest)
        {
            entry.inserted_at = std::time::Instant::now()
                - (super::NATIVE_RELEASE_PROPS_CACHE_MAX_AGE + std::time::Duration::from_secs(1));
        }
        assert!(
            super::lookup_native_release_properties(&latest).is_none(),
            "entries older than the fixed TTL must not be reused"
        );
        super::clear_native_release_resolved_props_cache();
    }

