    #[tokio::test]
    async fn compile_future_stack_footprint_is_bounded_for_desktop_invocation() {
        let temp = tempfile::tempdir().expect("future-size tempdir");
        let sysroot = crate::sysroot::Sysroot::init(
            Some(temp.path().join("sysroot")),
            "ck-builder-future-size-test",
        )
        .await
        .expect("future-size sysroot");
        let fqbn = unique_test_board();
        let lease = super::ToolchainIdentityLease::begin(&sysroot.root_dir, &fqbn)
            .expect("future-size identity lease");
        let access = super::NativeRelinkAccess::disabled();
        let future = super::compile_sketch_string_with_policy_and_identity_lease(
            &sysroot,
            "void setup() {}\nvoid loop() {}\n",
            &fqbn,
            &[],
            1,
            "future-size-signature",
            None,
            CompileProfile::Release,
            CkExactReusePolicy::Deny,
            CompileIntent::CompileOnly,
            DependencyResolutionPolicy::Managed,
            None,
            &lease,
            &access,
            false,
            |_percentage, _message| {},
            |_line| {},
        );
        let bytes = std::mem::size_of_val(&future);
        eprintln!("compile future size: {bytes} bytes");
        // A Tauri command can initially be polled on the Windows GUI thread,
        // whose stack is much smaller than a dedicated compiler worker. Keep
        // the state machine bounded and move architecture-specific work behind
        // heap/worker boundaries.
        assert!(bytes <= 256 * 1024, "compile future grew to {bytes} bytes");
        drop(future);
    }

