    #[test]
    fn esp32_library_route_is_qualification_only_and_requires_a_library_graph() {
        let access = |mode| super::NativeRelinkAccess {
            mode,
            target_binding: "test-target-binding".into(),
            authorization_key: "test-authorization".into(),
        };
        let disabled = access(super::NativeRelinkAccessMode::Disabled);
        let certified = access(super::NativeRelinkAccessMode::Certified);
        let probe = access(super::NativeRelinkAccessMode::QualificationProbe);
        let arduino_only = analyze_include_graph_for_relink(
            "#include <Arduino.h>\nvoid setup(){}\nvoid loop(){}\n",
        );
        let library_header = analyze_include_graph_for_relink(
            "#include <Arduino.h>\n#include <ProbeSensor.h>\nvoid setup(){}\nvoid loop(){}\n",
        );
        let selected_library = vec![PathBuf::from("selected-library")];
        let eligible = |access: &NativeRelinkAccess, extra_libs: &[PathBuf], include_analysis| {
            super::esp32_library_relink_qualification_candidate(
                access,
                CompileProfile::Release,
                DependencyResolutionPolicy::Managed,
                CompileIntent::CompileOnly,
                "esp32:esp32:esp32c6",
                0,
                false,
                extra_libs,
                include_analysis,
            )
        };

        assert!(!eligible(&probe, &[], &arduino_only));
        assert!(eligible(&probe, &selected_library, &arduino_only));
        assert!(eligible(&probe, &[], &library_header));
        assert!(!eligible(&disabled, &selected_library, &arduino_only));
        assert!(!eligible(&certified, &selected_library, &arduino_only));

        for (profile, policy, intent, attempt, force) in [
            (
                CompileProfile::QuickFast,
                DependencyResolutionPolicy::Managed,
                CompileIntent::CompileOnly,
                0,
                false,
            ),
            (
                CompileProfile::Release,
                DependencyResolutionPolicy::Locked,
                CompileIntent::CompileOnly,
                0,
                false,
            ),
            (
                CompileProfile::Release,
                DependencyResolutionPolicy::Managed,
                CompileIntent::UploadReady,
                0,
                false,
            ),
            (
                CompileProfile::Release,
                DependencyResolutionPolicy::Managed,
                CompileIntent::CompileOnly,
                1,
                false,
            ),
            (
                CompileProfile::Release,
                DependencyResolutionPolicy::Managed,
                CompileIntent::CompileOnly,
                0,
                true,
            ),
        ] {
            assert!(!super::esp32_library_relink_qualification_candidate(
                &probe,
                profile,
                policy,
                intent,
                "esp32:esp32:esp32c6",
                attempt,
                force,
                &selected_library,
                &arduino_only,
            ));
        }
    }

    #[test]
    fn native_relink_engine_contract_dispatch_is_three_way_and_distinct() {
        use super::native_relink_engine_contract_for_fqbn as contract_for;
        assert_eq!(
            contract_for("arduino:avr:uno"),
            super::native_relink::NATIVE_RELINK_ENGINE_CONTRACT
        );
        assert_eq!(
            contract_for("arduino:samd:mkrzero"),
            super::samd_native_relink::SAMD_NATIVE_RELINK_ENGINE_CONTRACT
        );
        assert_eq!(
            contract_for("esp32:esp32:esp32c6"),
            super::esp32_native_relink::ESP32_NATIVE_RELINK_ENGINE_CONTRACT
        );
        assert_eq!(
            contract_for("esp32:esp32:esp32c6:FlashSize=16M"),
            super::esp32_native_relink::ESP32_NATIVE_RELINK_ENGINE_CONTRACT
        );
        // The binding dispatch is prefix-scoped on purpose: every esp32:esp32:
        // target hashes the ESP32 contract, never the AVR default, even before
        // that board gains its own qualified adapter row.
        assert_eq!(
            contract_for("esp32:esp32:esp32s3"),
            super::esp32_native_relink::ESP32_NATIVE_RELINK_ENGINE_CONTRACT
        );
        let contracts = [
            contract_for("arduino:avr:uno"),
            contract_for("arduino:samd:mkrzero"),
            contract_for("esp32:esp32:esp32c6"),
        ];
        for (index, left) in contracts.iter().enumerate() {
            for right in &contracts[index + 1..] {
                assert_ne!(left, right, "engine contracts must be pairwise distinct");
            }
        }
    }

