    #[test]
    fn esp32_native_relink_sketch_argv_replaces_only_the_ccache_shim_spelling() {
        let temp = tempfile::tempdir().expect("esp32 argv tempdir");
        let sysroot_root = temp.path().join("sysroot");
        let shim_dir = sysroot_root.join("bin").join("ccache");
        let tool_dir = temp.path().join("tools").join("bin");
        std::fs::create_dir_all(&shim_dir).expect("shim dir");
        std::fs::create_dir_all(&tool_dir).expect("tool dir");
        let shim = shim_dir.join("riscv32-esp-elf-g++.exe");
        let real = tool_dir.join("riscv32-esp-elf-g++.exe");
        std::fs::write(&shim, b"shim").expect("shim tool");
        std::fs::write(&real, b"real").expect("real tool");
        let mut props = HashMap::new();
        props.insert(
            "compiler.path".to_string(),
            format!("{}/", tool_dir.to_string_lossy().replace('\\', "/")),
        );

        let shim_argv = vec![
            shim.to_string_lossy().replace('\\', "/"),
            "-MMD".to_string(),
            "@flags/cpp_flags".to_string(),
        ];
        let rewritten =
            super::esp32_native_relink_sketch_compile_argv(&sysroot_root, &props, &shim_argv)
                .expect("shim argv rewrite");
        assert_eq!(
            normalize_dep_path_key(&PathBuf::from(&rewritten[0])),
            normalize_dep_path_key(&real),
            "the shim token must be rewritten to the real toolchain compiler"
        );
        assert_eq!(&rewritten[1..], &shim_argv[1..]);

        let native_argv = vec![real.to_string_lossy().into_owned(), "-c".to_string()];
        assert_eq!(
            super::esp32_native_relink_sketch_compile_argv(&sysroot_root, &props, &native_argv)
                .expect("native argv is preserved"),
            native_argv,
            "a native Release argv must stay byte-identical"
        );

        assert!(
            super::esp32_native_relink_sketch_compile_argv(&sysroot_root, &props, &[]).is_err()
        );

        let mut broken_props = HashMap::new();
        broken_props.insert(
            "compiler.path".to_string(),
            format!("{}/missing/", tool_dir.to_string_lossy().replace('\\', "/")),
        );
        assert!(
            super::esp32_native_relink_sketch_compile_argv(
                &sysroot_root,
                &broken_props,
                &shim_argv
            )
            .is_err(),
            "a shim spelling with no resolvable real compiler must fail closed"
        );
    }

