    #[test]
    fn native_relink_access_is_host_target_toolchain_and_mode_bound() {
        let root = tempfile::tempdir().expect("sysroot");
        let fqbn = "arduino:avr:uno";
        let lease = ToolchainIdentityLease::begin(root.path(), fqbn).expect("identity lease");
        let probe = NativeRelinkAccess::qualification_probe(root.path(), fqbn, &lease)
            .expect("probe access");
        let certified = NativeRelinkAccess::certified(root.path(), fqbn, &lease, &"b".repeat(64))
            .expect("certified access");
        assert!(probe.is_authorized_for(root.path(), fqbn, &lease));
        assert!(certified.is_authorized_for(root.path(), fqbn, &lease));
        assert_ne!(probe.authorization_key(), certified.authorization_key());
        assert!(!NativeRelinkAccess::disabled().is_authorized_for(root.path(), fqbn, &lease));
        assert!(!probe.is_authorized_for(root.path(), "arduino:avr:nano", &lease));

        let samd_fqbn = "arduino:samd:mkrzero";
        let samd_lease =
            ToolchainIdentityLease::begin(root.path(), samd_fqbn).expect("SAMD identity lease");
        let samd_probe =
            NativeRelinkAccess::qualification_probe(root.path(), samd_fqbn, &samd_lease)
                .expect("SAMD probe access");
        assert!(samd_probe.is_authorized_for(root.path(), samd_fqbn, &samd_lease));
        assert_ne!(
            probe.authorization_key(),
            samd_probe.authorization_key(),
            "AVR and SAMD engine contracts must never share access keys"
        );

        let esp32_fqbn = "esp32:esp32:esp32c6";
        let esp32_lease =
            ToolchainIdentityLease::begin(root.path(), esp32_fqbn).expect("ESP32 identity lease");
        let esp32_probe =
            NativeRelinkAccess::qualification_probe(root.path(), esp32_fqbn, &esp32_lease)
                .expect("ESP32 probe access");
        assert!(esp32_probe.is_authorized_for(root.path(), esp32_fqbn, &esp32_lease));
        assert_ne!(
            probe.authorization_key(),
            esp32_probe.authorization_key(),
            "AVR and ESP32 engine contracts must never share access keys"
        );
        assert_ne!(
            samd_probe.authorization_key(),
            esp32_probe.authorization_key(),
            "SAMD and ESP32 engine contracts must never share access keys"
        );
    }

