    #[test]
    fn dependency_only_probe_preserves_inputs_and_replaces_all_compiler_outputs() {
        let temp = tempfile::tempdir().expect("tempdir");
        let source = temp.path().join("startup unit.S");
        let object = temp.path().join("build").join("startup unit.S.o");
        let old_depfile = temp.path().join("old dependency.d");
        let temporary_depfile = temp.path().join("build").join(".startup-probe.tmp");
        std::fs::create_dir_all(object.parent().unwrap()).expect("build directory");
        std::fs::write(&source, b"#include \"startup.h\"\n").expect("source");
        std::fs::write(&object, b"object").expect("object");
        let entry = CompileCommandEntry {
            directory: temp.path().to_string_lossy().into_owned(),
            arguments: vec![
                "arm-none-eabi-gcc".into(),
                "-mcpu=cortex-m4".into(),
                "@build.opt".into(),
                "-DSTM32F401xE".into(),
                "-Iinclude root".into(),
                "-c".into(),
                "-MMD".into(),
                "-MP".into(),
                "-MF".into(),
                old_depfile.to_string_lossy().into_owned(),
                "-MTold-target".into(),
                source.to_string_lossy().into_owned(),
                "-o".into(),
                object.to_string_lossy().into_owned(),
            ],
            command: String::new(),
            file: source.to_string_lossy().into_owned(),
            output: Some(object.to_string_lossy().into_owned()),
        };

        let tokens = dependency_only_probe_tokens(&entry, &temporary_depfile, &object)
            .expect("dependency-only probe tokens");
        assert_eq!(tokens[0], "arm-none-eabi-gcc");
        assert!(tokens.contains(&"-mcpu=cortex-m4".to_string()));
        assert!(tokens.contains(&"@build.opt".to_string()));
        assert!(tokens.contains(&"-DSTM32F401xE".to_string()));
        assert!(tokens.contains(&"-Iinclude root".to_string()));
        assert!(tokens.contains(&source.to_string_lossy().into_owned()));
        assert!(!tokens.contains(&"-c".to_string()));
        assert!(!tokens.contains(&"-MMD".to_string()));
        assert!(!tokens.contains(&"-MP".to_string()));
        assert!(!tokens.contains(&old_depfile.to_string_lossy().into_owned()));
        assert!(!tokens.contains(&"-MTold-target".to_string()));
        assert_eq!(
            &tokens[tokens.len() - 5..],
            &[
                "-M".to_string(),
                "-MF".to_string(),
                temporary_depfile.to_string_lossy().into_owned(),
                "-MT".to_string(),
                object.to_string_lossy().into_owned(),
            ]
        );

        let mut shell_entry = entry;
        shell_entry.arguments.clear();
        shell_entry.command = format!("gcc {} -o out.o && echo unsafe", source.display());
        assert!(
            dependency_only_probe_tokens(&shell_entry, &temporary_depfile, &object).is_err(),
            "shell composition must remain fail-closed"
        );
    }

