    #[test]
    fn synthetic_include_graph_accepts_only_unconditional_literal_includes() {
        let safe = analyze_include_graph_for_relink(
            "#include <Arduino.h>\n# include \"drivers/local.hpp\"\nvoid setup() {}\n",
        );
        assert!(safe.synthesis_safe);
        assert_eq!(
            safe.headers.into_iter().collect::<Vec<_>>(),
            vec!["arduino.h", "drivers/local.hpp"]
        );

        let conditional =
            analyze_include_graph_for_relink("#if defined(ESP32)\n#include <WiFi.h>\n#endif\n");
        assert!(!conditional.synthesis_safe);
        let macro_include =
            analyze_include_graph_for_relink("#define CK_NET <WiFi.h>\n#include CK_NET\n");
        assert!(!macro_include.synthesis_safe);
        let continued = analyze_include_graph_for_relink(
            "#define CK_FEATURE(x) \\\n+              x\n#include <Arduino.h>\n",
        );
        assert!(!continued.synthesis_safe);
        let commented = analyze_include_graph_for_relink(
            "/*\n#include <MustNotBeLinked.h>\n*/\n#include <Arduino.h>\n",
        );
        assert!(!commented.synthesis_safe);
        let raw_string = analyze_include_graph_for_relink(
            "const char *text = R\"tag(\n#include <MustNotBeLinked.h>\n)tag\";\n",
        );
        assert!(!raw_string.synthesis_safe);
        let continued_comment = analyze_include_graph_for_relink(
            "// this comment continues \\\n+#include <MustNotBeLinked.h>\n#include <Arduino.h>\n",
        );
        assert!(!continued_comment.synthesis_safe);
        let digraph_include = analyze_include_graph_for_relink("%:include <DigraphDependency.h>\n");
        assert!(!digraph_include.synthesis_safe);
        assert!(
            digraph_include.headers.contains("digraphdependency.h"),
            "the digraph include must be recorded even though synthesis fails closed"
        );
    }

    #[test]
    fn strong_content_stamp_detects_same_length_replacement() {
        let temp = tempfile::tempdir().expect("tempdir");
        let file = temp.path().join("core.a");
        std::fs::write(&file, b"AAAA").expect("first content");
        let before = content_path_stamp(&file).expect("first stamp");
        std::fs::write(&file, b"BBBB").expect("replacement content");
        let after = content_path_stamp(&file).expect("replacement stamp");
        assert_eq!(before.kind, after.kind);
        assert_eq!(before.len, after.len);
        assert_ne!(before.content_fingerprint, after.content_fingerprint);
    }

