    #[test]
    fn ck_mapping_marker_id_drift_does_not_change_dependency_graph_or_request_full_clear() {
        let marked_source = |boundary_id: &str| {
            let begin_payload = serde_json::json!({
                "boundaryId": boundary_id,
                "blockId": "block-with-stable-identity",
                "blockType": "set_pin_mode",
                "section": "definition",
                "confidence": "high",
            });
            let begin = format!(
                "/* @ck-source-begin:v1:{} */",
                hex::encode(serde_json::to_string(&begin_payload).expect("begin JSON"))
            );
            let end = format!(
                "/* @ck-source-end:v1:{} */",
                hex::encode(boundary_id.as_bytes())
            );
            let legacy = format!(
                "/* @ck:v1:{} */",
                hex::encode("block-with-stable-identity".as_bytes())
            );
            format!(
                "#include <Arduino.h> {begin} {end}\nvoid setup() {{}} {legacy}\nvoid loop() {{}}\n"
            )
        };

        let before = analyze_include_graph_for_relink(&marked_source("d1"));
        let after = analyze_include_graph_for_relink(&marked_source("d9"));
        assert_eq!(before.headers, after.headers);
        assert_eq!(before.headers.len(), 1);
        assert!(before.headers.contains("arduino.h"));
        assert_eq!(
            before.preprocessor_fingerprint, after.preprocessor_fingerprint,
            "source-map sequence IDs are diagnostic metadata, not dependency input"
        );
        assert!(before.synthesis_safe);
        assert!(after.synthesis_safe);

        let added = !after
            .headers
            .difference(&before.headers)
            .collect::<Vec<_>>()
            .is_empty();
        let removed = !before
            .headers
            .difference(&after.headers)
            .collect::<Vec<_>>()
            .is_empty();
        let preprocessor_changed =
            before.preprocessor_fingerprint != after.preprocessor_fingerprint;
        let dependency_inputs_changed = false;
        let trusted_fresh_core_header_seed = false;
        let dependency_graph_changed =
            (dependency_headers_require_clean_ccdb_refresh(added, removed)
                || preprocessor_changed
                || dependency_inputs_changed)
                && !trusted_fresh_core_header_seed;
        assert!(
            !dependency_graph_changed,
            "mapping-marker drift alone must not select the authoritative full-clear branch"
        );
    }

    #[test]
    fn mstimer2_conditional_scaffold_ignores_marker_id_drift_but_remains_platform_resolved() {
        let marked_source = |boundary_id: &str| {
            let begin_payload = serde_json::json!({
                "boundaryId": boundary_id,
                "blockId": "timer-block",
                "blockType": "control_mstimer2_every",
                "section": "definition",
                "confidence": "high",
            });
            let begin = format!(
                "/* @ck-source-begin:v1:{} */",
                hex::encode(serde_json::to_string(&begin_payload).expect("begin JSON"))
            );
            let end = format!(
                "/* @ck-source-end:v1:{} */",
                hex::encode(boundary_id.as_bytes())
            );
            format!(
                "#if defined(ARDUINO_ARCH_AVR) {begin}\n#include <MsTimer2.h>\n#define CK_MSTIMER2_RUN() ((void)0)\n#else\n#define CK_MSTIMER2_RUN() ck_ms_timer2.run()\n#endif {end}\nvoid setup() {{}}\n"
            )
        };

        let before = analyze_include_graph_for_relink(&marked_source("d4"));
        let after = analyze_include_graph_for_relink(&marked_source("d8"));
        assert_eq!(before.headers, after.headers);
        assert_eq!(before.headers.len(), 1);
        assert!(before.headers.contains("mstimer2.h"));
        assert_eq!(
            before.preprocessor_fingerprint, after.preprocessor_fingerprint,
            "mapping IDs attached to conditional directives must not look like a real graph change"
        );
        assert!(
            !before.synthesis_safe && !after.synthesis_safe,
            "the real conditional remains platform-resolved after mapping markers are removed"
        );
    }

    #[test]
    fn ordinary_and_malformed_marker_comments_remain_fail_closed() {
        let ordinary_before = analyze_include_graph_for_relink(
            "#include <Arduino.h> /* user dependency note A */\nvoid setup() {}\n",
        );
        let ordinary_after = analyze_include_graph_for_relink(
            "#include <Arduino.h> /* user dependency note B */\nvoid setup() {}\n",
        );
        assert!(!ordinary_before.synthesis_safe);
        assert!(!ordinary_after.synthesis_safe);
        assert_ne!(
            ordinary_before.preprocessor_fingerprint, ordinary_after.preprocessor_fingerprint,
            "ordinary comments on directives must remain visible to conservative analysis"
        );

        let malformed = analyze_include_graph_for_relink(
            "#include <Arduino.h> /* @ck-source-end:v1:not-hex */\nvoid setup() {}\n",
        );
        assert!(
            !malformed.synthesis_safe,
            "marker-looking user text without a valid encoded payload must not be trusted"
        );
    }

