    #[test]
    fn synthetic_relink_rejects_archive_precompiled_and_custom_link_libraries() {
        let temp = tempfile::tempdir().expect("tempdir");
        let safe = temp.path().join("Safe");
        let archive = temp.path().join("Archive");
        let precompiled = temp.path().join("Precompiled");
        let linked = temp.path().join("Linked");
        for library in [&safe, &archive, &precompiled, &linked] {
            std::fs::create_dir_all(library).expect("library directory");
        }
        std::fs::write(
            safe.join("library.properties"),
            "name=Safe\ndot_a_linkage=false\n",
        )
        .expect("safe properties");
        std::fs::write(
            archive.join("library.properties"),
            "name=Archive\ndot_a_linkage=true\n",
        )
        .expect("archive properties");
        std::fs::write(
            precompiled.join("library.properties"),
            "name=Precompiled\nprecompiled=full\n",
        )
        .expect("precompiled properties");
        std::fs::write(
            linked.join("library.properties"),
            "name=Linked\nldflags=-lcustom\n",
        )
        .expect("linked properties");

        assert!(unsupported_synthetic_library_semantics(&[safe]).is_empty());
        let rejected = unsupported_synthetic_library_semantics(&[archive, precompiled, linked]);
        assert_eq!(rejected.len(), 3);
        assert!(
            rejected
                .iter()
                .any(|reason| reason.contains("dot_a_linkage=true"))
        );
        assert!(
            rejected
                .iter()
                .any(|reason| reason.contains("precompiled=full"))
        );
        assert!(
            rejected
                .iter()
                .any(|reason| reason.contains("ldflags=-lcustom"))
        );
    }

