    struct CompileControlCacheGuard {
        sysroot: crate::sysroot::Sysroot,
        fqbn: String,
    }

    impl CompileControlCacheGuard {
        fn new(sysroot: &crate::sysroot::Sysroot, fqbn: &str) -> Self {
            Self {
                sysroot: sysroot.clone(),
                fqbn: fqbn.to_string(),
            }
        }
    }

    impl Drop for CompileControlCacheGuard {
        fn drop(&mut self) {
            let _ = super::clear_board_compile_cache_paths(&self.sysroot, &self.fqbn, false);
            for marker in super::force_rebuild_marker_paths(&self.fqbn) {
                let _ = std::fs::remove_file(marker);
            }
        }
    }

    fn blocked_runtime_tools_override(
        calls: std::sync::Arc<std::sync::atomic::AtomicUsize>,
    ) -> super::TestRuntimeToolsPreflightOverride {
        super::TestRuntimeToolsPreflightOverride {
            calls,
            report: crate::builder::direct_engine::RuntimeToolPreflightReport {
                board_hidden: false,
                unresolved_runtime_tool_paths: vec!["runtime.tools.compiler.path".into()],
                missing_critical_paths: vec![PathBuf::from("missing-compiler")],
            },
        }
    }

    #[tokio::test]
    async fn real_force_rebuild_control_flow_blocks_before_cache_deletion_or_compile_boundary() {
        use std::sync::atomic::{AtomicUsize, Ordering};

        let temp = tempfile::tempdir().expect("tempdir");
        let sysroot = crate::sysroot::Sysroot::init(
            Some(temp.path().join("sysroot")),
            "ck-exact-preflight-force-test",
        )
        .await
        .expect("sysroot");
        install_executable_cli_fixture(&sysroot.root_dir);
        let fqbn = unique_test_board();
        let _cleanup = CompileControlCacheGuard::new(&sysroot, &fqbn);
        let profile = CompileProfile::QuickFast;
        let cache_dir = std::env::temp_dir().join("CK_Builds");
        let build_path = short_build_cache_path(&cache_dir, &fqbn, profile);
        std::fs::create_dir_all(&build_path).expect("build cache");
        let build_sentinel = build_path.join("last-known-cache.sentinel");
        std::fs::write(&build_sentinel, b"preserve me").expect("build sentinel");
        let fqbn_safe = sanitize_fqbn_for_path(&fqbn);
        let metadata_dir = cache_dir.join("metadata");
        std::fs::create_dir_all(&metadata_dir).expect("metadata directory");
        let meta_path = metadata_dir.join(format!(
            "meta_{}_{}.json",
            fqbn_safe,
            build_mode_suffix(profile)
        ));
        std::fs::write(&meta_path, b"last-known-meta").expect("metadata sentinel");
        let force_marker = force_rebuild_marker_path(&fqbn);
        if let Some(parent) = force_marker.parent() {
            std::fs::create_dir_all(parent).expect("force marker parent");
        }
        std::fs::write(&force_marker, b"force-rebuild-v1").expect("force marker");

        let preflight_calls = std::sync::Arc::new(AtomicUsize::new(0));
        let compile_boundaries = std::sync::Arc::new(AtomicUsize::new(0));
        let result = super::TEST_RUNTIME_TOOLS_PREFLIGHT_OVERRIDE
            .scope(
                blocked_runtime_tools_override(std::sync::Arc::clone(&preflight_calls)),
                super::TEST_COMPILE_EXECUTION_BOUNDARY_COUNT.scope(
                    std::sync::Arc::clone(&compile_boundaries),
                    super::compile_sketch_string_with_policy(
                        &sysroot,
                        "void setup() {}\nvoid loop() {}\n",
                        &fqbn,
                        &[],
                        1,
                        "force-build-signature",
                        None,
                        profile,
                        CkExactReusePolicy::Allow,
                        DependencyResolutionPolicy::Managed,
                        None,
                        |_percentage, _message| {},
                        |_line| {},
                    ),
                ),
            )
            .await;

        let error = result.expect_err("missing runtime tools must block the forced rebuild");
        assert!(error.to_string().contains("missing-compiler"));
        assert_eq!(preflight_calls.load(Ordering::SeqCst), 1);
        assert_eq!(compile_boundaries.load(Ordering::SeqCst), 0);
        assert_eq!(
            std::fs::read(&build_sentinel).expect("preserved build sentinel"),
            b"preserve me"
        );
        assert_eq!(
            std::fs::read(&meta_path).expect("preserved metadata sentinel"),
            b"last-known-meta"
        );
        assert!(
            force_marker.is_file(),
            "the rebuild request remains pending"
        );
    }

    #[tokio::test]
    async fn real_authenticated_exact_control_flow_skips_preflight_and_compile_boundary() {
        use std::sync::atomic::{AtomicUsize, Ordering};

        // This end-to-end path holds a real ToolchainIdentityLease.  Serialize
        // it with the tests that deliberately advance the process-wide Core
        // identity generation; otherwise a parallel invalidation can make the
        // authenticated fixture look stale for reasons unrelated to Exact.
        let _identity_scope = process_identity_test_scope();
        let temp = tempfile::tempdir().expect("tempdir");
        let sysroot = crate::sysroot::Sysroot::init(
            Some(temp.path().join("sysroot")),
            "ck-exact-preflight-hit-test",
        )
        .await
        .expect("sysroot");
        install_executable_cli_fixture(&sysroot.root_dir);
        let fqbn = unique_test_board();
        let _cleanup = CompileControlCacheGuard::new(&sysroot, &fqbn);
        let profile = CompileProfile::QuickFast;
        let code = "void setup() {}\nvoid loop() {}\n";
        let build_signature = "authenticated-exact-build-signature";
        let cache_dir = std::env::temp_dir().join("CK_Builds");
        let fqbn_safe = sanitize_fqbn_for_path(&fqbn);
        let mode_suffix = build_mode_suffix(profile);
        let project_dir = cache_dir.join(format!("sketch_{}_{}", fqbn_safe, mode_suffix));
        let artifact_project_name = project_dir
            .file_name()
            .and_then(|name| name.to_str())
            .expect("artifact project name")
            .to_string();
        let build_path = short_build_cache_path(&cache_dir, &fqbn, profile);
        let metadata_dir = cache_dir.join("metadata");
        std::fs::create_dir_all(build_path.join("core")).expect("core directory");
        std::fs::create_dir_all(&project_dir).expect("project directory");
        std::fs::create_dir_all(&metadata_dir).expect("metadata directory");
        std::fs::write(
            build_path.join("core/core.a"),
            b"authenticated core archive",
        )
        .expect("core archive");
        write_core_cache_identity(
            &build_path,
            &expected_core_cache_identity(&sysroot, &fqbn, profile),
        )
        .expect("core identity");

        let sketch_build_dir = build_path.join("build/sketch");
        std::fs::create_dir_all(&sketch_build_dir).expect("sketch build directory");
        let source = sketch_build_dir.join(format!("{artifact_project_name}.ino.cpp"));
        let object = sketch_build_dir.join(format!("{artifact_project_name}.ino.cpp.o"));
        std::fs::write(&source, code).expect("translated sketch source");
        std::fs::write(&object, b"object").expect("sketch object");
        std::fs::write(
            object.with_extension("d"),
            format!("{}: {}\n", object.display(), source.display()),
        )
        .expect("dependency file");
        let ccdb = vec![CompileCommandEntry {
            directory: sysroot.root_dir.to_string_lossy().into_owned(),
            arguments: vec![
                "g++".into(),
                "-c".into(),
                source.to_string_lossy().into_owned(),
                "-o".into(),
                object.to_string_lossy().into_owned(),
            ],
            command: String::new(),
            file: source.to_string_lossy().into_owned(),
            output: Some(object.to_string_lossy().into_owned()),
        }];
        std::fs::write(
            build_path.join("compile_commands.json"),
            serde_json::to_vec(&ccdb).expect("ccdb json"),
        )
        .expect("ccdb");
        let dependency_content_signature =
            build_dependency_content_signature(&build_path, &sysroot.root_dir)
                .expect("dependency signature");
        let primary_artifact = build_path.join(format!("{artifact_project_name}.ino.elf"));
        std::fs::write(&primary_artifact, b"authenticated firmware").expect("firmware artifact");
        let artifact_manifest =
            collect_build_artifact_manifest(&build_path, &artifact_project_name)
                .expect("artifact manifest");
        let meta_path = metadata_dir.join(format!("meta_{}_{}.json", fqbn_safe, mode_suffix));
        let backup_path = metadata_dir.join(format!("backup_{}_{}.ino", fqbn_safe, mode_suffix));
        std::fs::write(&backup_path, code).expect("source backup");
        let meta = BuildMeta {
            schema_version: BUILD_META_SCHEMA_VERSION,
            fqbn: fqbn.clone(),
            success: true,
            build_signature: build_signature.to_string(),
            summary_lines: Vec::new(),
            warning_count: Some(0),
            workspace_fingerprint: None,
            library_tree_signature: extra_libs_tree_signature(&[]),
            dependency_content_signature: Some(dependency_content_signature),
            artifact_manifest: Some(artifact_manifest),
            esp32_library_relink_manifest_sha256: None,
        };
        std::fs::write(
            &meta_path,
            serde_json::to_vec(&meta).expect("build meta json"),
        )
        .expect("build meta");

        let preflight_calls = std::sync::Arc::new(AtomicUsize::new(0));
        let compile_boundaries = std::sync::Arc::new(AtomicUsize::new(0));
        let result = super::TEST_RUNTIME_TOOLS_PREFLIGHT_OVERRIDE
            .scope(
                blocked_runtime_tools_override(std::sync::Arc::clone(&preflight_calls)),
                super::TEST_COMPILE_EXECUTION_BOUNDARY_COUNT.scope(
                    std::sync::Arc::clone(&compile_boundaries),
                    super::compile_sketch_string_with_policy(
                        &sysroot,
                        code,
                        &fqbn,
                        &[],
                        1,
                        build_signature,
                        None,
                        profile,
                        CkExactReusePolicy::Allow,
                        DependencyResolutionPolicy::Managed,
                        None,
                        |_percentage, _message| {},
                        |_line| {},
                    ),
                ),
            )
            .await
            .expect("authenticated Exact must return the existing artifact set");

        assert_eq!(result.0, build_path);
        assert!(result.1.contains("Cached build (Exact Match)"));
        assert_eq!(preflight_calls.load(Ordering::SeqCst), 0);
        assert_eq!(compile_boundaries.load(Ordering::SeqCst), 0);
        assert!(primary_artifact.is_file());
        assert!(meta_path.is_file());

        // Turn the same authenticated fixture into an ordinary Exact miss.
        // Artifact invalidation used to delete the whole build directory before
        // discovering that the active Core compiler was missing.
        std::fs::write(&primary_artifact, b"tampered firmware").expect("tampered artifact");
        let miss = super::TEST_RUNTIME_TOOLS_PREFLIGHT_OVERRIDE
            .scope(
                blocked_runtime_tools_override(std::sync::Arc::clone(&preflight_calls)),
                super::TEST_COMPILE_EXECUTION_BOUNDARY_COUNT.scope(
                    std::sync::Arc::clone(&compile_boundaries),
                    super::compile_sketch_string_with_policy(
                        &sysroot,
                        code,
                        &fqbn,
                        &[],
                        1,
                        build_signature,
                        None,
                        profile,
                        CkExactReusePolicy::Allow,
                        DependencyResolutionPolicy::Managed,
                        None,
                        |_percentage, _message| {},
                        |_line| {},
                    ),
                ),
            )
            .await
            .expect_err("tampered Exact artifact must enter the blocked compile route");
        assert!(miss.to_string().contains("missing-compiler"));
        assert_eq!(preflight_calls.load(Ordering::SeqCst), 1);
        assert_eq!(compile_boundaries.load(Ordering::SeqCst), 0);
        assert_eq!(
            std::fs::read(&primary_artifact).expect("preserved invalid artifact sentinel"),
            b"tampered firmware"
        );
        assert!(meta_path.is_file(), "BuildMeta remains until tools pass");
    }

    #[test]
    fn fast_relink_size_summary_never_invents_zero_usage_without_regex_matches() {
        let props = HashMap::from([
            (
                "recipe.size.regex".to_string(),
                r"^PROGRAM:([0-9]+)$".to_string(),
            ),
            (
                "recipe.size.regex.data".to_string(),
                r"^DATA:([0-9]+)$".to_string(),
            ),
            ("upload.maximum_size".to_string(), "3145728".to_string()),
            ("upload.maximum_data_size".to_string(), "327680".to_string()),
        ]);

        assert!(parse_size_summary_lines(&props, "unrelated tool output").is_empty());
        assert_eq!(
            parse_size_summary_lines(&props, "PROGRAM:930688\n"),
            vec![
                "Sketch uses 930688 bytes (30%) of program storage space. Maximum is 3145728 bytes."
                    .to_string()
            ]
        );
        assert_eq!(
            parse_size_summary_lines(&props, "PROGRAM:930688\nDATA:39964\n").len(),
            2
        );

        let no_capacity_props = HashMap::from([
            (
                "recipe.size.regex".to_string(),
                r"^PROGRAM:([0-9]+)$".to_string(),
            ),
            (
                "recipe.size.regex.data".to_string(),
                r"^DATA:([0-9]+)$".to_string(),
            ),
        ]);
        assert_eq!(
            parse_size_summary_lines(&no_capacity_props, "PROGRAM:930688\nDATA:39964\n"),
            vec![
                "Sketch uses 930688 bytes of program storage space.".to_string(),
                "Global variables use 39964 bytes of dynamic memory.".to_string(),
            ],
            "measured usage remains evidence when a Core does not expose a trustworthy maximum"
        );
    }

    #[test]
    fn combining_upload_attempts_keeps_one_marker_and_the_final_outcome() {
        let mut first = BoundedLog::new(512, 96);
        first.push_line("[CK] Upload transport: arduino-cli");
        first.push_str(&"first attempt output\n".repeat(2_000));
        first.push_line("write timeout while changing baud rate to 921600");
        let mut retry = BoundedLog::new(512, 96);
        retry.push_line("[CK] Upload transport: arduino-cli-retry");
        retry.push_str(&"retry output\n".repeat(2_000));
        retry.push_line("[INFO] Upload process exited successfully");

        let combined = combine_bounded_upload_logs(&[&first.rendered(), &retry.rendered()]);
        assert!(combined.len() <= super::UPLOAD_FULL_LOG_MAX_BYTES);
        assert_eq!(combined.matches(BOUNDED_LOG_TRUNCATION_MARKER).count(), 1);
        assert!(combined.contains("[CK] Upload transport: arduino-cli"));
        assert!(combined.ends_with("[INFO] Upload process exited successfully\n"));
    }

    fn relative_fixture_paths(root: &Path, paths: &[PathBuf]) -> Vec<String> {
        paths
            .iter()
            .map(|path| {
                path.strip_prefix(root)
                    .expect("source remains inside fixture")
                    .to_string_lossy()
                    .replace('\\', "/")
            })
            .collect()
    }

    #[test]
    fn ccdb_lock_registry_reuses_active_locks_without_retaining_build_history() {
        let mut locks = HashMap::new();
        let anchor = reusable_async_mutex_for_key(&mut locks, "anchor".to_string());
        let same_anchor = reusable_async_mutex_for_key(&mut locks, "anchor".to_string());
        assert!(
            std::sync::Arc::ptr_eq(&anchor, &same_anchor),
            "parallel refreshes for one build path must share the same mutex"
        );
        drop(same_anchor);

        for index in 0..1_000 {
            let temporary = reusable_async_mutex_for_key(&mut locks, format!("build-{index}"));
            drop(temporary);
        }

        let anchor_again = reusable_async_mutex_for_key(&mut locks, "anchor".to_string());
        assert!(std::sync::Arc::ptr_eq(&anchor, &anchor_again));
        assert!(
            locks.len() <= 2,
            "only active locks and at most the newest stale weak entry may remain"
        );
    }

    #[test]
    fn avr_noncompiler_recipes_keep_the_real_toolchain_path() {
        let platform = r#"
compiler.path={runtime.tools.avr-gcc.path}/bin/
recipe.ar.pattern="{compiler.path}{compiler.ar.cmd}" rcs "{archive_file_path}" "{object_file}"
recipe.objcopy.hex.pattern="{compiler.path}{compiler.elf2hex.cmd}" -O ihex "{build.path}/app.elf" "{build.path}/app.hex"
recipe.objcopy.vendor-image.pattern.windows="{compiler.path}vendor-objcopy" "{build.path}/app.elf"
recipe.objcopy.bin.pattern_args=--chip example
recipe.size.pattern="{compiler.path}{compiler.size.cmd}" -A "{build.path}/app.elf"
debug.cortex-debug.custom.objdumpPath={compiler.path}{compiler.prefix}objdump
"#;

        for key in [
            "recipe.ar.pattern",
            "recipe.objcopy.hex.pattern",
            "recipe.size.pattern",
            "debug.cortex-debug.custom.objdumpPath",
        ] {
            let rewritten = derive_nocache_recipe(platform, key).expect("nocache recipe");
            assert!(rewritten.contains("{compiler.path.nocache}"));
            assert!(!rewritten.contains("{compiler.path}"));
        }

        let overrides = derive_nocache_tool_recipe_overrides(platform)
            .into_iter()
            .collect::<BTreeMap<_, _>>();
        assert_eq!(overrides.len(), 5);
        assert!(overrides.contains_key("recipe.objcopy.vendor-image.pattern.windows"));
        assert!(!overrides.contains_key("recipe.objcopy.bin.pattern_args"));
        assert!(
            overrides
                .values()
                .all(|recipe| recipe.contains("{compiler.path.nocache}"))
        );
    }

    #[test]
    fn final_fast_flags_are_derived_after_core_response_files_without_rewriting_recipes() {
        let platform = r#"
compiler.c.flags=-MMD -c "@{compiler.sdk.path}/flags/c_flags" {compiler.optimization_flags}
compiler.c.flags.windows=-MMD -c "@{compiler.sdk.path}/flags/c_flags.windows" {compiler.optimization_flags}
compiler.cpp.flags=-MMD -c "@{compiler.sdk.path}/flags/cpp_flags" {compiler.optimization_flags}
compiler.S.flags=-MMD -c "@{compiler.sdk.path}/flags/S_flags"
recipe.vendor.o.pattern="{compiler.path}vendor" --input={source_file} --output={object_file}
"#;
        let overrides = derive_final_compile_flag_overrides(platform)
            .into_iter()
            .collect::<BTreeMap<_, _>>();
        assert_eq!(overrides.len(), 3);
        for key in [
            "compiler.c.flags",
            "compiler.c.flags.windows",
            "compiler.cpp.flags",
        ] {
            let flags = overrides
                .get(key)
                .expect("standard compiler flags override");
            let response_index = flags
                .find("@{compiler.sdk.path}")
                .expect("SDK response file");
            let final_index = flags
                .find("{compiler.ck.final_flags}")
                .expect("final fast-profile property");
            assert!(response_index < final_index);
        }
        assert!(!overrides.contains_key("compiler.S.flags"));
        assert!(platform.contains("recipe.vendor.o.pattern"));
    }

    #[test]
    fn legacy_ck_platform_override_migration_is_exact_and_preserves_user_content() {
        let temp = tempfile::tempdir().expect("tempdir");
        let root = temp.path();
        let ccache_name = if cfg!(target_os = "windows") {
            "ccache.exe"
        } else {
            "ccache"
        };
        let compiler_name = if cfg!(target_os = "windows") {
            "riscv32-esp-elf-g++.exe"
        } else {
            "riscv32-esp-elf-g++"
        };
        let bundled_ccache = root.join("tools").join(ccache_name);
        let compiler = root
            .join("packages/acme/tools/demo-gcc/1.0.0/bin")
            .join(compiler_name);
        let platform = root.join("packages/acme/hardware/demo/1.0.0");
        for parent in [
            bundled_ccache.parent().unwrap(),
            compiler.parent().unwrap(),
            platform.as_path(),
        ] {
            std::fs::create_dir_all(parent).expect("fixture directory");
        }
        std::fs::write(&bundled_ccache, b"fixture-ccache").expect("ccache fixture");
        std::fs::write(&compiler, b"fixture-compiler").expect("compiler fixture");
        let platform_txt = platform.join("platform.txt");
        std::fs::write(
            &platform_txt,
            "compiler.path={runtime.tools.demo-gcc.path}/bin/\n\
             compiler.cpp.cmd=riscv32-esp-elf-g++\n\
             compiler.cpp.flags=-c -Os\n\
             recipe.cpp.o.pattern=\"{compiler.path}{compiler.cpp.cmd}\" {compiler.cpp.flags} \"{source_file}\" -o \"{object_file}\"\n\
             recipe.ar.pattern=\"{compiler.path}riscv32-esp-elf-ar\" rcs \"{archive_file_path}\" \"{object_file}\"\n",
        )
        .expect("platform fixture");

        let generated = legacy_ck_platform_local_payload(root, &platform_txt)
            .expect("fixture should enable command adapter");
        let fast_properties =
            command_scoped_build_properties(root, "acme:demo:board", CompileProfile::QuickFast)
                .into_iter()
                .collect::<BTreeMap<_, _>>();
        assert!(
            fast_properties
                .get("compiler.path")
                .is_some_and(|value| value.ends_with("/bin/ccache/"))
        );
        let quick_env = build_ccache_env_map(
            root,
            "acme:demo:board:Flash=16M,Mode=fast",
            CompileProfile::QuickFast,
        );
        let reordered_namespace = fast_profile_ccache_namespace_for_target(
            root,
            "acme:demo:board:Mode=fast,Flash=16M",
            CompileProfile::QuickFast,
        );
        let authenticated_key =
            toolchain_cache_key_from_root(root, "acme:demo:board:Flash=16M,Mode=fast");
        let authenticated_namespace = fast_profile_ccache_namespace_for_toolchain_key(
            &authenticated_key,
            "acme:demo:board:Flash=16M,Mode=fast",
            CompileProfile::QuickFast,
        );
        assert_eq!(
            quick_env.get("CCACHE_NAMESPACE").map(String::as_str),
            Some(authenticated_namespace.as_str()),
            "a request lease must produce the same namespace as the standalone guarded resolver"
        );
        assert_eq!(
            quick_env.get("CCACHE_NAMESPACE"),
            Some(&reordered_namespace),
            "equivalent option order must share one complete-target namespace"
        );
        assert_eq!(
            quick_env.get("CCACHE_HARDLINK").map(String::as_str),
            Some("true")
        );
        assert!(
            !quick_env.contains_key("CCACHE_BASEDIR"),
            "fast ccache must preserve source paths used by __FILE__"
        );
        assert!(
            !quick_env
                .get("CCACHE_SLOPPINESS")
                .expect("quick ccache sloppiness")
                .contains("system_headers")
        );
        let portable_env = build_ccache_env_map(
            root,
            "acme:demo:board:Flash=16M,Mode=fast",
            CompileProfile::PortableFast,
        );
        assert_ne!(
            quick_env.get("CCACHE_NAMESPACE"),
            portable_env.get("CCACHE_NAMESPACE"),
            "profile contracts must not share ccache objects"
        );
        assert_eq!(
            portable_env.get("CCACHE_NOHARDLINK").map(String::as_str),
            Some("true")
        );
        assert!(
            build_ccache_env_map(
                root,
                "acme:demo:board:Flash=16M,Mode=fast",
                CompileProfile::Release,
            )
            .is_empty()
        );
        assert!(
            command_scoped_build_properties(root, "acme:demo:board", CompileProfile::Release,)
                .is_empty()
        );
        let portable_properties =
            command_scoped_build_properties(root, "acme:demo:board", CompileProfile::PortableFast)
                .into_iter()
                .collect::<BTreeMap<_, _>>();
        assert!(
            portable_properties
                .get("compiler.path")
                .is_some_and(|value| value.ends_with("/bin/ccache/")),
            "PortableFast must use a command-scoped ccache compiler shim"
        );
        assert!(
            portable_properties
                .values()
                .filter(|value| value.contains("{compiler.path.nocache}"))
                .count()
                >= 1,
            "non-compiler recipes must retain the Core's native tool"
        );
        let local = platform.join("platform.local.txt");
        std::fs::write(&local, &generated).expect("legacy generated file");
        assert_eq!(remove_legacy_ck_platform_local_overrides(root), 1);
        assert!(!local.exists());

        let user_content = "compiler.warning_flags=-Wall\n# user-owned override\n";
        std::fs::write(&local, user_content).expect("user override");
        assert_eq!(remove_legacy_ck_platform_local_overrides(root), 0);
        assert_eq!(
            std::fs::read_to_string(&local).expect("preserved user override"),
            user_content
        );
    }

    #[test]
    fn portable_prebuild_guard_is_stable_and_runs_after_board_scoped_native_hooks() {
        let temp = tempfile::tempdir().expect("temporary sysroot");
        let root = temp.path();
        let platform = root.join("packages/acme/hardware/demo/1.0.0");
        std::fs::create_dir_all(&platform).expect("platform fixture");
        std::fs::write(
            platform.join("platform.txt"),
            "recipe.hooks.prebuild.3.pattern=native-three\n",
        )
        .expect("platform hooks");
        std::fs::write(
            platform.join("platform.local.txt"),
            "recipe.hooks.prebuild.41.pattern=native-local\n",
        )
        .expect("local hooks");
        std::fs::write(
            platform.join("boards.txt"),
            "board.recipe.hooks.prebuild.9001.pattern=native-board\n\
             other.menu.Mode.x.recipe.hooks.prebuild.125.pattern=native-menu\n",
        )
        .expect("board hooks");
        let helper = root.join("CK helper with spaces.exe");
        std::fs::write(&helper, b"fixture").expect("helper fixture");

        assert_eq!(
            max_prebuild_hook_index_in_text(
                "board.recipe.hooks.prebuild.12.pattern=x\nrecipe.hooks.prebuild.8.pattern=y\n"
            ),
            Some(12)
        );
        assert_eq!(
            portable_prebuild_guard_hook_index(root, "acme:demo:board"),
            Some(9002)
        );
        let first = portable_prebuild_restore_hook_property(root, "acme:demo:board", &helper)
            .expect("guard property");
        let subsequent = portable_prebuild_restore_hook_property(root, "acme:demo:board", &helper)
            .expect("stable guard property");
        assert_eq!(first, subsequent);
        assert_eq!(first.0, "recipe.hooks.prebuild.9002.pattern");
        assert!(first.1.contains("CK helper with spaces.exe"));
        assert!(first.1.contains("--ck-prebuild-restore"));
        assert!(first.1.contains("{build.path}"));
        assert_eq!(build_mode_suffix(CompileProfile::PortableFast), "pfast3");
        assert!(portable_prebuild_restore_helper_startup_failed(
            "--ck-prebuild-restore .ck-prebuild-restore-v1.json: The system cannot find the file specified"
        ));
        assert!(!portable_prebuild_restore_helper_startup_failed(
            "unrelated native compiler error: no such file or directory"
        ));
    }

    #[test]
    fn controlled_portable_recipe_probe_is_compile_only_and_not_direct_link() {
        use super::recipe_capability::RecipeCapabilityCandidateIntent;

        assert_eq!(
            super::recipe_capability_candidate_intent_for_probe(
                CompileProfile::PortableFast,
                CompileIntent::CompileOnly,
            )
            .expect("PortableFast compile-only observation"),
            RecipeCapabilityCandidateIntent::NativeRecipeCache
        );
        assert_eq!(
            super::recipe_capability_candidate_intent_for_probe(
                CompileProfile::QuickFast,
                CompileIntent::CompileOnly,
            )
            .expect("QuickFast compile-only observation"),
            RecipeCapabilityCandidateIntent::Compile
        );
        assert_eq!(
            super::recipe_capability_candidate_intent_for_probe(
                CompileProfile::SharedFast,
                CompileIntent::UploadReady,
            )
            .expect("SharedFast upload-ready observation"),
            RecipeCapabilityCandidateIntent::UploadReady
        );
        assert!(
            super::recipe_capability_candidate_intent_for_probe(
                CompileProfile::PortableFast,
                CompileIntent::UploadReady,
            )
            .is_err(),
            "PortableFast observation cannot imply upload/direct-link evidence"
        );
        assert!(
            super::recipe_capability_candidate_intent_for_probe(
                CompileProfile::Release,
                CompileIntent::CompileOnly,
            )
            .is_err(),
            "ordinary Release builds never become qualification probes"
        );
    }

    #[cfg(target_os = "windows")]
    #[tokio::test]
    async fn windows_shell_executor_preserves_platform_hook_redirection() {
        let temp = tempfile::tempdir().expect("temporary hook root");
        let build = temp.path().join("build path").join("nested");
        std::fs::create_dir_all(&build).expect("hook build directory");
        let mixed_path = format!(r"{}\build_opt.h", compiler_safe_path(&build));
        let hook = format!(r#"cmd /c if not exist "{mixed_path}" type nul > "{mixed_path}""#);

        let output = super::run_shell_line(&hook, Some(temp.path()))
            .await
            .expect("run Windows platform hook");
        assert!(
            output.status.success(),
            "hook failed: {}",
            String::from_utf8_lossy(&output.stderr)
        );
        let target = build.join("build_opt.h");
        assert!(target.is_file());

        std::fs::write(&target, b"ck-hook-sentinel").expect("write hook sentinel");
        let repeated = super::run_shell_line(&hook, Some(temp.path()))
            .await
            .expect("repeat Windows platform hook");
        assert!(
            repeated.status.success(),
            "repeated hook failed: {}",
            String::from_utf8_lossy(&repeated.stderr)
        );
        assert_eq!(
            std::fs::read(&target).expect("read preserved hook target"),
            b"ck-hook-sentinel",
            "idempotent hook truncated an existing target"
        );

        let direct_target = build.join("direct_opt.h");
        let direct_mixed_path = format!(r"{}\direct_opt.h", compiler_safe_path(&build));
        let direct_hook =
            format!(r#"if not exist "{direct_mixed_path}" type nul > "{direct_mixed_path}""#);
        let direct = super::run_shell_line(&direct_hook, Some(temp.path()))
            .await
            .expect("run unprefixed Windows platform hook");
        assert!(
            direct.status.success(),
            "unprefixed hook failed: {}",
            String::from_utf8_lossy(&direct.stderr)
        );
        assert!(direct_target.is_file());
    }

    #[test]
    fn arduino_modern_src_discovery_is_recursive_and_does_not_compile_package_extras() {
        let root = unique_library_fixture("modern-recursive");
        for relative in [
            "src/root.c",
            "src/drivers/a/same.c",
            "src/drivers/b/same.cpp",
            "src/vendor/native.S",
            "src/extra.cc",
            "src/deep/extra.cxx",
            "examples/not-a-library-source.c",
            "extras/not-a-library-source.cpp",
        ] {
            let path = root.join(relative);
            std::fs::create_dir_all(path.parent().unwrap()).unwrap();
            std::fs::write(path, "/* fixture */\n").unwrap();
        }

        let discovered = discover_arduino_library_sources(&root);
        assert_eq!(
            relative_fixture_paths(&root, &discovered),
            vec![
                "src/deep/extra.cxx",
                "src/drivers/a/same.c",
                "src/drivers/b/same.cpp",
                "src/extra.cc",
                "src/root.c",
                "src/vendor/native.S",
            ]
        );
        let include_flags = collect_library_include_flags(&root);
        assert_eq!(include_flags.len(), 1);
        assert!(include_flags[0].replace('\\', "/").ends_with("/src"));
        assert!(!include_flags.iter().any(|flag| flag.contains("drivers")));

        let signature_before = extra_libs_tree_signature(std::slice::from_ref(&root));
        std::fs::remove_file(root.join("src/drivers/a/same.c")).unwrap();
        let signature_after = extra_libs_tree_signature(std::slice::from_ref(&root));
        assert_ne!(
            signature_before, signature_after,
            "deleting a deep source must invalidate exact-match builds"
        );

        let _ = std::fs::remove_dir_all(root);
    }

    #[test]
    fn arduino_header_provider_discovery_supports_deep_modern_and_strict_legacy_layouts() {
        let temp = tempfile::tempdir().expect("tempdir");
        let libraries = temp.path().join("libraries");

        let modern = libraries.join("DeepModern");
        let deep_header = modern.join("src/a/b/c/d/e/f/DeepHeader.hxx");
        let direct_header = modern.join("src/DirectHeader.hh");
        for path in [&deep_header, &direct_header] {
            std::fs::create_dir_all(path.parent().expect("header parent"))
                .expect("modern header directory");
            std::fs::write(path, b"#pragma once\n").expect("modern header");
        }

        let deep_include = "a/b/c/d/e/f/DeepHeader.hxx";
        assert_eq!(
            canonical_header_providers(std::slice::from_ref(&modern), deep_include),
            vec![std::fs::canonicalize(&modern).expect("canonical modern library")],
            "a public header deeper than the former four-level scan must remain discoverable"
        );
        assert_eq!(
            canonical_header_providers(std::slice::from_ref(&modern), "DirectHeader.hh").len(),
            1,
            ".hh is a normal Arduino C++ header suffix"
        );

        let legacy = libraries.join("StrictLegacy");
        let legacy_root_header = legacy.join("LegacyRoot.hh");
        let legacy_utility_header = legacy.join("utility/deep/LegacyUtility.hxx");
        let legacy_vendor_header = legacy.join("vendor/MustNotProvide.hxx");
        for path in [
            &legacy_root_header,
            &legacy_utility_header,
            &legacy_vendor_header,
        ] {
            std::fs::create_dir_all(path.parent().expect("legacy header parent"))
                .expect("legacy header directory");
            std::fs::write(path, b"#pragma once\n").expect("legacy header");
        }
        for include in [
            "LegacyRoot.hh",
            "deep/LegacyUtility.hxx",
            "utility/deep/LegacyUtility.hxx",
        ] {
            assert_eq!(
                canonical_header_providers(std::slice::from_ref(&legacy), include).len(),
                1,
                "legacy root and utility include spellings follow Arduino layout rules"
            );
        }
        assert!(
            canonical_header_providers(std::slice::from_ref(&legacy), "vendor/MustNotProvide.hxx")
                .is_empty(),
            "an arbitrary legacy vendor subtree must not become a public provider"
        );

        let duplicate = libraries.join("DuplicateModern");
        let duplicate_header = duplicate.join("src/a/b/c/d/e/f/DeepHeader.hxx");
        std::fs::create_dir_all(duplicate_header.parent().expect("duplicate header parent"))
            .expect("duplicate header directory");
        std::fs::write(&duplicate_header, b"#pragma once\n").expect("duplicate header");
        let ambiguity = unique_synthetic_header_provider(&[], &[libraries], deep_include)
            .expect_err("deep .hxx providers must retain fail-closed ambiguity handling");
        assert!(ambiguity.to_string().contains("ambiguous"));
        assert!(ambiguity.to_string().contains("2 canonical providers"));
    }

    #[test]
    fn graph_transition_preserves_literal_include_and_library_source_order() {
        let temp = tempfile::tempdir().expect("tempdir");
        let platform = temp.path().join("platform");
        let libraries = platform.join("libraries");
        let fixtures = [("Wire", "Wire.h"), ("SPI", "SPI.h"), ("EEPROM", "EEPROM.h")];
        for (name, header) in fixtures {
            let root = libraries.join(name);
            std::fs::create_dir_all(root.join("src")).expect("library src");
            std::fs::write(root.join("src").join(header), b"#pragma once\n")
                .expect("public header");
            std::fs::write(
                root.join("library.properties"),
                format!("name={name}\nversion=1.0.0\n"),
            )
            .expect("library properties");
        }
        let wire = libraries.join("Wire");
        std::fs::create_dir_all(wire.join("src/utility")).expect("Wire utility");
        std::fs::write(wire.join("src/Wire.cpp"), b"int wire_cpp;\n").expect("Wire.cpp");
        std::fs::write(wire.join("src/utility/twi.c"), b"int twi_c;\n").expect("twi.c");

        let source = "#include <Wire.h>\n#include <SPI.h>\n#include <EEPROM.h>\n";
        let analysis = analyze_include_graph_for_relink(source);
        assert_eq!(
            literal_include_headers_in_source_order(source),
            vec!["wire.h", "spi.h", "eeprom.h"]
        );
        let roots = discover_native_relink_graph_transition_library_roots(
            &platform,
            &[],
            &analysis,
            source,
        )
        .expect("ordered direct libraries");
        assert_eq!(
            roots
                .iter()
                .map(|root| root.file_name().unwrap().to_string_lossy().into_owned())
                .collect::<Vec<_>>(),
            vec!["Wire", "SPI", "EEPROM"]
        );
        assert_eq!(
            relative_fixture_paths(&wire, &discover_arduino_library_sources(&wire)),
            vec!["src/Wire.cpp", "src/utility/twi.c"]
        );

        let build = temp.path().join("build");
        let sketch_source = build.join("sketch/fixture.ino.cpp");
        let sketch_object = build.join("sketch/fixture.ino.cpp.o");
        std::fs::create_dir_all(sketch_source.parent().expect("sketch parent"))
            .expect("sketch directory");
        std::fs::write(&sketch_source, b"void setup() {}\n").expect("sketch source");
        let sketch_entry = CompileCommandEntry {
            directory: build.to_string_lossy().into_owned(),
            command: String::new(),
            file: sketch_source.to_string_lossy().into_owned(),
            output: Some(sketch_object.to_string_lossy().into_owned()),
            arguments: vec![
                "avr-g++".into(),
                "-c".into(),
                sketch_source.to_string_lossy().into_owned(),
                "-o".into(),
                sketch_object.to_string_lossy().into_owned(),
            ],
        };
        let patched = patch_native_relink_transition_sketch_entry(&sketch_entry, &[], &roots)
            .expect("ordered sketch include roots");
        let source_position = patched
            .arguments
            .iter()
            .position(|token| token == &sketch_entry.file)
            .expect("sketch source token");
        let include_order = patched.arguments[..source_position]
            .iter()
            .filter(|token| token.starts_with("-I"))
            .map(|token| {
                let include_root = std::fs::canonicalize(Path::new(
                    token.trim_start_matches("-I").trim_matches('"'),
                ))
                .expect("canonical include root");
                roots
                    .iter()
                    .position(|root| include_root.starts_with(root))
                    .expect("include belongs to selected root")
            })
            .collect::<Vec<_>>();
        assert_eq!(include_order, vec![0, 1, 2]);
    }

    #[test]
    fn same_graph_library_roots_use_manifest_order_only_after_exact_set_proof() {
        let temp = tempfile::tempdir().expect("tempdir");
        let libraries = temp.path().join("libraries");
        let wire = libraries.join("Wire");
        let spi = libraries.join("SPI");
        let eeprom = libraries.join("EEPROM");
        for root in [&wire, &spi, &eeprom] {
            std::fs::create_dir_all(root).expect("library root");
        }
        let wire = std::fs::canonicalize(wire).expect("canonical Wire");
        let spi = std::fs::canonicalize(spi).expect("canonical SPI");
        let eeprom = std::fs::canonicalize(eeprom).expect("canonical EEPROM");

        let ordered = align_native_relink_library_roots_to_committed_order(
            vec![eeprom.clone(), spi.clone(), wire.clone()],
            &[wire.clone(), spi.clone(), eeprom.clone()],
        )
        .expect("the current exact set inherits only the committed order");
        assert_eq!(ordered, vec![wire.clone(), spi.clone(), eeprom.clone()]);

        assert!(
            align_native_relink_library_roots_to_committed_order(
                vec![wire.clone(), spi.clone(), eeprom.clone()],
                &[wire.clone(), spi.clone()],
            )
            .is_err(),
            "a newly discovered root must not be hidden by the manifest"
        );
        assert!(
            align_native_relink_library_roots_to_committed_order(
                vec![wire.clone(), spi.clone()],
                &[wire.clone(), spi.clone(), eeprom.clone()],
            )
            .is_err(),
            "a missing current root must not be supplied by the manifest"
        );
        assert!(
            align_native_relink_library_roots_to_committed_order(
                vec![wire.clone(), wire.clone(), eeprom.clone()],
                &[wire.clone(), spi.clone(), eeprom.clone()],
            )
            .is_err(),
            "a duplicate current identity must remain fail-closed"
        );
        assert!(
            align_native_relink_library_roots_to_committed_order(
                vec![wire.clone(), spi.clone(), eeprom.clone()],
                &[wire.clone(), wire.clone(), eeprom.clone()],
            )
            .is_err(),
            "a duplicate committed identity must remain fail-closed"
        );

        let replacement_wire = temp.path().join("replacement/Wire");
        std::fs::create_dir_all(&replacement_wire).expect("replacement Wire root");
        let replacement_wire =
            std::fs::canonicalize(replacement_wire).expect("canonical replacement Wire");
        assert!(
            align_native_relink_library_roots_to_committed_order(
                vec![replacement_wire, spi.clone(), eeprom.clone()],
                &[wire, spi, eeprom],
            )
            .is_err(),
            "a same-basename root at a different canonical path is a graph replacement"
        );
    }

    #[test]
    fn same_graph_requires_the_exact_committed_include_preprocessor_contract() {
        let committed = NativeRelinkIncludeManifest {
            headers: vec!["eeprom.h".into(), "spi.h".into(), "wire.h".into()],
            preprocessor_fingerprint: "wire-then-spi-then-eeprom".into(),
            synthesis_safe: true,
        };
        validate_native_relink_same_graph_include_contract(&committed, &committed)
            .expect("an identical include contract remains same-graph");

        let reordered = NativeRelinkIncludeManifest {
            // Header membership is intentionally identical. The fingerprint
            // binds directive order and must distinguish the LTO link graph.
            headers: committed.headers.clone(),
            preprocessor_fingerprint: "spi-then-wire-then-eeprom".into(),
            synthesis_safe: true,
        };
        assert!(
            validate_native_relink_same_graph_include_contract(&reordered, &committed).is_err(),
            "include reordering must leave the same-graph lane before manifest order is applied"
        );
    }

