    #[test]
    fn final_fast_relink_ccdb_enforces_global_source_object_command_bijection() {
        let temp = tempfile::tempdir().expect("tempdir");
        let build = temp.path().join("build");
        std::fs::create_dir_all(&build).expect("build directory");
        let source_a = temp.path().join("a.cpp");
        let source_b = temp.path().join("b.cpp");
        std::fs::write(&source_a, b"int a;\n").expect("source a");
        std::fs::write(&source_b, b"int b;\n").expect("source b");
        let object_a = build.join("a.cpp.o");
        let object_b = build.join("b.cpp.o");
        let make_entry = |source: &Path, object: &Path, define: &str| CompileCommandEntry {
            directory: build.to_string_lossy().to_string(),
            command: String::new(),
            file: source.to_string_lossy().to_string(),
            output: Some(object.to_string_lossy().to_string()),
            arguments: vec![
                "c++".to_string(),
                define.to_string(),
                "-o".to_string(),
                object.to_string_lossy().to_string(),
                source.to_string_lossy().to_string(),
            ],
        };

        let exact = make_entry(&source_a, &object_a, "-DVALUE=1");
        let deduplicated =
            validate_and_deduplicate_fast_relink_ccdb(vec![exact.clone(), exact.clone()])
                .expect("an exact duplicate is harmless");
        assert_eq!(deduplicated.len(), 1);

        let error = validate_and_deduplicate_fast_relink_ccdb(vec![
            exact.clone(),
            make_entry(&source_b, &object_a, "-DVALUE=1"),
        ])
        .expect_err("two sources must not own one object");
        assert!(error.to_string().contains("multiple sources to one object"));

        let error = validate_and_deduplicate_fast_relink_ccdb(vec![
            exact.clone(),
            make_entry(&source_a, &object_b, "-DVALUE=1"),
        ])
        .expect_err("one source must not write two objects");
        assert!(error.to_string().contains("one source to multiple objects"));

        let error = validate_and_deduplicate_fast_relink_ccdb(vec![
            exact,
            make_entry(&source_a, &object_a, "-DVALUE=2"),
        ])
        .expect_err("one source/object must not have conflicting commands");
        assert!(error.to_string().contains("multiple compiler commands"));
    }

