    #[tokio::test]
    async fn fast_relink_synthesis_accepts_content_bound_response_flags_but_rejects_hidden_io() {
        let temp = tempfile::tempdir().expect("tempdir");
        let library = temp.path().join("platform/libraries/WiFi");
        let library_source = library.join("src/WiFiGeneric.cpp");
        std::fs::create_dir_all(library_source.parent().expect("library parent"))
            .expect("library directory");
        std::fs::write(&library_source, b"int wifi_symbol = 1;\n").expect("library source");

        let build = temp.path().join("build");
        let sketch_source = build.join("sketch/fixture.ino.cpp");
        let sketch_object = build.join("sketch/fixture.ino.cpp.o");
        std::fs::create_dir_all(sketch_source.parent().expect("sketch parent"))
            .expect("sketch directory");
        std::fs::write(&sketch_source, b"void setup() {}\nvoid loop() {}\n")
            .expect("sketch source");

        let response = temp.path().join("esp32-cpp-flags.rsp");
        std::fs::write(&response, b"-gdwarf-4 -ggdb -DCK_RESPONSE_VALUE=1\n")
            .expect("response flags");
        let base_entry = CompileCommandEntry {
            directory: build.to_string_lossy().to_string(),
            command: String::new(),
            file: sketch_source.to_string_lossy().to_string(),
            output: Some(sketch_object.to_string_lossy().to_string()),
            arguments: vec![
                "riscv32-esp-elf-g++".to_string(),
                format!("@{}", response.to_string_lossy()),
                "-O1".to_string(),
                "-g0".to_string(),
                "-fno-lto".to_string(),
                "-c".to_string(),
                sketch_source.to_string_lossy().to_string(),
                "-o".to_string(),
                sketch_object.to_string_lossy().to_string(),
            ],
        };

        let entries = synthesize_ccdb_entries_for_added_libraries(
            &build,
            std::slice::from_ref(&library),
            &base_entry,
            std::slice::from_ref(&base_entry),
        )
        .await
        .expect("ordinary ESP32-style response flags are reproducible");
        assert_eq!(entries.len(), 1);
        assert!(
            entries[0]
                .arguments
                .iter()
                .any(|token| token.starts_with('@')),
            "the platform response token must be preserved for the real compiler"
        );
        validate_and_deduplicate_fast_relink_ccdb(vec![base_entry.clone(), entries[0].clone()])
            .expect("response-backed commands pass the final integrity gate");

        let identity_before = fast_relink_command_identity(&base_entry).expect("first identity");
        std::fs::write(&response, b" -gdwarf-4 -ggdb -DCK_RESPONSE_VALUE=1\n")
            .expect("byte-distinct equivalent response flags");
        let identity_after = fast_relink_command_identity(&base_entry).expect("second identity");
        assert_ne!(
            identity_before, identity_after,
            "response bytes, not only tokenized semantics, must bind the CCDB identity"
        );

        let hidden_source = temp.path().join("hidden.cpp");
        let hidden_object = build.join("hidden.cpp.o");
        std::fs::write(&hidden_source, b"int hidden = 1;\n").expect("hidden source");
        std::fs::write(
            &response,
            format!(
                "{} -o {}\n",
                hidden_source.to_string_lossy(),
                hidden_object.to_string_lossy()
            ),
        )
        .expect("malicious response flags");
        let error = synthesize_ccdb_entries_for_added_libraries(
            &build,
            std::slice::from_ref(&library),
            &base_entry,
            std::slice::from_ref(&base_entry),
        )
        .await
        .expect_err("a response file cannot smuggle another source or output");
        assert!(error.to_string().contains("expanded command"));
    }

