    #[tokio::test]
    async fn relink_props_cache_roundtrips_current_schema() {
        let temp = tempfile::tempdir().expect("tempdir");
        let cache_path = temp.path().join("relink_props.json");
        let fqbn = "esp32:esp32:esp32s3:FlashSize=16M,PartitionScheme=fatflash,PSRAM=opi";
        let build_signature = "fixture-build-signature";
        let props = HashMap::from([
            ("build.project_name".to_string(), "wifi.ino".to_string()),
            (
                "recipe.c.combine.pattern".to_string(),
                "esp32-elf-g++ -o wifi.elf".to_string(),
            ),
        ]);

        store_cached_relink_props(
            temp.path(),
            &cache_path,
            fqbn,
            CompileProfile::QuickFast,
            build_signature,
            &props,
        )
        .await;

        let raw: serde_json::Value = serde_json::from_slice(
            &tokio::fs::read(&cache_path)
                .await
                .expect("stored relink cache"),
        )
        .expect("valid cache JSON");
        assert_eq!(
            raw.get("schema_version")
                .and_then(serde_json::Value::as_u64),
            Some(FAST_RELINK_PROPS_CACHE_SCHEMA_VERSION as u64)
        );
        assert_eq!(
            raw.get("property_contract")
                .and_then(serde_json::Value::as_str),
            Some(relink_property_contract(temp.path(), fqbn, CompileProfile::QuickFast).as_str(),)
        );
        assert_eq!(
            load_cached_relink_props(
                temp.path(),
                &cache_path,
                fqbn,
                CompileProfile::QuickFast,
                build_signature,
            )
            .await,
            Some(props)
        );
        assert!(
            load_cached_relink_props(
                temp.path(),
                &cache_path,
                fqbn,
                CompileProfile::QuickFast,
                "different-build-signature",
            )
            .await
            .is_none(),
            "expanded linker/compiler properties must be bound to the current build identity"
        );
        assert!(
            load_cached_relink_props(
                temp.path(),
                &cache_path,
                "esp32:esp32:esp32s3:FlashSize=8M,PartitionScheme=default_8MB,PSRAM=opi",
                CompileProfile::QuickFast,
                build_signature,
            )
            .await
            .is_none(),
            "16MB Flash relink properties must never be reused by an 8MB Flash target"
        );
    }

