    #[test]
    fn esp32_write_timeout_retry_is_limited_to_ck_builtin_targets() {
        let failed =
            "Changing baud rate to 921600...\nA serial exception error occurred: Write timeout";
        for board_id in [
            "esp32", "esp32s2", "esp32s3", "esp32c3", "esp32c5", "esp32c6",
        ] {
            let original_fqbn = format!("esp32:esp32:{}", board_id);
            let (retry_fqbn, speed) = esp32_timeout_retry_fqbn(&original_fqbn, failed)
                .unwrap_or_else(|| panic!("CK built-in target {board_id} should be retryable"));
            #[cfg(target_os = "windows")]
            assert_eq!(speed, 512_000);
            #[cfg(not(target_os = "windows"))]
            assert_eq!(speed, 460_800);
            assert_eq!(
                retry_fqbn,
                format!("{}:UploadSpeed={}", original_fqbn, speed)
            );
        }

        for fqbn in [
            "arduino:avr:nano",
            "esp8266:esp8266:nodemcuv2",
            "STMicroelectronics:stm32:GenF1",
            "thirdparty:esp32:esp32s3",
            "esp32:thirdparty:esp32s3",
            "esp32:esp32:adafruit_feather_esp32s3",
            "esp32:esp32:esp32s3box",
            "ESP32:ESP32:ESP32S3",
        ] {
            assert!(
                esp32_timeout_retry_fqbn(fqbn, failed).is_none(),
                "non-CK target {fqbn} must not get an automatic retry"
            );
        }
    }

    #[test]
    fn esp32_retry_requires_write_timeout_and_a_reducible_speed() {
        assert!(
            esp32_timeout_retry_fqbn(
                "esp32:esp32:esp32s3",
                "Changing baud rate to 921600...\nA fatal error occurred: No serial data received"
            )
            .is_none()
        );
        assert!(
            esp32_timeout_retry_fqbn(
                "esp32:esp32:esp32s3",
                "A serial exception error occurred: Write timeout"
            )
            .is_none()
        );
        assert!(
            esp32_timeout_retry_fqbn(
                "esp32:esp32:esp32s3",
                "Changing baud rate to 115200...\nA serial exception error occurred: Write timeout"
            )
            .is_none()
        );
    }

    #[test]
    fn upload_percentage_parser_keeps_the_whole_integer_and_decimal_value() {
        assert_eq!(parse_upload_percentage("Writing... (7 %)"), Some(7.0));
        assert_eq!(
            parse_upload_percentage("Writing at 0x1234... (47.3 %)"),
            Some(47.3)
        );
        assert_eq!(parse_upload_percentage("Progress: 99.8%"), Some(99.8));
        assert_eq!(parse_upload_percentage("Progress: 100.0%"), Some(100.0));
        assert_eq!(parse_upload_percentage("Progress: 147.3%"), None);
        assert_eq!(parse_upload_percentage("No percentage here"), None);
    }

    #[tokio::test]
    async fn esp32_multisegment_esptool_progress_is_byte_weighted_and_monotonic() {
        let temp = tempfile::tempdir().expect("tempdir");
        let sysroot = crate::sysroot::Sysroot::init(
            Some(temp.path().join("sysroot")),
            "ck-esp32-upload-progress-test",
        )
        .await
        .expect("sysroot");
        let build = temp.path().join("build");
        std::fs::create_dir_all(&build).expect("build dir");
        let images = [
            ("demo.ino.bootloader.bin", 20_224u64),
            ("demo.ino.partitions.bin", 3_072u64),
            ("demo.ino.bin", 838_352u64),
            ("demo.spiffs.bin", 262_144u64),
        ];
        for (name, size) in images {
            let file = std::fs::File::create(build.join(name)).expect("segment image");
            file.set_len(size).expect("segment image size");
        }
        // Arduino-ESP32 keeps boot_app0 in the installed core rather than the
        // build directory; the production plan must still resolve its weight.
        let packaged_boot_app = sysroot
            .root_dir
            .join("packages/esp32/hardware/esp32/3.3.6/tools/partitions/boot_app0.bin");
        std::fs::create_dir_all(packaged_boot_app.parent().unwrap())
            .expect("packaged partitions dir");
        let file = std::fs::File::create(&packaged_boot_app).expect("packaged boot_app0");
        file.set_len(8_192).expect("packaged boot_app0 size");
        std::fs::write(
            build.join("flash_args"),
            "--flash-mode dio --flash-freq 80m --flash-size 16MB\n\
             0x0 demo.ino.bootloader.bin\n\
             0x8000 demo.ino.partitions.bin\n\
             0xe000 boot_app0.bin\n\
             0x10000 demo.ino.bin\n\
             0x310000 demo.spiffs.bin\n",
        )
        .expect("flash_args");

        let segments = load_esp32_upload_segments(
            &sysroot,
            &build,
            "esp32:esp32:esp32s3:FlashSize=16M,PartitionScheme=app3M_fat9M_16MB",
        )
        .expect("ESP32 upload plan");
        assert_eq!(segments.len(), 5);
        assert!(segments.iter().all(|segment| segment.size_resolved));
        assert_eq!(
            segments
                .iter()
                .map(|segment| segment.label)
                .collect::<Vec<_>>(),
            vec!["引导", "分区", "引导", "应用", "文件系统"]
        );

        // Representative esptool v4/v5 output: each image owns a local 0-100
        // range, small images may jump directly to 100, and Wrote/verified
        // lines delimit images. The displayed percentage must never reset.
        let esptool_lines = [
            "Writing at 0x00000000... (100 %)",
            "Wrote 20224 bytes (12868 compressed) at 0x00000000 in 0.3 seconds (effective 539.3 kbit/s)...",
            "Hash of data verified.",
            "Writing at 0x00008000... (42 %)",
            "Wrote 3072 bytes (146 compressed) at 0x00008000 in 0.1 seconds...",
            "Hash of data verified.",
            "Writing at 0x0000e000... (100 %)",
            "Wrote 8192 bytes (47 compressed) at 0x0000e000 in 0.1 seconds...",
            "Hash of data verified.",
            "Writing at 0x00010000... (0.0 %)",
            "Writing at 0x00070000... (50.0 %)",
            "Writing at 0x000dcb00... (100.0 %)",
            "Wrote 838352 bytes (512901 compressed) at 0x00010000 in 5.7 seconds...",
            "Hash of data verified.",
            "Writing at 0x00310000... (0.0 %)",
            "Writing at 0x00330000... (50.0 %)",
            "Writing at 0x0034ffff... (100.0 %)",
            "Wrote 262144 bytes (1984 compressed) at 0x00310000 in 1.2 seconds...",
            "Hash of data verified.",
        ];
        let mut tracker = Esp32UploadProgress::new(segments);
        let updates = esptool_lines
            .iter()
            .filter_map(|line| tracker.observe_line(line))
            .collect::<Vec<_>>();

        assert!(!updates.is_empty());
        assert!(
            updates
                .windows(2)
                .all(|pair| { pair[1].percentage + f32::EPSILON >= pair[0].percentage })
        );
        assert!(
            updates[0].percentage < 10.0,
            "a tiny bootloader reaching local 100% must not finish the whole upload"
        );
        let application_start = updates
            .iter()
            .position(|update| update.segment_label == "应用" && update.local_percentage == 0.0)
            .expect("application local reset");
        assert!(application_start > 0);
        assert!(updates[application_start].percentage >= updates[application_start - 1].percentage);
        let filesystem_start = updates
            .iter()
            .position(|update| update.segment_label == "文件系统" && update.local_percentage == 0.0)
            .expect("filesystem local reset");
        assert!(filesystem_start > application_start);
        assert!(updates[filesystem_start].percentage >= updates[filesystem_start - 1].percentage);
        let last = updates.last().expect("final filesystem progress");
        assert_eq!(last.segment_label, "文件系统");
        assert!((last.percentage - 99.0).abs() < 0.001);
        let message = last.message();
        assert!(message.contains("文件系统"));
        assert!(message.contains("0x310000"));
        assert!(message.contains("总体 99.0%"));
    }

