    #[cfg(any(windows, unix))]
    #[test]
    fn managed_cli_version_memo_is_path_scoped_and_invalidates_same_length_replacement() {
        let _identity_scope = process_identity_test_scope();
        super::clear_arduino_cli_version_memo_cache();
        let temp = tempfile::tempdir().expect("CLI version tempdir");
        let first_root = temp.path().join("first-sysroot");
        let missing_root = temp.path().join("missing-sysroot");
        std::fs::create_dir_all(&first_root).expect("first sysroot");
        std::fs::create_dir_all(&missing_root).expect("missing sysroot");
        let cli = install_executable_cli_fixture(&first_root);

        let calls_before =
            super::arduino_cli_version_probe_calls().load(std::sync::atomic::Ordering::Relaxed);
        let first = super::canonical_prewarm_cli_version_from_root(&first_root);
        assert_ne!(first, "unknown_cli", "the executable fixture must probe");
        let calls_after_first =
            super::arduino_cli_version_probe_calls().load(std::sync::atomic::Ordering::Relaxed);
        assert_eq!(calls_after_first, calls_before + 1);
        assert_eq!(
            super::canonical_prewarm_cli_version_from_root(&missing_root),
            "unknown_cli",
            "a second sysroot must not inherit the first sysroot's CLI version"
        );
        assert_eq!(
            super::canonical_prewarm_cli_version_from_root(&first_root),
            first,
            "an unchanged canonical path and observation should reuse the memo"
        );
        assert_eq!(
            super::arduino_cli_version_probe_calls().load(std::sync::atomic::Ordering::Relaxed),
            calls_after_first,
            "an unchanged CLI must not launch another version process"
        );

        let canonical = super::canonical_bundled_arduino_cli_from_root(&first_root)
            .expect("canonical managed CLI");
        let stamp_before =
            super::capture_bundled_arduino_cli_stamp(&canonical).expect("initial CLI stamp");
        let mut replacement = std::fs::read(&cli).expect("read executable CLI fixture");
        let last = replacement.last_mut().expect("non-empty CLI fixture");
        *last ^= 0x01;
        overwrite_equal_length_restoring_mtime(&cli, &replacement);
        let canonical = super::canonical_bundled_arduino_cli_from_root(&first_root)
            .expect("canonical replaced CLI");
        let stamp_after =
            super::capture_bundled_arduino_cli_stamp(&canonical).expect("replaced CLI stamp");
        assert_ne!(stamp_after.content_sha256, stamp_before.content_sha256);
        assert_ne!(stamp_after.observation, stamp_before.observation);

        let _ = super::canonical_prewarm_cli_version_from_root(&first_root);
        assert_eq!(
            super::arduino_cli_version_probe_calls().load(std::sync::atomic::Ordering::Relaxed),
            calls_after_first + 1,
            "same length and restored mtime must still revoke the version memo"
        );
    }

