    #[cfg(any(windows, unix))]
    #[test]
    fn pre_commit_hook_external_edit_revokes_existing_cache_markers() {
        let _identity_scope = process_identity_test_scope();
        super::invalidate_process_toolchain_identity_cache();
        let fixture = make_toolchain_identity_fixture("request-lease-precommit-hook");
        let fqbn = "acme:demo:board";
        let lease = super::ToolchainIdentityLease::begin(&fixture.root, fqbn)
            .expect("request identity lease");
        let build_path = fixture.root.join("request-build");
        std::fs::create_dir_all(&build_path).expect("request build directory");
        let meta_path = fixture.root.join("request-meta.json");
        std::fs::write(&meta_path, b"old-meta").expect("old BuildMeta marker");
        std::fs::write(
            build_path.join(super::CORE_CACHE_IDENTITY_FILE),
            b"old-core-identity",
        )
        .expect("old Core identity marker");

        struct HookReset;
        impl Drop for HookReset {
            fn drop(&mut self) {
                super::TEST_TOOLCHAIN_PRE_COMMIT_HOOK.with(|slot| {
                    *slot.borrow_mut() = None;
                });
            }
        }
        let _hook_reset = HookReset;
        let edited_core = fixture.core_source.clone();
        super::TEST_TOOLCHAIN_PRE_COMMIT_HOOK.with(|slot| {
            *slot.borrow_mut() = Some(std::sync::Arc::new(move || {
                overwrite_equal_length_restoring_mtime(&edited_core, b"int core_v2;\n");
            }));
        });

        let error = super::revalidate_toolchain_identity_before_cache_commit(
            &lease,
            &fixture.root,
            fqbn,
            &meta_path,
            &build_path,
        )
        .expect_err("pre-commit external edit must block evidence commit");
        assert!(error.to_string().contains("not committed"));
        assert!(!meta_path.exists(), "old BuildMeta must be revoked");
        assert!(
            !build_path.join(super::CORE_CACHE_IDENTITY_FILE).exists(),
            "old Core identity must be revoked"
        );
    }

    #[tokio::test(flavor = "current_thread")]
    async fn locked_signature_and_compile_share_lease_and_close_generation_gap() {
        let _identity_scope = process_identity_test_scope();
        super::invalidate_process_toolchain_identity_cache();
        let fixture = make_toolchain_identity_fixture("request-lease-locked-gap");
        let sysroot =
            crate::sysroot::Sysroot::init(Some(fixture.root.clone()), "request-lease-locked-gap")
                .await
                .expect("locked test sysroot");
        let fqbn = "acme:demo:board";
        let lease = super::ToolchainIdentityLease::begin(&sysroot.root_dir, fqbn)
            .expect("locked request identity lease");
        let build_signature = super::compute_fast_build_signature(
            fqbn,
            "arduino-cli-test",
            lease.toolchain_key(),
            &[],
        );

        // This is the historical signature/compile gap. The leased entry must
        // reject it before a compiler or preprocessor execution boundary.
        super::invalidate_process_toolchain_identity_cache();
        let boundary = std::sync::Arc::new(std::sync::atomic::AtomicUsize::new(0));
        let result = super::TEST_COMPILE_EXECUTION_BOUNDARY_COUNT
            .scope(
                std::sync::Arc::clone(&boundary),
                super::compile_sketch_string_locked_cancellable_with_identity_lease(
                    &sysroot,
                    "void setup() {}\nvoid loop() {}\n",
                    fqbn,
                    &[],
                    "locked-content-sha256",
                    1,
                    &build_signature,
                    None,
                    super::CompileProfile::Release,
                    super::CkExactReusePolicy::Deny,
                    lease,
                    super::BuildCancellation::new(),
                    |_percentage, _message| {},
                    |_line| {},
                ),
            )
            .await;
        let error = result.expect_err("stale locked lease must fail closed");
        assert!(error.to_string().contains("managed Core packages changed"));
        assert_eq!(
            boundary.load(std::sync::atomic::Ordering::SeqCst),
            0,
            "locked build must not enter a compiler boundary after the lease goes stale"
        );
    }

    #[test]
    fn persistent_toolchain_identity_reuses_fresh_process_metadata_proof() {
        let _identity_scope = process_identity_test_scope();
        let fixture = make_qualified_esp_toolchain_identity_fixture();
        let fqbn = "esp32:esp32:esp32c6";
        let (strong, strong_source) = resolve_toolchain_cache_key_from_root(&fixture.root, fqbn);
        assert_eq!(
            strong_source,
            ToolchainIdentityResolutionSource::StrongContent
        );

        // A new process has no strong-content memo.  Clearing that memo here
        // models the same state while retaining only the on-disk CK proof.
        super::invalidate_process_toolchain_identity_cache();
        strong_content_memo_cache()
            .lock()
            .expect("strong memo lock")
            .clear();
        let (reused, reused_source) = resolve_toolchain_cache_key_from_root(&fixture.root, fqbn);
        assert_eq!(
            reused_source,
            ToolchainIdentityResolutionSource::PersistentMetadata
        );
        assert_eq!(
            reused, strong,
            "persistent reuse must preserve the exact key"
        );
    }

    #[test]
    fn expired_process_identity_reuses_only_its_paths_and_revalidates_persistent_proof() {
        let _identity_scope = process_identity_test_scope();
        let fixture = make_qualified_esp_toolchain_identity_fixture();
        let fqbn = "esp32:esp32:esp32c6";
        let (strong, source) = resolve_toolchain_cache_key_from_root(&fixture.root, fqbn);
        assert_eq!(source, ToolchainIdentityResolutionSource::StrongContent);

        let selected_version = "3.3.6";
        let plan =
            super::target_tool_plan(&fixture.root, "esp32", "esp32", "esp32c6", selected_version);
        let lookup = super::process_toolchain_identity_cache_key(
            &fixture.root,
            fqbn,
            selected_version,
            &plan,
        )
        .expect("process identity lookup");
        {
            let mut cache = super::process_toolchain_identity_cache()
                .lock()
                .expect("process identity cache");
            cache
                .get_mut(&lookup)
                .expect("seeded process memo")
                .validated_at = std::time::Instant::now()
                .checked_sub(super::PROCESS_TOOLCHAIN_IDENTITY_CACHE_MAX_AGE)
                .and_then(|value| value.checked_sub(std::time::Duration::from_secs(1)))
                .expect("expired instant");
        }

        let (revalidated, source) = resolve_toolchain_cache_key_from_root(&fixture.root, fqbn);
        assert_eq!(
            source,
            ToolchainIdentityResolutionSource::PersistentMetadata
        );
        assert_eq!(revalidated, strong);
        assert_eq!(
            super::load_process_toolchain_identity(
                &lookup,
                &fixture.root,
                "esp32",
                "esp32",
                selected_version,
                &plan,
            )
            .as_deref(),
            Some(strong.as_str()),
            "the revalidated persistent record must refresh the process proof"
        );
    }

    #[test]
    fn persistent_snapshot_process_guard_binding_is_exact_and_fail_closed() {
        let fixture = make_qualified_esp_toolchain_identity_fixture();
        let selected_version = "3.3.6";
        let plan =
            super::target_tool_plan(&fixture.root, "esp32", "esp32", "esp32c6", selected_version);
        let snapshot = super::current_toolchain_identity_snapshot(
            &fixture.root,
            "esp32",
            "esp32",
            selected_version,
            &plan,
        )
        .expect("persistent snapshot");
        let guard = super::process_toolchain_identity_guard(
            &fixture.root,
            "esp32",
            "esp32",
            selected_version,
            &plan,
        )
        .expect("process guard");
        assert!(super::persistent_snapshot_matches_process_guard(
            &snapshot, &guard
        ));

        let mut missing = snapshot.clone();
        missing.pop().expect("non-empty identity fixture");
        assert!(
            !super::persistent_snapshot_matches_process_guard(&missing, &guard),
            "a persistent record cannot omit a current strong input"
        );

        let mut stale = snapshot;
        stale[0].change_marker.primary = stale[0].change_marker.primary.saturating_add(1);
        assert!(
            !super::persistent_snapshot_matches_process_guard(&stale, &guard),
            "a changed host-native marker must revoke persistent reuse"
        );

        let mut forged_identity = super::current_toolchain_identity_snapshot(
            &fixture.root,
            "esp32",
            "esp32",
            selected_version,
            &plan,
        )
        .expect("fresh persistent snapshot");
        let entry = forged_identity
            .iter_mut()
            .find(|entry| entry.kind == super::ToolchainIdentitySnapshotKind::File)
            .expect("file strong input");
        let unchanged_metadata = (
            entry.len,
            entry.modified_ns,
            entry.change_marker,
            entry.members.clone(),
        );
        entry.file_identity.file = entry.file_identity.file.wrapping_add(1);
        assert_eq!(
            (
                entry.len,
                entry.modified_ns,
                entry.change_marker,
                entry.members.clone(),
            ),
            unchanged_metadata,
            "the test models a replacement with the same length, mtime, ChangeTime and directory membership"
        );
        assert!(
            !super::persistent_snapshot_matches_process_guard(&forged_identity, &guard),
            "a matching metadata record with a different volume/file identity must not reuse persistent proof"
        );
    }

    #[test]
    fn matching_toolchain_identity_requests_singleflight_and_different_fqbns_do_not_share_a_lock() {
        let _identity_scope = process_identity_test_scope();
        super::invalidate_process_toolchain_identity_cache();
        let fixture = make_qualified_esp_toolchain_identity_fixture();
        let fqbn = "esp32:esp32:esp32c6";
        let root = std::sync::Arc::new(fixture.root.clone());
        let barrier = std::sync::Arc::new(std::sync::Barrier::new(8));
        let workers = (0..8)
            .map(|_| {
                let root = std::sync::Arc::clone(&root);
                let barrier = std::sync::Arc::clone(&barrier);
                std::thread::spawn(move || {
                    barrier.wait();
                    resolve_toolchain_cache_key_from_root(root.as_path(), fqbn)
                })
            })
            .collect::<Vec<_>>();
        let results = workers
            .into_iter()
            .map(|worker| worker.join().expect("identity worker"))
            .collect::<Vec<_>>();
        assert_eq!(
            results
                .iter()
                .filter(|(_, source)| {
                    *source == ToolchainIdentityResolutionSource::StrongContent
                })
                .count(),
            1,
            "one same-key request performs the strong scan and every waiter rechecks the memo"
        );
        assert!(results.iter().all(|(key, _)| key == &results[0].0));

        let selected_version = "3.3.6";
        let plan =
            super::target_tool_plan(&fixture.root, "esp32", "esp32", "esp32c6", selected_version);
        let first_key = super::process_toolchain_identity_cache_key(
            &fixture.root,
            "esp32:esp32:esp32c6:FlashSize=4M",
            selected_version,
            &plan,
        )
        .expect("first key");
        let second_key = super::process_toolchain_identity_cache_key(
            &fixture.root,
            "esp32:esp32:esp32c6:FlashSize=8M",
            selected_version,
            &plan,
        )
        .expect("second key");
        let first_lock = super::process_toolchain_identity_singleflight_lock(&first_key);
        let same_lock = super::process_toolchain_identity_singleflight_lock(&first_key);
        let second_lock = super::process_toolchain_identity_singleflight_lock(&second_key);
        assert!(std::sync::Arc::ptr_eq(&first_lock, &same_lock));
        assert!(!std::sync::Arc::ptr_eq(&first_lock, &second_lock));
    }

