    #[test]
    fn process_toolchain_identity_is_scoped_and_generation_invalidated() {
        let _identity_scope = process_identity_test_scope();
        super::invalidate_process_toolchain_identity_cache();
        let first = make_qualified_esp_toolchain_identity_fixture();
        let second = make_qualified_esp_toolchain_identity_fixture();
        let fqbn_a = "esp32:esp32:esp32c6:FlashSize=4M";
        let fqbn_b = "esp32:esp32:esp32c6:FlashSize=8M";

        let (first_key, source) = resolve_toolchain_cache_key_from_root(&first.root, fqbn_a);
        assert_eq!(source, ToolchainIdentityResolutionSource::StrongContent);
        let selected_version = "3.3.6";
        let plan_a = super::target_tool_plan_with_options(
            &first.root,
            "esp32",
            "esp32",
            "esp32c6",
            Some("FlashSize=4M"),
            selected_version,
        );
        let lookup_a = super::process_toolchain_identity_cache_key(
            &first.root,
            fqbn_a,
            selected_version,
            &plan_a,
        )
        .expect("first process lookup key");
        assert_eq!(
            super::load_process_toolchain_identity(
                &lookup_a,
                &first.root,
                "esp32",
                "esp32",
                selected_version,
                &plan_a,
            )
            .as_deref(),
            Some(first_key.as_str()),
            "same generation and full target identity should hit memory"
        );

        let lookup_b = super::process_toolchain_identity_cache_key(
            &first.root,
            fqbn_b,
            selected_version,
            &super::target_tool_plan_with_options(
                &first.root,
                "esp32",
                "esp32",
                "esp32c6",
                Some("FlashSize=8M"),
                selected_version,
            ),
        )
        .expect("option-specific lookup key");
        assert_ne!(lookup_a, lookup_b, "complete FQBN options are cache scope");
        let second_plan = super::target_tool_plan_with_options(
            &second.root,
            "esp32",
            "esp32",
            "esp32c6",
            Some("FlashSize=4M"),
            selected_version,
        );
        let second_lookup = super::process_toolchain_identity_cache_key(
            &second.root,
            fqbn_a,
            selected_version,
            &second_plan,
        )
        .expect("second sysroot lookup key");
        assert_ne!(
            lookup_a, second_lookup,
            "canonical sysroot is part of the process cache scope"
        );

        super::invalidate_process_toolchain_identity_cache();
        assert!(
            super::load_process_toolchain_identity(
                &lookup_a,
                &first.root,
                "esp32",
                "esp32",
                selected_version,
                &plan_a,
            )
            .is_none(),
            "managed package generation bump must make the old memo unreachable"
        );
        let (after_bump, source) = resolve_toolchain_cache_key_from_root(&first.root, fqbn_a);
        assert_eq!(
            source,
            ToolchainIdentityResolutionSource::PersistentMetadata
        );
        assert_eq!(after_bump, first_key);
    }

    #[test]
    fn process_toolchain_identity_never_hides_core_version_install_or_remove() {
        let _identity_scope = process_identity_test_scope();
        super::invalidate_process_toolchain_identity_cache();
        let fixture = make_toolchain_identity_fixture("process-version-change");
        let fqbn = "acme:demo:board";
        let (version_one, _) = resolve_toolchain_cache_key_from_root(&fixture.root, fqbn);
        assert!(version_one.starts_with("acme|demo|1.2.3|"));

        let version_two = fixture.root.join("packages/acme/hardware/demo/2.0.0");
        std::fs::create_dir_all(version_two.join("cores/demo")).expect("new Core source root");
        std::fs::create_dir_all(version_two.join("variants/default"))
            .expect("new Core variant root");
        std::fs::write(version_two.join("platform.txt"), "recipe.c.o.pattern=v2\n")
            .expect("new Core platform config");
        std::fs::write(version_two.join("boards.txt"), "board.name=Demo v2\n")
            .expect("new Core board config");
        std::fs::write(version_two.join("cores/demo/core.cpp"), "int core_v2;\n")
            .expect("new Core source");

        let (installed, _) = resolve_toolchain_cache_key_from_root(&fixture.root, fqbn);
        assert!(
            installed.starts_with("acme|demo|2.0.0|"),
            "new highest Core version must bypass the old process memo"
        );
        assert_ne!(installed, version_one);

        std::fs::remove_dir_all(&version_two).expect("remove newer Core version");
        let (removed, _) = resolve_toolchain_cache_key_from_root(&fixture.root, fqbn);
        assert!(removed.starts_with("acme|demo|1.2.3|"));
        assert_eq!(
            removed, version_one,
            "removing the newer Core restores v1 identity"
        );
    }

