    #[test]
    fn persistent_toolchain_identity_rejects_cross_host_and_legacy_v5_schema_records() {
        let _identity_scope = process_identity_test_scope();
        let fixture = make_qualified_esp_toolchain_identity_fixture();
        let fqbn = "esp32:esp32:esp32c6";
        assert_eq!(
            resolve_toolchain_cache_key_from_root(&fixture.root, fqbn).1,
            ToolchainIdentityResolutionSource::StrongContent
        );
        let directory = toolchain_identity_cache_directory(&fixture.root).expect("cache dir");
        let target_scope = "esp32:esp32:esp32c6";
        let scope = toolchain_identity_cache_scope("esp32", "esp32", target_scope);
        let original_path = persistent_cache_candidates(&directory, &scope)
            .expect("bounded persistent candidates")
            .into_iter()
            .next()
            .expect("persistent cache record")
            .0;
        let original_bytes = std::fs::read(&original_path).expect("read identity record");
        let original: super::PersistentToolchainIdentity =
            serde_json::from_slice(&original_bytes).expect("parse identity record");
        std::fs::remove_file(&original_path).expect("remove original identity record");

        let other_os = format!("{}-other", std::env::consts::OS);
        let other_arch = format!("{}-other", std::env::consts::ARCH);
        assert_ne!(
            scope,
            toolchain_identity_cache_scope_for_host(
                "esp32",
                "esp32",
                target_scope,
                &other_os,
                std::env::consts::ARCH
            ),
            "cache filenames must be host-OS scoped"
        );
        assert_ne!(
            scope,
            toolchain_identity_cache_scope_for_host(
                "esp32",
                "esp32",
                target_scope,
                std::env::consts::OS,
                &other_arch
            ),
            "cache filenames must be host-architecture scoped"
        );

        for (index, forged) in [
            {
                let mut value = original.clone();
                value.host_os = other_os.clone();
                value
            },
            {
                let mut value = original.clone();
                value.host_arch = other_arch.clone();
                value
            },
            {
                let mut value = original.clone();
                value.schema_version = 5;
                value
            },
            {
                let mut value = original.clone();
                value.identity_schema = "ck_toolchain_cache_key_v11".to_string();
                value
            },
        ]
        .into_iter()
        .enumerate()
        {
            // Keep the payload digest valid. Rejection must come from the
            // explicit host/schema binding, not record corruption.
            let path = write_forged_toolchain_identity_record(
                &directory,
                &scope,
                &format!("forged-{index}"),
                &forged,
            );
            assert!(
                super::load_persistent_toolchain_identity(
                    &fixture.root,
                    "esp32",
                    "esp32",
                    "3.3.6",
                    &super::target_tool_plan(&fixture.root, "esp32", "esp32", "esp32c6", "3.3.6",),
                )
                .is_none(),
                "forged host/schema record {index} must fail closed"
            );
            assert!(!path.exists(), "rejected record should be removed");
        }
    }

