    #[test]
    fn persistent_toolchain_identity_invalidates_every_strong_input_class() {
        let _identity_scope = process_identity_test_scope();
        let fixture = make_toolchain_identity_fixture("invalidation");
        let fqbn = "acme:demo:board";
        let (initial, source) = resolve_toolchain_cache_key_from_root(&fixture.root, fqbn);
        assert_eq!(source, ToolchainIdentityResolutionSource::StrongContent);
        assert_eq!(
            resolve_toolchain_cache_key_from_root(&fixture.root, fqbn).1,
            ToolchainIdentityResolutionSource::StrongContent,
            "Generic targets must not receive metadata-only identity reuse"
        );

        let platform = fixture.platform_root.join("platform.txt");
        overwrite_equal_length_with_new_mtime(&platform, b"recipe.c.o.pattern=v2\n");
        let (config_replaced, source) = resolve_toolchain_cache_key_from_root(&fixture.root, fqbn);
        assert_eq!(source, ToolchainIdentityResolutionSource::StrongContent);
        assert_ne!(config_replaced, initial, "equal-length config replacement");
        let local_config = fixture.platform_root.join("boards.local.txt");
        std::fs::write(&local_config, "board.menu.Fast=on\n").expect("add local config");
        let (config_added, source) = resolve_toolchain_cache_key_from_root(&fixture.root, fqbn);
        assert_eq!(source, ToolchainIdentityResolutionSource::StrongContent);
        assert_ne!(config_added, config_replaced, "config addition");
        std::fs::remove_file(&local_config).expect("delete local config");
        let (config_deleted, source) = resolve_toolchain_cache_key_from_root(&fixture.root, fqbn);
        assert_eq!(source, ToolchainIdentityResolutionSource::StrongContent);
        assert_eq!(config_deleted, config_replaced, "config deletion");

        overwrite_equal_length_with_new_mtime(
            &fixture.partition_file,
            b"app0,app,factory,0x10000,2M\n",
        );
        let (partition_replaced, source) =
            resolve_toolchain_cache_key_from_root(&fixture.root, fqbn);
        assert_eq!(source, ToolchainIdentityResolutionSource::StrongContent);
        assert_ne!(partition_replaced, config_deleted, "partition replacement");
        let extra_partition = fixture
            .partition_file
            .parent()
            .expect("partition parent")
            .join("ota.csv");
        std::fs::write(&extra_partition, "ota_0,app,ota_0,0x10000,1M\n").expect("add partition");
        let (partition_added, source) = resolve_toolchain_cache_key_from_root(&fixture.root, fqbn);
        assert_eq!(source, ToolchainIdentityResolutionSource::StrongContent);
        assert_ne!(partition_added, partition_replaced, "partition addition");
        std::fs::remove_file(&extra_partition).expect("delete partition");
        let (partition_deleted, source) =
            resolve_toolchain_cache_key_from_root(&fixture.root, fqbn);
        assert_eq!(source, ToolchainIdentityResolutionSource::StrongContent);
        assert_eq!(partition_deleted, partition_replaced, "partition deletion");

        overwrite_equal_length_with_new_mtime(&fixture.critical_tool, b"tool-v2");
        let (tool_replaced, source) = resolve_toolchain_cache_key_from_root(&fixture.root, fqbn);
        assert_eq!(source, ToolchainIdentityResolutionSource::StrongContent);
        assert_ne!(
            tool_replaced, partition_deleted,
            "critical tool replacement"
        );
        let extra_tool =
            fixture
                .critical_tool
                .parent()
                .expect("tool parent")
                .join(if cfg!(windows) {
                    "demo-objcopy.exe"
                } else {
                    "demo-objcopy"
                });
        std::fs::write(&extra_tool, b"objcopy-v1").expect("add critical tool");
        let (tool_added, source) = resolve_toolchain_cache_key_from_root(&fixture.root, fqbn);
        assert_eq!(source, ToolchainIdentityResolutionSource::StrongContent);
        assert_ne!(tool_added, tool_replaced, "critical tool addition");
        std::fs::remove_file(&extra_tool).expect("delete critical tool");
        let (tool_deleted, source) = resolve_toolchain_cache_key_from_root(&fixture.root, fqbn);
        assert_eq!(source, ToolchainIdentityResolutionSource::StrongContent);
        assert_eq!(tool_deleted, tool_replaced, "critical tool deletion");

        overwrite_equal_length_with_new_mtime(&fixture.core_source, b"int core_v2;\n");
        let (source_replaced, source) = resolve_toolchain_cache_key_from_root(&fixture.root, fqbn);
        assert_eq!(source, ToolchainIdentityResolutionSource::StrongContent);
        assert_ne!(source_replaced, tool_deleted, "Core source replacement");
        let extra_source = fixture
            .core_source
            .parent()
            .expect("source parent")
            .join("helper.cpp");
        std::fs::write(&extra_source, "int helper;\n").expect("add Core source");
        let (source_added, source) = resolve_toolchain_cache_key_from_root(&fixture.root, fqbn);
        assert_eq!(source, ToolchainIdentityResolutionSource::StrongContent);
        assert_ne!(source_added, source_replaced, "Core source addition");
        std::fs::remove_file(&extra_source).expect("delete Core source");
        let (source_deleted, source) = resolve_toolchain_cache_key_from_root(&fixture.root, fqbn);
        assert_eq!(source, ToolchainIdentityResolutionSource::StrongContent);
        assert_eq!(source_deleted, source_replaced, "Core source deletion");
        let renamed_source = fixture
            .core_source
            .parent()
            .expect("source parent")
            .join("renamed.cpp");
        std::fs::rename(&fixture.core_source, &renamed_source).expect("rename Core source");
        let (source_renamed, source) = resolve_toolchain_cache_key_from_root(&fixture.root, fqbn);
        assert_eq!(source, ToolchainIdentityResolutionSource::StrongContent);
        assert_ne!(source_renamed, source_deleted, "Core source rename");
    }

    #[cfg(windows)]
    #[test]
    fn windows_process_guard_uses_one_locked_non_reparse_handle() {
        use sha2::Digest;

        let temp = tempfile::tempdir().expect("Windows handle fixture");
        let guard_root = temp.path().join("guard-root");
        std::fs::create_dir_all(&guard_root).expect("guard root");
        let canonical_root =
            super::windows_normalized_canonical_root(&guard_root).expect("canonical guard root");
        let path = guard_root.join("tool.exe");
        let moved = guard_root.join("tool-old.exe");
        let contents = vec![0x5au8; 96 * 1024 + 17];
        std::fs::write(&path, &contents).expect("write handle fixture");
        let (handle, before) = super::open_windows_process_guard_handle(&path, &canonical_root)
            .expect("open one process-guard handle");
        let mut read_handle = super::open_windows_process_guard_read_handle(&path)
            .expect("open the content read handle");
        assert!(
            std::fs::rename(&path, &moved).is_err(),
            "the guarded pathname must not be replaceable while its read handle is live"
        );
        assert!(
            std::fs::OpenOptions::new().write(true).open(&path).is_err(),
            "the guarded object must not accept a concurrent writer"
        );
        let (digest, bytes_read) = super::windows_hash_process_guard_file(&mut read_handle, before)
            .expect("hash through the pinned pathname");
        assert_eq!(bytes_read, contents.len() as u64);
        assert_eq!(
            digest.as_slice(),
            sha2::Sha256::digest(&contents).as_slice()
        );
        assert_eq!(
            super::windows_process_guard_handle_metadata(&handle).expect("stable metadata"),
            before,
            "the attributes handle must still observe the hashed object"
        );
        drop(read_handle);
        drop(handle);
        std::fs::rename(&path, &moved).expect("pathname unlock after handle drop");

        let outside = temp.path().join("outside");
        let linked = guard_root.join("linked");
        std::fs::create_dir_all(&outside).expect("junction target");
        junction::create(&outside, &linked).expect("junction fixture");
        assert!(
            super::open_windows_process_guard_handle(&linked, &canonical_root).is_none(),
            "a final-component reparse point must fail closed"
        );
        let escaped = outside.join("escaped.exe");
        std::fs::write(&escaped, b"outside").expect("ancestor-junction target");
        let escaped_via_link = linked.join("escaped.exe");
        assert!(
            super::open_windows_process_guard_handle(&escaped_via_link, &canonical_root).is_none(),
            "the final handle path must reject an ancestor junction escape"
        );
        junction::delete(&linked).expect("remove junction fixture");
    }

    #[cfg(any(windows, unix))]
    #[test]
    fn qualified_avr_platform_bootloader_content_is_strong_identity() {
        let _identity_scope = process_identity_test_scope();
        let temp = tempfile::tempdir().expect("qualified AVR fixture");
        let root = temp.path().join("sysroot-qualified-avr");
        let platform = root.join("packages/arduino/hardware/avr/1.8.6");
        let compiler = root.join("packages/arduino/tools/avr-gcc/7.3.0");
        let uploader = root.join("packages/arduino/tools/avrdude/6.3.0");
        for directory in [
            platform.join("cores/arduino"),
            platform.join("variants/standard"),
            platform.join("bootloaders/optiboot"),
            compiler.join("bin"),
            uploader.join("bin"),
            root.join("bin"),
            root.join("cache"),
        ] {
            std::fs::create_dir_all(directory).expect("AVR identity directory");
        }
        std::fs::write(
            platform.join("platform.txt"),
            "recipe.c.o.pattern=avr-gcc\n",
        )
        .expect("AVR platform config");
        std::fs::write(
            platform.join("boards.txt"),
            "uno.name=Arduino Uno\nuno.bootloader.file=optiboot_atmega328.hex\n",
        )
        .expect("AVR board config");
        std::fs::write(platform.join("cores/arduino/main.cpp"), "int main(){}\n")
            .expect("AVR core source");
        std::fs::write(
            platform.join("variants/standard/pins_arduino.h"),
            "#define LED 13\n",
        )
        .expect("AVR variant");
        std::fs::write(
            platform.join("installed.json"),
            serde_json::to_vec(&serde_json::json!({
                "packages": [{"platforms": [{
                    "architecture": "avr",
                    "version": "1.8.6",
                    "toolsDependencies": [
                        {"packager": "arduino", "name": "avr-gcc", "version": "7.3.0"},
                        {"packager": "arduino", "name": "avrdude", "version": "6.3.0"}
                    ]
                }]}]
            }))
            .expect("AVR installed receipt"),
        )
        .expect("AVR installed receipt file");
        let compiler_binary = compiler.join(if cfg!(windows) {
            "bin/avr-gcc.exe"
        } else {
            "bin/avr-gcc"
        });
        let uploader_binary = uploader.join(if cfg!(windows) {
            "bin/avrdude.exe"
        } else {
            "bin/avrdude"
        });
        std::fs::write(compiler_binary, b"avr-gcc-v1").expect("AVR compiler");
        std::fs::write(uploader_binary, b"avrdude-v1").expect("AVR uploader");
        std::fs::write(bundled_arduino_cli_lexical_path(&root), b"arduino-cli-v1")
            .expect("AVR Arduino CLI");
        let bootloader = platform.join("bootloaders/optiboot/optiboot_atmega328.hex");
        std::fs::write(&bootloader, b":0100000001FE\n").expect("AVR bootloader");

        let fqbn = "arduino:avr:uno";
        let (initial, source) = resolve_toolchain_cache_key_from_root(&root, fqbn);
        assert_eq!(source, ToolchainIdentityResolutionSource::StrongContent);
        assert_eq!(
            resolve_toolchain_cache_key_from_root(&root, fqbn).1,
            ToolchainIdentityResolutionSource::ProcessMemory
        );
        overwrite_equal_length_restoring_mtime(&bootloader, b":0100000002FD\n");
        let (changed, source) = resolve_toolchain_cache_key_from_root(&root, fqbn);
        assert_eq!(source, ToolchainIdentityResolutionSource::StrongContent);
        assert_ne!(
            changed, initial,
            "with_bootloader artifact input must change the strong key"
        );
    }

