    #[test]
    fn qualified_strong_identity_is_portable_across_roots_receipt_metadata_and_global_shims() {
        let _identity_scope = process_identity_test_scope();
        let first = make_qualified_esp_toolchain_identity_fixture();
        let second = make_qualified_esp_toolchain_identity_fixture();
        assert_ne!(
            first.root.canonicalize().expect("first canonical root"),
            second.root.canonicalize().expect("second canonical root"),
            "the fixture must exercise different absolute user/sysroot paths"
        );

        write_fixture_ccache(&first.root, b"ccache-v1");
        write_fixture_ccache(&second.root, b"ccache-v1");

        let first_shims = first.root.join("bin/ccache");
        let second_shims = second.root.join("bin/ccache");
        std::fs::create_dir_all(&first_shims).expect("first shim directory");
        std::fs::create_dir_all(&second_shims).expect("second shim directory");
        std::fs::write(first_shims.join("riscv32-esp-elf-gcc.exe"), b"ccache-v1")
            .expect("first selected shim");
        for name in [
            "riscv32-esp-elf-gcc.exe",
            "avr-gcc.exe",
            "arm-none-eabi-gcc.exe",
            "xtensa-esp32-elf-gcc.exe",
        ] {
            std::fs::write(second_shims.join(name), b"ccache-v1").expect("second global shim");
        }

        let second_receipt = second
            .root
            .join("packages/esp32/hardware/esp32/3.3.6/installed.json");
        let mut receipt = serde_json::from_slice::<serde_json::Value>(
            &std::fs::read(&second_receipt).expect("read second receipt"),
        )
        .expect("parse second receipt");
        receipt["downloadedAt"] = serde_json::json!("different-client-install-time");
        receipt["packageIndexSnapshot"] = serde_json::json!({
            "unrelatedBoard": "newer-than-qualification-machine",
            "userRoot": "C:/Users/a-completely-different-user/Documents/CK"
        });
        std::fs::write(
            &second_receipt,
            serde_json::to_vec_pretty(&receipt).expect("serialize second receipt"),
        )
        .expect("rewrite unrelated receipt metadata");

        assert_eq!(
            qualified_esp_strong_toolchain_key(&first),
            qualified_esp_strong_toolchain_key(&second),
            "absolute user roots, package-index provenance and unrelated board shims are not compiler inputs"
        );
    }

