    #[test]
    fn qualified_process_guard_invalidates_deep_inputs_with_restored_mtime() {
        let _identity_scope = process_identity_test_scope();
        let fixture = make_qualified_esp_toolchain_identity_fixture();
        let fqbn = "esp32:esp32:esp32c6:FlashSize=16M,PartitionScheme=app3M_fat9M_16MB";
        let (mut previous_key, source) = resolve_toolchain_cache_key_from_root(&fixture.root, fqbn);
        assert_eq!(source, ToolchainIdentityResolutionSource::StrongContent);
        assert_eq!(
            resolve_toolchain_cache_key_from_root(&fixture.root, fqbn).1,
            ToolchainIdentityResolutionSource::ProcessMemory
        );

        for (label, path, replacement) in [
            (
                "compiler runtime DLL",
                &fixture.compiler_runtime_dll,
                b"dll-v2".as_slice(),
            ),
            ("LTO plugin", &fixture.lto_plugin, b"lto-v2".as_slice()),
            (
                "default specs",
                &fixture.default_specs,
                b"specs-v2".as_slice(),
            ),
            (
                "target multilib",
                &fixture.target_multilib,
                b"libstdcpp-v2".as_slice(),
            ),
            (
                "SDK flags",
                &fixture.sdk_flags,
                b"-march=rv32imac_zicsr_zifencei -DCK_FIXTURE_REV=2\n".as_slice(),
            ),
            (
                "Core platform generator",
                &fixture.platform_generator,
                b"part-v2".as_slice(),
            ),
        ] {
            overwrite_equal_length_restoring_mtime(path, replacement);
            let (changed, source) = resolve_toolchain_cache_key_from_root(&fixture.root, fqbn);
            assert_eq!(
                source,
                ToolchainIdentityResolutionSource::StrongContent,
                "{label} metadata change must bypass ProcessMemory"
            );
            assert_ne!(changed, previous_key, "{label} content is identity");
            let (warm, source) = resolve_toolchain_cache_key_from_root(&fixture.root, fqbn);
            assert_eq!(source, ToolchainIdentityResolutionSource::ProcessMemory);
            assert_eq!(warm, changed);
            previous_key = changed;
        }
    }

