    #[cfg(any(windows, unix))]
    #[test]
    fn generic_stm32_system_path_change_forces_new_strong_identity() {
        let _identity_scope = process_identity_test_scope();
        super::invalidate_process_toolchain_identity_cache();
        let temp = tempfile::tempdir().expect("STM32 generic identity tempdir");
        let root = temp.path().join("sysroot-stm32-system");
        let platform = root.join("packages/STMicroelectronics/hardware/stm32/2.12.0");
        let system = platform.join("system");
        let linker_script = system.join("ldscript.ld");
        for directory in [platform.join("cores/arduino"), system, root.join("cache")] {
            std::fs::create_dir_all(directory).expect("STM32 generic fixture directory");
        }
        std::fs::write(
            platform.join("platform.txt"),
            "build.system.path={runtime.platform.path}/system\nrecipe.c.combine.pattern=-T{build.system.path}/ldscript.ld\n",
        )
        .expect("STM32 platform recipe");
        std::fs::write(platform.join("boards.txt"), "GenF4.name=STM32 GenF4\n")
            .expect("STM32 boards definition");
        std::fs::write(platform.join("cores/arduino/main.cpp"), "int core_v1;\n")
            .expect("STM32 core source");
        std::fs::write(
            &linker_script,
            "MEMORY { FLASH (rx) : ORIGIN = 0x08000000 }\n",
        )
        .expect("STM32 linker script");

        let fqbn = "STMicroelectronics:stm32:GenF4";
        let selected_version = super::select_highest_installed_core_version(
            &root.join("packages/STMicroelectronics/hardware/stm32"),
        )
        .expect("STM32 selected Core version");
        let plan = super::target_tool_plan(
            &root,
            "STMicroelectronics",
            "stm32",
            "GenF4",
            &selected_version,
        );
        assert!(
            !super::target_tool_plan_allows_identity_reuse(&plan),
            "an unmodelled STM32 recipe must not receive metadata-only reuse"
        );

        let (first, first_source) = resolve_toolchain_cache_key_from_root(&root, fqbn);
        assert_eq!(
            first_source,
            ToolchainIdentityResolutionSource::StrongContent
        );
        assert_eq!(
            resolve_toolchain_cache_key_from_root(&root, fqbn).1,
            ToolchainIdentityResolutionSource::StrongContent,
            "Generic STM32 must not enter the process or persistent identity cache"
        );

        overwrite_equal_length_restoring_mtime(
            &linker_script,
            b"MEMORY { FLASH (rx) : ORIGIN = 0x08000001 }\n",
        );
        let (changed, changed_source) = resolve_toolchain_cache_key_from_root(&root, fqbn);
        assert_eq!(
            changed_source,
            ToolchainIdentityResolutionSource::StrongContent
        );
        assert_ne!(
            changed, first,
            "a build.system.path linker-script mutation must revoke the prior identity"
        );
    }

    #[test]
    fn persistent_toolchain_identity_does_not_walk_library_catalogues() {
        let _identity_scope = process_identity_test_scope();
        let fixture = make_toolchain_identity_fixture("library-boundary");
        let fqbn = "acme:demo:board";
        let (initial, _) = resolve_toolchain_cache_key_from_root(&fixture.root, fqbn);
        let library_root = fixture.platform_root.join("libraries/Example/src/deep");
        std::fs::create_dir_all(&library_root).expect("library catalogue fixture");
        std::fs::write(library_root.join("example.cpp"), "int example_v1;\n")
            .expect("library source fixture");
        let (after_catalogue_appeared, source) =
            resolve_toolchain_cache_key_from_root(&fixture.root, fqbn);
        assert_eq!(source, ToolchainIdentityResolutionSource::StrongContent);
        assert_eq!(
            after_catalogue_appeared, initial,
            "library catalogues have independent dependency identity"
        );
        // Generic targets deliberately have no metadata-only identity cache,
        // while selected Arduino libraries retain their independent content
        // identity rather than entering the platform key.
        std::fs::write(library_root.join("example.cpp"), "int example_v2;\n")
            .expect("deep library edit");
        let (after_deep_library_edit, source) =
            resolve_toolchain_cache_key_from_root(&fixture.root, fqbn);
        assert_eq!(source, ToolchainIdentityResolutionSource::StrongContent);
        assert_eq!(after_deep_library_edit, initial);
    }

