    #[test]
    fn installed_esp32_toolchain_key_reports_cold_and_warm_preflight_cost() {
        let _identity_scope = process_identity_test_scope();
        super::invalidate_process_toolchain_identity_cache();
        let workspace = Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("../..")
            .canonicalize()
            .expect("workspace root");
        if !workspace.join("packages/esp32/hardware/esp32").is_dir() {
            return;
        }
        let fqbn = "esp32:esp32:esp32c6:FlashSize=16M,PartitionScheme=app3M_fat9M_16MB";
        let cold_started = std::time::Instant::now();
        let (cold, cold_source) = resolve_toolchain_cache_key_from_root(&workspace, fqbn);
        let cold_elapsed = cold_started.elapsed();
        super::process_toolchain_guard_bytes_read().store(0, std::sync::atomic::Ordering::Relaxed);
        let warm_started = std::time::Instant::now();
        let (warm, warm_source) = resolve_toolchain_cache_key_from_root(&workspace, fqbn);
        let warm_elapsed = warm_started.elapsed();
        let warm_guard_bytes = super::process_toolchain_guard_bytes_read()
            .swap(0, std::sync::atomic::Ordering::Relaxed);
        eprintln!(
            "toolchain-key fixture: first={}ms ({:?}) reuse={}ms ({:?})",
            cold_elapsed.as_millis(),
            cold_source,
            warm_elapsed.as_millis(),
            warm_source,
        );
        assert_eq!(cold, warm);
        assert_eq!(
            warm_source,
            ToolchainIdentityResolutionSource::ProcessMemory,
            "installed ESP32 fixture should reuse the process-local proof"
        );
        assert_eq!(
            warm_guard_bytes, 0,
            "unchanged process-memory guard hits must not reread compiler/tool payload bytes"
        );
        assert!(
            warm_elapsed < std::time::Duration::from_secs(8),
            "content-verified toolchain preflight took {}ms",
            warm_elapsed.as_millis()
        );
    }

    #[test]
    fn installed_c6_identity_selects_only_its_compiler_sdk_and_firmware_tool() {
        let _identity_scope = process_identity_test_scope();
        let workspace = Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("../..")
            .canonicalize()
            .expect("workspace root");
        let version_root = workspace.join("packages/esp32/hardware/esp32/3.3.6");
        if !version_root.is_dir() {
            return;
        }
        assert!(
            super::toolchain_identity_cache_directory(&workspace).is_some(),
            "workspace CK Forge identity cache must be a bounded local directory"
        );
        let plan = super::target_tool_plan(&workspace, "esp32", "esp32", "esp32c6", "3.3.6");
        let super::TargetToolSelection::Qualified(roots) = &plan.selection else {
            panic!("installed C6 must resolve an exact tool plan: {plan:?}");
        };
        let labels = roots
            .iter()
            .map(|root| root.label.as_str())
            .collect::<Vec<_>>();
        assert!(labels.iter().any(|label| label.contains("esp-rv32/2511")));
        assert!(
            labels
                .iter()
                .any(|label| label.contains("esp32c6-libs/3.3.6"))
        );
        assert!(
            labels
                .iter()
                .any(|label| label.contains("esptool_py/5.1.0"))
        );
        assert!(!labels.iter().any(|label| {
            label.contains("esp32c3-libs")
                || label.contains("esp32c5-libs")
                || label.contains("esp32s3-libs")
        }));
        let snapshot = super::current_toolchain_identity_snapshot(
            &workspace, "esp32", "esp32", "3.3.6", &plan,
        )
        .expect("C6 selected roots must support a bounded persistent snapshot");
        let inputs =
            super::collect_toolchain_identity_inputs(&workspace, "esp32", "esp32", "3.3.6", &plan)
                .expect("C6 bounded strong inputs");
        let input_paths = inputs
            .directories
            .into_iter()
            .chain(inputs.files)
            .filter_map(|path| super::snapshot_relative_path(&workspace, &path))
            .collect::<std::collections::BTreeSet<_>>();
        let guard =
            super::process_toolchain_identity_guard(&workspace, "esp32", "esp32", "3.3.6", &plan)
                .expect("C6 process guard");
        let guarded_paths = guard
            .entries
            .iter()
            .map(|entry| entry.path.as_str())
            .collect::<std::collections::BTreeSet<_>>();
        assert!(!snapshot.is_empty());
        assert!(snapshot.iter().any(|entry| {
            entry
                .path
                .contains("packages/esp32/tools/esp32c6-libs/3.3.6/")
        }));
        assert!(
            !snapshot
                .iter()
                .any(|entry| entry.path.contains("packages/esp32/tools/esp32s3-libs/"))
        );
        for required in [
            "packages/esp32/tools/esp-rv32/2511/bin/riscv32-esp-elf-gcc.exe",
            "packages/esp32/tools/esp-rv32/2511/libexec/gcc/riscv32-esp-elf/14.2.0/cc1plus.exe",
            "packages/esp32/tools/esp-rv32/2511/libexec/gcc/riscv32-esp-elf/14.2.0/liblto_plugin.dll",
            "packages/esp32/tools/esp-rv32/2511/bin/libstdc++-6.dll",
            "packages/esp32/tools/esp-rv32/2511/riscv32-esp-elf/lib/default.specs",
            "packages/esp32/tools/esp-rv32/2511/lib/gcc/riscv32-esp-elf/14.2.0/rv32imac_zicsr_zifencei/ilp32/libgcc.a",
            "packages/esp32/tools/esp-rv32/2511/riscv32-esp-elf/lib/rv32imac_zicsr_zifencei/ilp32/libstdc++.a",
            "packages/esp32/tools/esp32c6-libs/3.3.6/flags/c_flags",
            "packages/esp32/tools/esptool_py/5.1.0/esptool.exe",
            "packages/esp32/hardware/esp32/3.3.6/tools/gen_esp32part.exe",
            "packages/esp32/hardware/esp32/3.3.6/tools/gen_insights_package.exe",
            "packages/esp32/hardware/esp32/3.3.6/tools/espota.exe",
        ] {
            assert!(
                snapshot.iter().any(|entry| entry.path == required),
                "C6 identity must include {required}"
            );
            assert!(
                input_paths.contains(required),
                "C6 strong input closure must include {required}"
            );
            assert!(
                guarded_paths.contains(required),
                "C6 process guard must include {required}"
            );
        }
        assert!(
            !snapshot.iter().any(|entry| entry
                .path
                .contains("packages/esp32/tools/esp-rv32/2511/picolibc/")),
            "the compiler's unused alternate sysroot must not reintroduce a multi-gigabyte scan"
        );
    }

    #[test]
    fn installed_esp_tool_plans_follow_recipes_for_h2_p4_and_feather_s3() {
        let workspace = Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("../..")
            .canonicalize()
            .expect("workspace root");
        let version_root = workspace.join("packages/esp32/hardware/esp32/3.3.6");
        if !version_root.is_dir() {
            return;
        }

        for (board, raw_options, compiler, sdk, target_tag) in [
            (
                "esp32h2",
                None,
                "esp-rv32",
                "esp32h2-libs",
                "rv32imac_zicsr_zifencei",
            ),
            (
                "esp32p4",
                None,
                "esp-rv32",
                "esp32p4_es-libs",
                "rv32imafc_zicsr_zifencei",
            ),
            (
                "esp32p4",
                Some("ChipVariant=postv3"),
                "esp-rv32",
                "esp32p4-libs",
                "rv32imafc_zicsr_zifencei",
            ),
            (
                "adafruit_feather_esp32s3",
                None,
                "esp-x32",
                "esp32s3-libs",
                "esp32s3",
            ),
        ] {
            let plan = super::target_tool_plan_with_options(
                &workspace,
                "esp32",
                "esp32",
                board,
                raw_options,
                "3.3.6",
            );
            let super::TargetToolSelection::Qualified(roots) = plan.selection else {
                panic!("{board} must resolve through its active recipes: {plan:?}");
            };
            let compiler_root = roots
                .iter()
                .find(|root| root.label.contains(&format!("/{compiler}/")))
                .unwrap_or_else(|| panic!("{board} compiler dependency"));
            assert!(
                roots
                    .iter()
                    .any(|root| root.label.contains(&format!("/{sdk}/"))),
                "{board} SDK dependency"
            );
            assert!(
                roots.iter().any(|root| root.label.contains("/esptool_py/")),
                "{board} compile packaging dependency"
            );
            assert!(matches!(
                &compiler_root.mode,
                super::SelectedToolRootMode::EspCompiler { target_tag: actual }
                    if actual == target_tag
            ));
        }
    }

