    #[tokio::test]
    async fn board_cache_refresh_is_scoped_and_arms_one_shot_rebuild() {
        let temp = tempfile::tempdir().expect("tempdir");
        let sysroot =
            crate::sysroot::Sysroot::init(Some(temp.path().join("sysroot")), "ck-board-cache-test")
                .await
                .expect("sysroot");
        let fqbn = unique_test_board();
        let safe = sanitize_fqbn_for_path(&fqbn);
        let cache_root = std::env::temp_dir().join("CK_Builds");
        let profile_root = cache_root.join(format!("sketch_{}_{}", safe, QUICK_FAST_MODE_SUFFIX));
        let dependency_root = cache_root.join("dep_obj_cache").join(&safe);
        let unrelated = cache_root.join(format!("unrelated_{}", safe));
        let metadata_dir = cache_root.join("metadata");
        let seed_certificate = release_core_seed_certificate_path(&metadata_dir, &safe, "rel");
        let snapshot_root = temp
            .path()
            .join("prebuilt_cores")
            .join(format!("sketch_{}_{}", safe, QUICK_FAST_MODE_SUFFIX));
        std::fs::create_dir_all(&profile_root).expect("profile cache");
        std::fs::create_dir_all(&dependency_root).expect("dependency cache");
        std::fs::create_dir_all(&unrelated).expect("unrelated cache");
        std::fs::create_dir_all(&metadata_dir).expect("metadata cache");
        std::fs::create_dir_all(&snapshot_root).expect("snapshot cache");
        std::fs::write(profile_root.join("core.a"), b"profile").expect("profile fixture");
        std::fs::write(dependency_root.join("object.o"), b"dependency")
            .expect("dependency fixture");
        std::fs::write(snapshot_root.join("core.a"), b"snapshot").expect("snapshot fixture");
        std::fs::write(&seed_certificate, b"seed-certificate")
            .expect("ReleaseCoreSeed certificate fixture");

        let report = request_board_compile_cache_rebuild(&sysroot, &fqbn).expect("cache refresh");
        assert_eq!(report.fqbn, fqbn);
        assert!(report.removed_entries >= 4);
        assert!(report.removed_bytes >= 25);
        assert!(report.force_rebuild_pending);
        assert_eq!(report.reset_scope, "exact-full-fqbn");
        assert!(report.ccache_store_preserved);
        assert!(!report.prebuilt_core_preserved);
        assert!(report.force_ccache_recache);
        let serialized = serde_json::to_value(&report).expect("serialized cache reset evidence");
        assert_eq!(serialized["reset_scope"], "exact-full-fqbn");
        assert_eq!(serialized["ccache_store_preserved"], true);
        assert_eq!(serialized["prebuilt_core_preserved"], false);
        assert_eq!(serialized["force_ccache_recache"], true);
        assert!(!profile_root.exists());
        assert!(!dependency_root.exists());
        assert!(!snapshot_root.exists());
        assert!(!seed_certificate.exists());
        assert!(
            unrelated.exists(),
            "unrelated cache entries must be preserved"
        );
        assert!(force_rebuild_marker_path(&fqbn).is_file());

        let _ = std::fs::remove_file(force_rebuild_marker_path(&fqbn));
        let _ = std::fs::remove_dir_all(unrelated);
    }

    #[tokio::test]
    async fn first_project_cache_reset_preserves_ccache_without_arming_recache() {
        let temp = tempfile::tempdir().expect("tempdir");
        let sysroot = crate::sysroot::Sysroot::init(
            Some(temp.path().join("sysroot")),
            "ck-first-project-test",
        )
        .await
        .expect("sysroot");
        let fqbn = unique_test_board();
        let safe = sanitize_fqbn_for_path(&fqbn);
        let cache_root = std::env::temp_dir().join("CK_Builds");
        let profile_root = cache_root.join(format!("sketch_{}_{}", safe, QUICK_FAST_MODE_SUFFIX));
        let metadata_root = cache_root
            .join("metadata")
            .join(format!("meta_{}_{}.json", safe, QUICK_FAST_MODE_SUFFIX));
        let dependency_root = cache_root.join("dep_obj_cache").join(&safe);
        let snapshot_root = temp
            .path()
            .join("prebuilt_cores")
            .join(format!("sketch_{}_{}", safe, QUICK_FAST_MODE_SUFFIX));
        let ccache_entry = sysroot.root_dir.join("cache/ccache/retained-object");
        for root in [&profile_root, &dependency_root] {
            std::fs::create_dir_all(root).expect("cache fixture");
            std::fs::write(root.join("object.o"), b"object").expect("cache object");
        }
        std::fs::create_dir_all(snapshot_root.join("core")).expect("snapshot core");
        std::fs::write(snapshot_root.join("core/core.a"), b"validated core").expect("core archive");
        write_core_cache_identity(
            &snapshot_root,
            &expected_core_cache_identity(&sysroot, &fqbn, CompileProfile::QuickFast),
        )
        .expect("v6 identity");
        std::fs::create_dir_all(snapshot_root.join("build")).expect("old project snapshot");
        std::fs::write(snapshot_root.join("build/sketch.o"), b"old project")
            .expect("old project object");
        std::fs::write(snapshot_root.join("snapshot_meta.json"), b"{}")
            .expect("old snapshot metadata");
        std::fs::write(snapshot_root.join("snapshot_backup.ino"), b"old code")
            .expect("old snapshot code");
        std::fs::create_dir_all(snapshot_root.join("libraries/WiFi"))
            .expect("old project library snapshot");
        std::fs::write(snapshot_root.join("libraries/WiFi/WiFi.o"), b"old library")
            .expect("old project library object");
        let adjacent_fqbn = format!("{fqbn}:PartitionScheme=adjacent");
        let adjacent_root = sysroot
            .prebuilt_cores_write_root()
            .expect("prebuilt root")
            .join(format!(
                "sketch_{}_{}",
                sanitize_fqbn_for_path(&adjacent_fqbn),
                QUICK_FAST_MODE_SUFFIX
            ));
        std::fs::create_dir_all(&adjacent_root).expect("adjacent target snapshot");
        std::fs::write(adjacent_root.join("sentinel"), b"adjacent")
            .expect("adjacent target sentinel");
        std::fs::create_dir_all(metadata_root.parent().expect("metadata parent"))
            .expect("metadata directory");
        std::fs::write(&metadata_root, b"metadata").expect("metadata fixture");
        let seed_certificate = release_core_seed_certificate_path(
            metadata_root.parent().expect("metadata parent"),
            &safe,
            "rel",
        );
        std::fs::write(&seed_certificate, b"seed-certificate")
            .expect("ReleaseCoreSeed certificate fixture");
        std::fs::write(&ccache_entry, b"global ccache hit").expect("ccache fixture");
        std::fs::create_dir_all(cache_root.as_path()).expect("build cache root");
        std::fs::write(force_rebuild_marker_path(&fqbn), b"force-rebuild-v1")
            .expect("stale hard-refresh marker");

        let report = clear_board_compile_cache_for_first_project(&sysroot, &fqbn)
            .expect("first-project reset");
        assert_eq!(report.fqbn, fqbn);
        assert!(report.removed_entries >= 5);
        assert_eq!(report.reset_scope, "first-project-full-fqbn");
        assert!(report.ccache_store_preserved);
        assert!(!report.prebuilt_core_preserved);
        assert!(!report.force_rebuild_pending);
        assert!(!report.force_ccache_recache);
        assert!(!profile_root.exists());
        assert!(!metadata_root.exists());
        assert!(!seed_certificate.exists());
        assert!(!dependency_root.exists());
        assert!(!snapshot_root.exists());
        assert!(
            ccache_entry.is_file(),
            "global ccache objects model an already-used installation and must remain reusable"
        );
        assert!(
            force_rebuild_marker_paths(&fqbn)
                .into_iter()
                .all(|path| !path.exists()),
            "first-project mode must not inherit or arm a forced recache marker"
        );
    }

    #[test]
    fn ccache_stats_snapshot_is_machine_readable_and_delta_is_fail_closed() {
        let before = parse_ccache_stats_snapshot(
            r#"{"direct_cache_hit":82,"preprocessed_cache_hit":3,"cache_miss":186}"#,
        )
        .expect("parse ccache counters");
        let after = parse_ccache_stats_snapshot(
            r#"{"direct_cache_hit":90,"preprocessed_cache_hit":4,"cache_miss":188}"#,
        )
        .expect("parse later ccache counters");
        assert_eq!(
            before,
            CcacheStatsSnapshot {
                hits: 85,
                misses: 186
            }
        );
        assert_eq!(
            ccache_stats_delta(before, after),
            Some(CcacheStatsSnapshot { hits: 9, misses: 2 })
        );
        assert!(
            ccache_stats_delta(after, before).is_none(),
            "a concurrently reset counter must not produce invented hit metrics"
        );
        assert!(parse_ccache_stats_snapshot("not json").is_none());
    }

    #[test]
    fn fresh_core_header_seed_requires_complete_ready_install_evidence() {
        let allowed = |policy, profile, attempt, injected, meta, backup, ccdb, extra_libraries| {
            verified_fresh_core_header_seed_allowed(
                policy,
                profile,
                attempt,
                injected,
                meta,
                backup,
                ccdb,
                extra_libraries,
            )
        };
        assert!(allowed(
            DependencyResolutionPolicy::Managed,
            CompileProfile::QuickFast,
            0,
            true,
            false,
            false,
            false,
            0,
        ));
        assert!(!allowed(
            DependencyResolutionPolicy::Locked,
            CompileProfile::QuickFast,
            0,
            true,
            false,
            false,
            false,
            0,
        ));
        assert!(!allowed(
            DependencyResolutionPolicy::Managed,
            CompileProfile::SharedFast,
            0,
            true,
            false,
            false,
            false,
            0,
        ));
        for (attempt, injected, meta, backup, ccdb, extra_libraries) in [
            (1, true, false, false, false, 0),
            (0, false, false, false, false, 0),
            (0, true, true, false, false, 0),
            (0, true, false, true, false, 0),
            (0, true, false, false, true, 0),
            (0, true, false, false, false, 1),
        ] {
            assert!(!allowed(
                DependencyResolutionPolicy::Managed,
                CompileProfile::QuickFast,
                attempt,
                injected,
                meta,
                backup,
                ccdb,
                extra_libraries,
            ));
        }
    }

