    #[tokio::test]
    async fn strict_platform_resolver_does_not_allow_sketchbook_or_build_options_to_steal_wifi() {
        let temp = tempfile::tempdir().expect("tempdir");
        let sysroot = temp.path().join("sysroot");
        let platform = sysroot
            .join("packages")
            .join("esp32")
            .join("hardware")
            .join("esp32")
            .join("3.3.6");
        let platform_wifi = platform.join("libraries/WiFi");
        let sketchbook_wifi = sysroot.join("sketchbook/libraries/WiFi");
        let external_hardware = temp.path().join("external-hardware");
        let external_wifi = external_hardware.join("libraries/WiFi");
        for library in [&platform_wifi, &sketchbook_wifi, &external_wifi] {
            std::fs::create_dir_all(library.join("src")).expect("library fixture");
            std::fs::write(library.join("src/WiFi.h"), b"#pragma once\n").expect("WiFi header");
        }
        std::fs::write(
            sketchbook_wifi.join("src/SketchbookOnly.h"),
            b"#pragma once\n",
        )
        .expect("sketchbook-only header");
        std::fs::write(external_wifi.join("src/ExternalOnly.h"), b"#pragma once\n")
            .expect("external-only header");

        let props = HashMap::from([(
            "runtime.platform.path".to_string(),
            platform.to_string_lossy().to_string(),
        )]);
        let trusted_dirs = trusted_platform_library_search_dirs(&props, &sysroot);
        let build = temp.path().join("fresh-build");
        std::fs::create_dir_all(&build).expect("fresh build");
        std::fs::write(
            build.join("build.options.json"),
            serde_json::json!({
                "hardwareFolders": external_hardware.to_string_lossy(),
                "otherLibrariesFolders": sysroot.join("sketchbook/libraries").to_string_lossy(),
            })
            .to_string(),
        )
        .expect("hostile build options");

        let resolved_wifi = resolve_untracked_libraries(
            &build,
            &["wifi.h".to_string()],
            Some(&sysroot),
            &trusted_dirs,
            UntrackedLibraryResolutionPolicy::StrictPlatformOnly,
        )
        .await;
        assert_eq!(
            resolved_wifi,
            vec![std::fs::canonicalize(&platform_wifi).expect("canonical platform WiFi")],
            "the exact platform WiFi must win even when user roots contain a same-name library"
        );

        let escaped_roots = resolve_untracked_libraries(
            &build,
            &["sketchbookonly.h".to_string(), "externalonly.h".to_string()],
            Some(&sysroot),
            &trusted_dirs,
            UntrackedLibraryResolutionPolicy::StrictPlatformOnly,
        )
        .await;
        assert!(
            escaped_roots.is_empty(),
            "strict ready-install resolution must not inspect sketchbook or build.options roots"
        );
    }

    #[tokio::test]
    async fn strict_platform_resolver_rejects_child_link_escape() {
        let temp = tempfile::tempdir().expect("tempdir");
        let sysroot = temp.path().join("sysroot");
        let platform = sysroot
            .join("packages")
            .join("esp32")
            .join("hardware")
            .join("esp32")
            .join("3.3.6");
        let libraries = platform.join("libraries");
        std::fs::create_dir_all(&libraries).expect("platform libraries");
        let outside_wifi = temp.path().join("outside/WiFi");
        std::fs::create_dir_all(outside_wifi.join("src")).expect("outside WiFi");
        std::fs::write(outside_wifi.join("src/WiFi.h"), b"#pragma once\n")
            .expect("outside WiFi header");
        let linked_wifi = libraries.join("WiFi");

        #[cfg(windows)]
        junction::create(&outside_wifi, &linked_wifi).expect("create directory junction escape");
        #[cfg(unix)]
        std::os::unix::fs::symlink(&outside_wifi, &linked_wifi)
            .expect("create directory symlink escape");
        #[cfg(not(any(windows, unix)))]
        return;

        assert!(
            std::fs::canonicalize(&linked_wifi)
                .expect("canonical linked library")
                .starts_with(std::fs::canonicalize(temp.path().join("outside")).expect("outside")),
            "fixture must actually escape the trusted platform library root"
        );
        let props = HashMap::from([(
            "runtime.platform.path".to_string(),
            platform.to_string_lossy().to_string(),
        )]);
        let trusted_dirs = trusted_platform_library_search_dirs(&props, &sysroot);
        let build = temp.path().join("fresh-build");
        std::fs::create_dir_all(&build).expect("fresh build");

        let resolved = resolve_untracked_libraries(
            &build,
            &["wifi.h".to_string()],
            Some(&sysroot),
            &trusted_dirs,
            UntrackedLibraryResolutionPolicy::StrictPlatformOnly,
        )
        .await;

        #[cfg(windows)]
        junction::delete(&linked_wifi).expect("delete directory junction");
        #[cfg(unix)]
        std::fs::remove_file(&linked_wifi).expect("delete directory symlink");

        assert!(
            resolved.is_empty(),
            "a child symlink or junction must not escape exact runtime.platform.path/libraries"
        );
    }

