    #[tokio::test]
    async fn untracked_resolver_chooses_duplicate_header_stably_within_each_root() {
        let temp = tempfile::tempdir().expect("tempdir");
        let sysroot = temp.path().join("sysroot");
        let platform = sysroot.join("packages/vendor/hardware/arch/1.2.3");
        let zulu = platform.join("libraries/ZuluLibrary");
        let alpha = platform.join("libraries/AlphaLibrary");
        // Intentionally create the lexically later library first; filesystem
        // enumeration order must not become library precedence.
        for library in [&zulu, &alpha] {
            std::fs::create_dir_all(library.join("src")).expect("duplicate library");
            std::fs::write(library.join("src/Duplicate.h"), b"#pragma once\n")
                .expect("duplicate header");
        }
        let props = HashMap::from([(
            "runtime.platform.path".to_string(),
            platform.to_string_lossy().to_string(),
        )]);
        let trusted_dirs = trusted_platform_library_search_dirs(&props, &sysroot);
        let build = temp.path().join("fresh-build");
        std::fs::create_dir_all(&build).expect("fresh build");
        let strict = resolve_untracked_libraries(
            &build,
            &["duplicate.h".to_string()],
            Some(&sysroot),
            &trusted_dirs,
            UntrackedLibraryResolutionPolicy::StrictPlatformOnly,
        )
        .await;
        assert!(
            strict.is_empty(),
            "the synthetic path must not guess Arduino's winner for duplicate providers"
        );

        let compatible = resolve_untracked_libraries(
            &build,
            &["duplicate.h".to_string()],
            Some(&sysroot),
            &trusted_dirs,
            UntrackedLibraryResolutionPolicy::Compatible,
        )
        .await;
        assert_eq!(
            compatible,
            vec![std::fs::canonicalize(&alpha).expect("canonical alpha")],
            "legacy compatible resolution remains deterministic within one root"
        );
    }

