    #[tokio::test]
    async fn fresh_core_synthetic_ccdb_has_strict_sketch_contract_and_translation() {
        let temp = tempfile::tempdir().expect("tempdir");
        let project = temp.path().join("fresh_project");
        let build = project.join("build");
        let core = temp.path().join("platform/cores/esp32");
        let variant = temp.path().join("platform/variants/c6");
        for path in [&project, &build, &core, &variant] {
            std::fs::create_dir_all(path).expect("fixture directory");
        }
        let props = HashMap::from([
            (
                "build.project_name".to_string(),
                "fresh_project.ino".to_string(),
            ),
            (
                "runtime.platform.path".to_string(),
                temp.path().join("platform").to_string_lossy().to_string(),
            ),
            ("build.core".to_string(), "esp32".to_string()),
            (
                "build.variant.path".to_string(),
                variant.to_string_lossy().to_string(),
            ),
            (
                "recipe.cpp.o.pattern".to_string(),
                "riscv32-esp-elf-g++ -O1 -g0 -fno-lto -DARDUINO_BOARD=\"ESP32C6_DEV\" -DARDUINO_VARIANT=\"esp32c6\" {includes} -c \"{source_file}\" -o \"{object_file}\""
                    .to_string(),
            ),
        ]);
        let code = r#"#include <WiFi.h>

int helper(int value) {
  return value + 1;
}

void setup() {
  helper(1);
}

void loop() {}
"#;
        let sketch_source = project.join("fresh_project.ino");
        std::fs::write(&sketch_source, code).expect("root sketch fixture");
        let canonical_sketch_source =
            std::fs::canonicalize(&sketch_source).expect("canonical root sketch fixture");
        assert!(
            synthesize_initial_ccdb_with_sketch(
                &props,
                &build,
                temp.path(),
                &[],
                code,
                "esp32:esp32:esp32c6:FlashSize=16M,PartitionScheme=app3M_fat9M_16MB",
                CompileProfile::QuickFast,
                &canonical_sketch_source,
            )
            .await
            .expect("strict synthetic CCDB")
        );

        let ccdb_path = build.join("compile_commands.json");
        let entries: Vec<CompileCommandEntry> =
            serde_json::from_slice(&std::fs::read(&ccdb_path).expect("synthetic compile database"))
                .expect("parse synthetic compile database");
        assert_eq!(entries.len(), 1);
        let contract = validate_ccdb_profile_contract(&entries, CompileProfile::QuickFast)
            .expect("QuickFast profile contract");
        assert!(contract.contains("1 C/C++ command(s) verified"));
        let sketch_entry = &entries[0];
        let expected_sketch = build
            .join("sketch/fresh_project.ino.cpp")
            .to_string_lossy()
            .replace('\\', "/");
        assert_eq!(sketch_entry.file, expected_sketch);
        assert_eq!(
            sketch_entry.directory,
            temp.path().to_string_lossy().replace('\\', "/")
        );
        let command = sketch_entry.arguments.join(" ");
        for flag in ["-O1", "-g0", "-fno-lto"] {
            assert!(command.contains(flag));
        }
        assert!(
            sketch_entry
                .arguments
                .contains(&"-DARDUINO_BOARD=\"ESP32C6_DEV\"".to_string())
        );
        assert!(
            sketch_entry
                .arguments
                .contains(&"-DARDUINO_VARIANT=\"esp32c6\"".to_string())
        );
        assert!(command.contains(&core.to_string_lossy().replace('\\', "/")));
        assert!(command.contains(&variant.to_string_lossy().replace('\\', "/")));
        let translated = std::fs::read_to_string(build.join("sketch/fresh_project.ino.cpp"))
            .expect("translated root sketch");
        assert!(translated.starts_with(&format!(
            "#line 1 \"{}\"\n",
            escape_line_directive_filename(&canonical_sketch_source)
                .expect("escaped canonical sketch path")
        )));
        assert!(!translated.starts_with("#line 1 \"fresh_project.ino\""));

        let wifi = temp.path().join("platform/libraries/WiFi");
        let wifi_header = wifi.join("src/WiFi.h");
        let wifi_source = wifi.join("src/WiFiGeneric.cpp");
        let network = temp.path().join("platform/libraries/Network");
        let network_header = network.join("src/Network.h");
        let network_source = network.join("src/NetworkUdp.cpp");
        std::fs::create_dir_all(wifi_source.parent().expect("WiFi src"))
            .expect("WiFi fixture directory");
        std::fs::create_dir_all(network_source.parent().expect("Network src"))
            .expect("Network fixture directory");
        std::fs::write(&wifi_header, "#pragma once\n").expect("WiFi fixture header");
        std::fs::write(&wifi_source, "#include <Network.h>\n").expect("WiFi fixture source");
        std::fs::write(&network_header, "#pragma once\n").expect("Network fixture header");
        // Deliberately make the transitive relationship circular: every source
        // synthesized in this batch must see the complete include-root closure,
        // not only its own library or whichever dependency was resolved first.
        std::fs::write(&network_source, "#include <Arduino.h>\n#include <WiFi.h>\n")
            .expect("Network fixture source");
        let canonical_wifi = std::fs::canonicalize(&wifi).expect("canonical WiFi fixture");
        let canonical_network = std::fs::canonicalize(&network).expect("canonical Network fixture");
        let library_entries = synthesize_ccdb_entries_for_added_libraries(
            &build,
            &[canonical_wifi, canonical_network],
            sketch_entry,
            &entries,
        )
        .await
        .expect("synthetic transitive library entry");
        assert_eq!(library_entries.len(), 2);
        for library_entry in &library_entries {
            let library_command = library_entry.arguments.join(" ");
            for include_path in [&core, &variant, &wifi.join("src"), &network.join("src")] {
                assert!(
                    library_command.contains(&compiler_safe_path(include_path)),
                    "all same-batch recursive libraries must inherit include path {} in {}",
                    include_path.display(),
                    library_entry.file
                );
            }
            let compiler_facing_fields = format!(
                "{} {} {} {} {}",
                library_entry.directory,
                library_entry.file,
                library_entry.output.as_deref().unwrap_or_default(),
                library_entry.command,
                library_command
            );
            assert!(
                !compiler_facing_fields.contains("//?/")
                    && !compiler_facing_fields.contains(r"\\?\"),
                "CCDB compiler fields must not contain a Windows verbatim namespace: {compiler_facing_fields}"
            );
        }

        assert_eq!(
            compiler_safe_path(Path::new(r"\\?\C:\platform\libraries\WiFi\src")),
            "C:/platform/libraries/WiFi/src"
        );
        assert_eq!(
            compiler_safe_path(Path::new(r"\\?\UNC\server\share\Network\src")),
            "//server/share/Network/src"
        );

        let translated = std::fs::read_to_string(&sketch_entry.file).expect("translated sketch");
        assert!(translated.starts_with(&format!(
            "#line 1 \"{}\"\n#include <Arduino.h>\n",
            escape_line_directive_filename(&canonical_sketch_source)
                .expect("escaped canonical sketch path")
        )));
        assert!(translated.contains("#include <WiFi.h>"));
        assert!(translated.contains("int helper(int value);"));
        assert!(translated.contains("void setup();"));
        assert!(translated.contains("void loop();"));
        assert!(build.join("build_opt.h").is_file());
        assert!(build.join("file_opts").is_file());
    }

    #[tokio::test]
    async fn ready_install_project_reset_preserves_exact_prebuilt_core_only() {
        let temp = tempfile::tempdir().expect("tempdir");
        let sysroot = crate::sysroot::Sysroot::init(
            Some(temp.path().join("sysroot")),
            "ck-ready-install-project-test",
        )
        .await
        .expect("sysroot");
        install_executable_cli_fixture(&sysroot.root_dir);
        let base = unique_test_board();
        let fqbn = format!("{base}:FlashSize=16M,PartitionScheme=app3M_fat9M_16MB,PSRAM=disabled");
        let adjacent_fqbn = format!("{base}:FlashSize=16M,PartitionScheme=fatflash,PSRAM=disabled");
        let safe = sanitize_fqbn_for_path(&fqbn);
        let adjacent_safe = sanitize_fqbn_for_path(&adjacent_fqbn);
        assert_ne!(
            safe, adjacent_safe,
            "complete FQBN options must isolate caches"
        );
        let cache_root = std::env::temp_dir().join("CK_Builds");
        let profile_root = cache_root.join(format!("sketch_{}_{}", safe, QUICK_FAST_MODE_SUFFIX));
        let metadata = cache_root
            .join("metadata")
            .join(format!("meta_{}_{}.json", safe, QUICK_FAST_MODE_SUFFIX));
        let dependency_root = cache_root.join("dep_obj_cache").join(&safe);
        let snapshot_root = sysroot
            .prebuilt_cores_write_root()
            .expect("prebuilt root")
            .join(format!("sketch_{}_{}", safe, QUICK_FAST_MODE_SUFFIX));
        let adjacent_root = sysroot
            .prebuilt_cores_write_root()
            .expect("prebuilt root")
            .join(format!(
                "sketch_{}_{}",
                adjacent_safe, QUICK_FAST_MODE_SUFFIX
            ));
        for root in [&profile_root, &dependency_root] {
            std::fs::create_dir_all(root).expect("cache fixture");
            std::fs::write(root.join("object.o"), b"object").expect("cache object");
        }
        std::fs::create_dir_all(metadata.parent().expect("metadata parent"))
            .expect("metadata directory");
        std::fs::write(&metadata, b"metadata").expect("metadata fixture");
        std::fs::create_dir_all(snapshot_root.join("core")).expect("snapshot core");
        std::fs::write(snapshot_root.join("core/core.a"), b"validated core")
            .expect("snapshot archive");
        write_core_cache_identity(
            &snapshot_root,
            &expected_core_cache_identity(&sysroot, &fqbn, CompileProfile::QuickFast),
        )
        .expect("snapshot v6 identity");
        std::fs::create_dir_all(snapshot_root.join("build/core")).expect("full-build payload");
        std::fs::write(snapshot_root.join("build/core/core.a"), b"project core")
            .expect("project payload");
        std::fs::write(snapshot_root.join("snapshot_meta.json"), b"{}").expect("snapshot metadata");
        std::fs::write(
            snapshot_root.join("snapshot_backup.ino"),
            b"void setup() {}",
        )
        .expect("snapshot source");
        std::fs::create_dir_all(snapshot_root.join("libraries/WiFi"))
            .expect("snapshot project libraries");
        std::fs::write(
            snapshot_root.join("libraries/WiFi/WiFi.cpp.o"),
            b"library object",
        )
        .expect("snapshot library object");
        std::fs::create_dir_all(&adjacent_root).expect("adjacent snapshot");
        std::fs::write(adjacent_root.join("sentinel"), b"other configuration")
            .expect("adjacent sentinel");

        let report = clear_board_compile_cache_for_ready_install_project(&sysroot, &fqbn)
            .expect("ready-install reset");
        assert_eq!(report.reset_scope, "ready-install-project-full-fqbn");
        assert!(report.ccache_store_preserved);
        assert!(report.prebuilt_core_preserved);
        assert!(report.prebuilt_core_validated);
        assert!(!report.force_rebuild_pending);
        assert!(!report.force_ccache_recache);
        assert!(!profile_root.exists());
        assert!(!metadata.exists());
        assert!(!dependency_root.exists());
        assert!(snapshot_root.join("core/core.a").is_file());
        assert!(snapshot_root.join(CORE_CACHE_IDENTITY_FILE).is_file());
        assert!(!snapshot_root.join("build").exists());
        assert!(!snapshot_root.join("snapshot_meta.json").exists());
        assert!(!snapshot_root.join("snapshot_backup.ino").exists());
        assert!(!snapshot_root.join("libraries").exists());
        assert!(adjacent_root.join("sentinel").is_file());
    }

