    #[tokio::test]
    async fn board_cache_refresh_cleans_previous_long_key_without_crossing_configurations() {
        let temp = tempfile::tempdir().expect("tempdir");
        let sysroot = crate::sysroot::Sysroot::init(
            Some(temp.path().join("sysroot")),
            "ck-legacy-board-cache-test",
        )
        .await
        .expect("sysroot");
        let base = unique_test_board();
        let target = format!("{base}:FlashSize=16M,PartitionScheme=app3M_fat9M_16MB,PSRAM=opi");
        let other = format!("{base}:FlashSize=16M,PartitionScheme=fatflash,PSRAM=opi");
        let current_key = fqbn_cache_key(&target);
        let legacy_key = legacy_long_fqbn_cache_key(&target);
        let other_legacy_key = legacy_long_fqbn_cache_key(&other);
        assert_ne!(current_key, legacy_key, "long option slugs changed format");
        assert_ne!(
            legacy_key, other_legacy_key,
            "legacy hashes remain exact-target scoped"
        );

        let cache_root = std::env::temp_dir().join("CK_Builds");
        let profile_root =
            |key: &str| cache_root.join(format!("sketch_{key}_{SHARED_FAST_MODE_SUFFIX}"));
        let current_root = profile_root(&current_key);
        let legacy_root = profile_root(&legacy_key);
        let other_legacy_root = profile_root(&other_legacy_key);
        for root in [&current_root, &legacy_root, &other_legacy_root] {
            std::fs::create_dir_all(root).expect("legacy cache fixture");
            std::fs::write(root.join("marker"), b"cache").expect("cache marker");
        }

        let legacy_marker = cache_root.join(format!("{legacy_key}{FORCE_REBUILD_MARKER_SUFFIX}"));
        std::fs::write(&legacy_marker, b"force-rebuild-v1").expect("legacy rebuild marker");
        assert!(
            force_rebuild_marker_paths(&target).contains(&legacy_marker),
            "a pending refresh from the previous release must still be recognized"
        );

        request_board_compile_cache_rebuild(&sysroot, &target).expect("short-key cache refresh");
        assert!(
            !current_root.exists(),
            "current exact-target cache is cleared"
        );
        assert!(
            !legacy_root.exists(),
            "previous long exact-target cache is cleared"
        );
        assert!(!legacy_marker.exists(), "legacy refresh marker is migrated");
        assert!(
            other_legacy_root.exists(),
            "a different partition configuration must remain untouched"
        );
        assert!(force_rebuild_marker_path(&target).is_file());

        let _ = std::fs::remove_file(force_rebuild_marker_path(&target));
        let _ = std::fs::remove_dir_all(other_legacy_root);
    }

