    #[tokio::test]
    async fn warm_cache_gate_requires_exact_fqbn_and_matching_core_identity() {
        let temp = tempfile::tempdir().expect("tempdir");
        let sysroot = crate::sysroot::Sysroot::init(
            Some(temp.path().join("sysroot")),
            "ck-warm-cache-identity-test",
        )
        .await
        .expect("sysroot");
        install_executable_cli_fixture(&sysroot.root_dir);
        let base = unique_test_board();
        let flash16 = format!("{base}:FlashSize=16M,PartitionScheme=fatflash,PSRAM=opi");
        let cache_root = std::env::temp_dir().join("CK_Builds");
        let base_build = short_build_cache_path(&cache_root, &base, CompileProfile::QuickFast);
        let flash16_build =
            short_build_cache_path(&cache_root, &flash16, CompileProfile::QuickFast);
        let base_project = cache_root.join(format!(
            "sketch_{}_{}",
            sanitize_fqbn_for_path(&base),
            QUICK_FAST_MODE_SUFFIX
        ));
        assert_eq!(
            base_build.file_name(),
            base_project.file_name(),
            "out-of-tree build must retain the source project basename for Arduino artifacts"
        );
        assert_ne!(
            base_build.parent(),
            base_project.as_path().parent(),
            "generated objects must not be nested below the sketch project"
        );

        std::fs::create_dir_all(base_build.join("core")).expect("base core dir");
        std::fs::write(base_build.join("core/core.a"), b"default core").expect("base core");
        let base_identity =
            expected_core_cache_identity(&sysroot, &base, CompileProfile::QuickFast);
        assert_eq!(
            base_identity.schema_version,
            CORE_CACHE_IDENTITY_SCHEMA_VERSION
        );
        assert!(
            !store_prebuilt_core_snapshot(&sysroot, &base, CompileProfile::QuickFast, &base_build,)
                .expect("unlabelled snapshot gate")
        );
        assert!(
            !base_build.join(super::CORE_CACHE_IDENTITY_FILE).exists(),
            "snapshotting must not bless an unverified legacy core archive"
        );
        write_core_cache_identity(&base_build, &base_identity).expect("base identity");
        assert!(
            store_prebuilt_core_snapshot(&sysroot, &base, CompileProfile::QuickFast, &base_build,)
                .expect("canonical snapshot")
        );
        let snapshot_root = sysroot.root_dir.join("prebuilt_cores").join(format!(
            "sketch_{}_{}",
            sanitize_fqbn_for_path(&base),
            QUICK_FAST_MODE_SUFFIX
        ));
        let source_identity = matching_core_cache_identity(&base_build, &base_identity)
            .expect("active Core identity");
        assert!(
            prebuilt_core_snapshot_matches_source_identity(
                &snapshot_root,
                &base_identity,
                &source_identity,
            ),
            "an unchanged sealed snapshot must take the bounded archive-identity fast path"
        );
        assert!(
            store_prebuilt_core_snapshot(&sysroot, &base, CompileProfile::QuickFast, &base_build,)
                .expect("unchanged snapshot fast path")
        );
        std::fs::write(snapshot_root.join("core/core.a"), b"tampered snapshot")
            .expect("tamper snapshot archive");
        assert!(
            !prebuilt_core_snapshot_matches_source_identity(
                &snapshot_root,
                &base_identity,
                &source_identity,
            ),
            "archive tampering must invalidate the fast path"
        );
        assert!(
            store_prebuilt_core_snapshot(&sysroot, &base, CompileProfile::QuickFast, &base_build,)
                .expect("repair tampered snapshot")
        );
        assert_eq!(
            std::fs::read(snapshot_root.join("core/core.a")).expect("repaired snapshot archive"),
            b"default core"
        );
        assert!(
            snapshot_root.join("core/core.a").is_file(),
            "all new snapshots must be written below sysroot.root_dir/prebuilt_cores"
        );
        assert!(has_warm_build_cache(
            &sysroot,
            &base,
            CompileProfile::QuickFast
        ));
        assert!(
            !has_warm_build_cache(&sysroot, &flash16, CompileProfile::QuickFast),
            "a default/base core must not make a 16MB Flash target look warm"
        );

        std::fs::create_dir_all(flash16_build.join("core")).expect("16MB Flash core dir");
        std::fs::write(flash16_build.join("core/core.a"), b"16MB Flash core")
            .expect("16MB Flash core");
        assert!(
            !has_warm_build_cache(&sysroot, &flash16, CompileProfile::QuickFast),
            "an unlabelled core archive is not a trustworthy warm cache"
        );
        write_core_cache_identity(
            &flash16_build,
            &expected_core_cache_identity(&sysroot, &flash16, CompileProfile::QuickFast),
        )
        .expect("16MB Flash identity");
        assert!(has_warm_build_cache(
            &sysroot,
            &flash16,
            CompileProfile::QuickFast
        ));

        let _ = std::fs::remove_dir_all(&base_build);
        let _ = std::fs::remove_dir_all(&flash16_build);
    }

    #[tokio::test]
    async fn warm_cache_reads_scoped_legacy_root_without_crossing_other_roots() {
        let temp = tempfile::tempdir().expect("tempdir");
        let sysroot = crate::sysroot::Sysroot::init(
            Some(temp.path().join("sysroot")),
            "ck-legacy-prebuilt-read-test",
        )
        .await
        .expect("sysroot");
        install_executable_cli_fixture(&sysroot.root_dir);
        // A non-empty canonical root models an upgrade where atomic migration
        // is intentionally not allowed. The sibling legacy root remains a
        // compatibility read location, while arbitrary roots remain invisible.
        std::fs::write(
            sysroot.root_dir.join("prebuilt_cores/canonical-marker"),
            b"new-cache",
        )
        .expect("canonical marker");

        let fqbn = unique_test_board();
        let profile_name = format!(
            "sketch_{}_{}",
            sanitize_fqbn_for_path(&fqbn),
            QUICK_FAST_MODE_SUFFIX
        );
        let legacy = temp.path().join("prebuilt_cores").join(&profile_name);
        let unrelated = temp.path().join("other/prebuilt_cores").join(&profile_name);
        for root in [&legacy, &unrelated] {
            std::fs::create_dir_all(root.join("core")).expect("legacy core root");
            std::fs::write(root.join("core/core.a"), b"verified core").expect("core archive");
        }
        let expected = expected_core_cache_identity(&sysroot, &fqbn, CompileProfile::QuickFast);
        write_core_cache_identity(&legacy, &expected).expect("legacy identity");
        assert!(has_warm_build_cache(
            &sysroot,
            &fqbn,
            CompileProfile::QuickFast
        ));

        std::fs::remove_file(legacy.join(super::CORE_CACHE_IDENTITY_FILE))
            .expect("remove only trusted legacy identity");
        write_core_cache_identity(&unrelated, &expected).expect("unrelated identity");
        assert!(
            !has_warm_build_cache(&sysroot, &fqbn, CompileProfile::QuickFast),
            "cache lookup must never cross into an unrelated prebuilt_cores root"
        );
    }

    #[test]
    fn canonicalize_ignores_whitespace_and_comments() {
        let a = r#"
int x = 1; // c1
Serial.println(x);
"#;
        let b = r#"int   x=1;/* c2 */Serial.println( x );"#;
        assert_eq!(
            canonicalize_code_for_cache(a),
            canonicalize_code_for_cache(b)
        );
    }

    #[test]
    fn canonicalize_keeps_string_literal_semantics() {
        let a = r#"Serial.println("HELLO");"#;
        let b = r#"Serial.println("HELLO ");"#;
        assert_ne!(
            canonicalize_code_for_cache(a),
            canonicalize_code_for_cache(b)
        );
    }

    #[test]
    fn canonicalize_keeps_identifier_boundaries() {
        let a = "int a = 1; int b = 2;";
        let b = "inta=1;intb=2;";
        assert_ne!(
            canonicalize_code_for_cache(a),
            canonicalize_code_for_cache(b)
        );
    }

    #[test]
    fn exact_cache_rejects_punctuator_boundary_collisions() {
        let increment_right = "int value = p + ++q;\n";
        let increment_left = "int value = p++ + q;\n";

        assert_eq!(
            canonicalize_code_for_cache(increment_right),
            canonicalize_code_for_cache(increment_left),
            "fixture must demonstrate the lossy canonicalizer collision"
        );
        assert!(!exact_cache_source_matches(increment_right, increment_left));
    }

