    #[tokio::test]
    async fn foreground_build_can_prime_dependency_objects_from_its_compilation_database() {
        let temp = tempfile::tempdir().expect("tempdir");
        let build = temp.path().join("build");
        let source = temp.path().join("WiFi.cpp");
        let header = temp.path().join("internal").join("WiFiPrivate.h");
        let object = build.join("libraries").join("WiFi").join("WiFi.cpp.o");
        std::fs::create_dir_all(object.parent().expect("object parent"))
            .expect("create object parent");
        std::fs::create_dir_all(header.parent().expect("header parent"))
            .expect("create header parent");
        std::fs::write(&source, b"void wifi_dependency() {}\n").expect("source");
        std::fs::write(&header, b"#define WIFI_PRIVATE 1\n").expect("header");
        std::fs::write(&object, b"compiled dependency object").expect("object");
        std::fs::write(
            object.with_extension("d"),
            format!(
                "{}: ../WiFi.cpp ../internal/WiFiPrivate.h\n",
                object.display()
            ),
        )
        .expect("dependency evidence");

        let sketch_source = build.join("sketch").join("sketch.ino.cpp");
        let sketch_object = build.join("sketch").join("sketch.ino.cpp.o");
        std::fs::create_dir_all(sketch_object.parent().expect("sketch object parent"))
            .expect("create sketch object parent");
        std::fs::write(&sketch_source, b"void setup() {}\nvoid loop() {}\n")
            .expect("sketch source");
        std::fs::write(&sketch_object, b"compiled sketch object").expect("sketch object");

        let entry = CompileCommandEntry {
            // Deliberately differs from the trusted cache base: compiler
            // depfiles resolve relative paths against the CCDB command's
            // working directory, while the trusted base remains cache identity.
            directory: build.to_string_lossy().to_string(),
            arguments: vec![
                "riscv32-esp-elf-g++".into(),
                "-DARDUINO_ESP32C5_DEV".into(),
                "-c".into(),
                source.to_string_lossy().to_string(),
                "-o".into(),
                object.to_string_lossy().to_string(),
            ],
            command: String::new(),
            file: source.to_string_lossy().to_string(),
            output: Some(object.to_string_lossy().to_string()),
        };
        let sketch_entry = CompileCommandEntry {
            directory: build.to_string_lossy().to_string(),
            arguments: vec![
                "riscv32-esp-elf-g++".into(),
                "-DARDUINO_ESP32C5_DEV".into(),
                "-c".into(),
                sketch_source.to_string_lossy().to_string(),
                "-o".into(),
                sketch_object.to_string_lossy().to_string(),
            ],
            command: String::new(),
            file: sketch_source.to_string_lossy().to_string(),
            output: Some(sketch_object.to_string_lossy().to_string()),
        };
        std::fs::write(
            build.join("compile_commands.json"),
            serde_json::to_vec(&vec![entry.clone(), sketch_entry]).expect("serialize ccdb"),
        )
        .expect("write ccdb");

        let fqbn = unique_test_board();
        let cache_identity = "test-toolchain-v1";
        let cache_path =
            dependency_object_cache_path(cache_identity, &fqbn, &entry, &source, temp.path())
                .expect("dependency cache path");
        let _ = std::fs::remove_file(&cache_path);

        let count =
            prime_dependency_object_cache_from_ccdb(cache_identity, &fqbn, &build, temp.path())
                .await
                .expect("prime dependency cache");
        assert_eq!(count, 1);
        assert_eq!(
            std::fs::read(&cache_path).expect("cached object"),
            b"compiled dependency object"
        );
        assert!(cache_path.with_extension("d").is_file());
        let proof: DependencyObjectProof = serde_json::from_slice(
            &std::fs::read(cache_path.with_extension("proof.json")).expect("cache proof"),
        )
        .expect("parse cache proof");
        assert_eq!(proof.schema_version, 3);
        assert_eq!(
            proof.dependency_base,
            dependency_base_key(temp.path()).expect("bound dependency base")
        );

        std::fs::remove_file(&object).expect("remove original dependency object");
        std::fs::remove_file(object.with_extension("d")).expect("remove original depfile");
        assert!(
            restore_dependency_object_from_cache(
                cache_identity,
                &fqbn,
                &entry,
                &source,
                &object,
                temp.path(),
            )
            .await
            .expect("restore dependency object")
        );
        assert_eq!(
            std::fs::read(&object).expect("restored object"),
            b"compiled dependency object"
        );
        assert!(object.with_extension("d").is_file());

        let wrong_base = temp.path().join("wrong-dependency-base");
        std::fs::create_dir_all(&wrong_base).expect("wrong dependency base");
        std::fs::remove_file(&object).expect("remove object before wrong-base restore");
        std::fs::remove_file(object.with_extension("d"))
            .expect("remove depfile before wrong-base restore");
        assert!(
            !restore_dependency_object_from_cache(
                cache_identity,
                &fqbn,
                &entry,
                &source,
                &object,
                &wrong_base,
            )
            .await
            .expect("a different explicit base must fail closed")
        );
        assert!(!object.exists());

        assert!(
            restore_dependency_object_from_cache(
                cache_identity,
                &fqbn,
                &entry,
                &source,
                &object,
                temp.path(),
            )
            .await
            .expect("restore after wrong-base rejection")
        );

        std::thread::sleep(std::time::Duration::from_millis(20));
        std::fs::write(&header, b"#define WIFI_PRIVATE 200\n").expect("changed deep header");
        std::fs::remove_file(&object).expect("remove object before stale restore");
        std::fs::remove_file(object.with_extension("d"))
            .expect("remove depfile before stale restore");
        assert!(
            !restore_dependency_object_from_cache(
                cache_identity,
                &fqbn,
                &entry,
                &source,
                &object,
                temp.path(),
            )
            .await
            .expect("stale nested header cache must be rejected")
        );
        assert!(!object.exists());
        let _ = std::fs::remove_file(&cache_path);
        let _ = std::fs::remove_file(cache_path.with_extension("d"));
    }

    #[tokio::test]
    async fn fast_relink_proof_store_preserves_exact_evidence_for_ccdb_relative_depfiles() {
        let temp = tempfile::tempdir().expect("tempdir");
        let sysroot = temp.path().join("sysroot");
        let build = temp.path().join("build");
        let library = sysroot.join("libraries").join("WiFi");
        let source = library.join("src").join("WiFi.cpp");
        let header = library.join("src").join("internal").join("WiFiPrivate.h");
        let object = build.join("libraries").join("WiFi").join("WiFi.cpp.o");
        std::fs::create_dir_all(source.parent().expect("source parent")).expect("source directory");
        std::fs::create_dir_all(header.parent().expect("header parent")).expect("header directory");
        std::fs::create_dir_all(object.parent().expect("object parent")).expect("object directory");
        std::fs::write(&source, b"void wifi_dependency() {}\n").expect("source");
        std::fs::write(&header, b"#define WIFI_PRIVATE 1\n").expect("header");
        std::fs::write(&object, b"compiled dependency object").expect("object");

        // This is the form emitted by ccache in the real ESP32 Fast Relink
        // build: dependency paths are relative to the CCDB command's working
        // directory, not to CK's sysroot/Arduino data directory.
        std::fs::write(
            object.with_extension("d"),
            concat!(
                "WiFi.cpp.o: ../sysroot/libraries/WiFi/src/WiFi.cpp \\\n",
                " ../sysroot/libraries/WiFi/src/internal/WiFiPrivate.h\n",
            ),
        )
        .expect("ccdb-relative dependency evidence");

        let entry = CompileCommandEntry {
            directory: build.to_string_lossy().to_string(),
            arguments: vec![
                "riscv32-esp-elf-g++".into(),
                "-DARDUINO_ESP32C6_DEV".into(),
                "-c".into(),
                source.to_string_lossy().to_string(),
                "-o".into(),
                object.to_string_lossy().to_string(),
            ],
            command: String::new(),
            file: source.to_string_lossy().to_string(),
            output: Some(object.to_string_lossy().to_string()),
        };
        std::fs::write(
            build.join("compile_commands.json"),
            serde_json::to_vec(&vec![entry.clone()]).expect("serialize ccdb"),
        )
        .expect("write ccdb");

        assert_ne!(
            std::fs::canonicalize(&sysroot).expect("canonical sysroot"),
            std::fs::canonicalize(&build).expect("canonical build"),
            "the regression fixture must not accidentally share the dependency base"
        );
        let signature_before = build_dependency_content_signature(&build, &sysroot)
            .expect("Fast Relink must commit complete dependency evidence");

        let fqbn = unique_test_board();
        let cache_identity = "fast-relink-exact-regression-v1";
        let stored =
            prime_dependency_object_cache_from_ccdb(cache_identity, &fqbn, &build, &sysroot)
                .await
                .expect("store strong dependency proof after Fast Relink");
        assert_eq!(stored, 1);

        let cache_path =
            dependency_object_cache_path(cache_identity, &fqbn, &entry, &source, &sysroot)
                .expect("trusted-base-bound dependency cache path");
        assert!(cache_path.is_file(), "proof store must retain the object");
        assert!(
            cache_path.with_extension("d").is_file(),
            "proof store must retain the depfile"
        );
        assert!(
            cache_path.with_extension("proof.json").is_file(),
            "proof store must commit its machine-readable proof"
        );

        let signature_after = build_dependency_content_signature(&build, &sysroot)
            .expect("an identical compile must still have complete dependency evidence");
        assert_eq!(
            signature_before, signature_after,
            "proof storage is read-only with respect to Exact Match evidence"
        );

        let _ = std::fs::remove_file(&cache_path);
        let _ = std::fs::remove_file(cache_path.with_extension("d"));
        let _ = std::fs::remove_file(cache_path.with_extension("proof.json"));
    }

    #[test]
    fn compilation_dependency_signature_tracks_content_and_missing_deep_headers() {
        let temp = tempfile::tempdir().expect("tempdir");
        let build = temp.path().join("build");
        let source = temp.path().join("Library.cpp");
        let header = temp.path().join("src").join("internal").join("Private.h");
        let object = build.join("libraries").join("Demo").join("Library.cpp.o");
        std::fs::create_dir_all(header.parent().unwrap()).unwrap();
        std::fs::create_dir_all(object.parent().unwrap()).unwrap();
        std::fs::write(&source, b"void library_value() {}\n").unwrap();
        std::fs::write(&header, b"#define PRIVATE_VALUE 1\n").unwrap();
        std::fs::write(&object, b"object").unwrap();
        std::fs::write(
            object.with_extension("d"),
            format!(
                "{}: {} {}\n",
                object.display(),
                source.display(),
                header.display()
            ),
        )
        .unwrap();
        let entry = CompileCommandEntry {
            directory: temp.path().to_string_lossy().to_string(),
            arguments: vec![
                "g++".into(),
                "-c".into(),
                source.to_string_lossy().to_string(),
                "-o".into(),
                object.to_string_lossy().to_string(),
            ],
            command: String::new(),
            file: source.to_string_lossy().to_string(),
            output: Some(object.to_string_lossy().to_string()),
        };
        std::fs::write(
            build.join("compile_commands.json"),
            serde_json::to_vec(&vec![entry]).unwrap(),
        )
        .unwrap();

        let first = build_dependency_content_signature(&build, temp.path())
            .expect("complete dependency proof");
        std::fs::write(&header, b"#define PRIVATE_VALUE 2\n").unwrap();
        let second = build_dependency_content_signature(&build, temp.path())
            .expect("updated dependency proof");
        assert_ne!(
            first, second,
            "equal-length header edits must change evidence"
        );

        std::fs::remove_file(&header).unwrap();
        assert!(
            build_dependency_content_signature(&build, temp.path()).is_none(),
            "deleted dependencies cannot retain exact-match evidence"
        );
    }

    #[test]
    fn native_relink_dependency_signature_is_actual_graph_only_and_rejects_libraries() {
        let temp = tempfile::tempdir().expect("tempdir");
        let build = temp.path().join("build");
        let core_root = temp
            .path()
            .join("packages/arduino/hardware/avr/1.8.6/cores/arduino");
        let source = core_root.join("wiring.c");
        let header = core_root.join("Arduino.h");
        let object = build.join("core/wiring.c.o");
        std::fs::create_dir_all(&core_root).expect("core root");
        std::fs::create_dir_all(object.parent().expect("object parent")).expect("object root");
        std::fs::write(&source, b"void wiring_value(void) {}\n").expect("source");
        std::fs::write(&header, b"#define ARDUINO_VALUE 1\n").expect("header");
        std::fs::write(&object, b"object").expect("object");
        std::fs::write(
            object.with_extension("d"),
            format!(
                "{}: {} {}\n",
                object.display(),
                source.display(),
                header.display()
            ),
        )
        .expect("depfile");
        let core_entry = CompileCommandEntry {
            directory: temp.path().to_string_lossy().to_string(),
            arguments: vec![
                "avr-gcc".into(),
                "-c".into(),
                source.to_string_lossy().to_string(),
                "-o".into(),
                object.to_string_lossy().to_string(),
            ],
            command: String::new(),
            file: source.to_string_lossy().to_string(),
            output: Some(object.to_string_lossy().to_string()),
        };
        std::fs::write(
            build.join("compile_commands.json"),
            serde_json::to_vec(&vec![core_entry]).expect("ccdb JSON"),
        )
        .expect("ccdb");

        let first = build_native_relink_dependency_content_signature(&build, temp.path())
            .expect("Core-only graph is eligible");
        std::fs::write(&header, b"#define ARDUINO_VALUE 2\n").expect("header edit");
        let second = build_native_relink_dependency_content_signature(&build, temp.path())
            .expect("edited Core-only graph remains measurable");
        assert_ne!(first, second, "actual dependency bytes must remain bound");

        let library = temp.path().join("libraries/Demo");
        let library_source = library.join("src/Demo.cpp");
        let library_object = build.join("libraries/Demo/Demo.cpp.o");
        std::fs::create_dir_all(library_source.parent().expect("library source parent"))
            .expect("library source root");
        std::fs::create_dir_all(library_object.parent().expect("library object parent"))
            .expect("library object root");
        std::fs::write(
            library.join("library.properties"),
            "name=Demo\nversion=1.0.0\n",
        )
        .expect("library manifest");
        std::fs::write(&library_source, b"void demo() {}\n").expect("library source");
        std::fs::write(&library_object, b"library object").expect("library object");
        std::fs::write(
            library_object.with_extension("d"),
            format!(
                "{}: {}\n",
                library_object.display(),
                library_source.display()
            ),
        )
        .expect("library depfile");
        let library_entry = CompileCommandEntry {
            directory: temp.path().to_string_lossy().to_string(),
            arguments: vec![
                "avr-g++".into(),
                "-c".into(),
                library_source.to_string_lossy().to_string(),
                "-o".into(),
                library_object.to_string_lossy().to_string(),
            ],
            command: String::new(),
            file: library_source.to_string_lossy().to_string(),
            output: Some(library_object.to_string_lossy().to_string()),
        };
        std::fs::write(
            build.join("compile_commands.json"),
            serde_json::to_vec(&vec![library_entry]).expect("library ccdb JSON"),
        )
        .expect("library ccdb");
        assert!(
            build_native_relink_dependency_content_signature(&build, temp.path()).is_none(),
            "a library translation unit must leave the Arduino.h-only NativeRelink lane"
        );
        assert!(
            build_native_relink_dependency_content_signature_for_library_mode(
                &build,
                temp.path(),
                true,
            )
            .is_some(),
            "the bounded-library NativeRelink lane must retain complete dependency evidence"
        );
    }

    #[test]
    fn code_warmup_cache_requires_unchanged_dependency_evidence() {
        let temp = tempfile::tempdir().expect("tempdir");
        let build = temp.path().join("build");
        let metadata = temp.path().join("metadata");
        let source = temp.path().join("Library.cpp");
        let header = temp.path().join("src").join("internal").join("Private.h");
        let object = build.join("libraries").join("Demo").join("Library.cpp.o");
        let warmup_meta = metadata.join("warmup_meta.json");
        let warmup_success = metadata.join("warmup_success");
        std::fs::create_dir_all(header.parent().unwrap()).unwrap();
        std::fs::create_dir_all(object.parent().unwrap()).unwrap();
        std::fs::create_dir_all(build.join("core")).unwrap();
        std::fs::create_dir_all(&metadata).unwrap();
        std::fs::write(&source, b"void library_value() {}\n").unwrap();
        std::fs::write(&header, b"#define PRIVATE_VALUE 1\n").unwrap();
        std::fs::write(&object, b"object").unwrap();
        std::fs::write(build.join("core").join("core.a"), b"archive").unwrap();
        std::fs::write(
            object.with_extension("d"),
            format!(
                "{}: {} {}\n",
                object.display(),
                source.display(),
                header.display()
            ),
        )
        .unwrap();
        let entry = CompileCommandEntry {
            directory: temp.path().to_string_lossy().to_string(),
            arguments: vec![
                "g++".into(),
                "-c".into(),
                source.to_string_lossy().to_string(),
                "-o".into(),
                object.to_string_lossy().to_string(),
            ],
            command: String::new(),
            file: source.to_string_lossy().to_string(),
            output: Some(object.to_string_lossy().to_string()),
        };
        std::fs::write(
            build.join("compile_commands.json"),
            serde_json::to_vec(&vec![entry]).unwrap(),
        )
        .unwrap();

        let fqbn = "esp32:esp32:esp32c6:FlashSize=16M";
        let identity = CoreCacheIdentity {
            schema_version: 6,
            fqbn: fqbn.to_string(),
            profile: "qfast2".to_string(),
            signature: "test-core-signature".to_string(),
            managed_cli_identity_available: true,
            core_archive_sha256: String::new(),
        };
        write_core_cache_identity(&build, &identity).unwrap();
        write_warmup_cache_meta(
            &warmup_meta,
            fqbn,
            CompileProfile::QuickFast,
            Some("same-code".to_string()),
            &build,
            temp.path(),
        )
        .unwrap();
        std::fs::write(&warmup_success, b"ready").unwrap();

        assert!(matching_code_warmup_cache_exists(
            &warmup_meta,
            &warmup_success,
            &build,
            fqbn,
            CompileProfile::QuickFast,
            "same-code",
            &identity,
            temp.path(),
        ));
        assert!(!matching_code_warmup_cache_exists(
            &warmup_meta,
            &warmup_success,
            &build,
            fqbn,
            CompileProfile::QuickFast,
            "different-code",
            &identity,
            temp.path(),
        ));

        std::fs::write(&header, b"#define PRIVATE_VALUE 2\n").unwrap();
        assert!(!matching_code_warmup_cache_exists(
            &warmup_meta,
            &warmup_success,
            &build,
            fqbn,
            CompileProfile::QuickFast,
            "same-code",
            &identity,
            temp.path(),
        ));
    }

